/* SC 144 A&P — exam-suite drill content, keyed by BodyQuest unit (1-11).
   Authored and adversarially fact-checked per unit.
   Assembled by scratchpad/assemble_herzing_drills.py */
window.FINAL_DRILLS_BY_EXAM={"1":{"labs":[{"labs":[["Cell volume","up"],["Intracellular solute concentration","down"],["Extracellular osmolarity compared with cytosol","down"],["Membrane integrity","abn"]],"opts":["Cell placed in a hypotonic solution","Cell placed in an isotonic solution","Cell placed in a hypertonic solution","Cell using primary active transport"],"c":0,"why":"The membrane blocks the solute but not water, so the only way the two compartments can equalize is for water to move toward the side with more solute. Fewer particles outside means net water entry, and the swelling itself dilutes the cytosol before the membrane finally tears.","week":"1"},{"labs":[["Cell volume","n"],["Net water movement","n"],["Hemolysis","n"],["Extracellular osmolarity compared with cytosol","n"]],"opts":["Cell placed in 0.9 percent NaCl, an isotonic solution","Cell placed in distilled water","Cell placed in 5 percent NaCl","Cell with its aquaporins blocked"],"c":0,"why":"Osmosis never actually stops at the molecular level. Isotonic means water enters and leaves at equal rates, so the entirely normal panel is itself the answer, which is why a flat set of findings should not be read as no transport occurring.","week":"1"},{"labs":[["Cell volume","down"],["Cell surface contour","abn"],["Extracellular osmolarity compared with cytosol","up"],["Intracellular solute concentration","up"]],"opts":["Hypertonic solution causing crenation","Hypotonic solution causing hemolysis","Isotonic solution at equilibrium","Active transport of water out of the cell"],"c":0,"why":"A higher outside concentration of nonpenetrating solute pulls water out. The plasma membrane then has more surface area than the shrunken volume needs, so it puckers into the scalloped crenated shape rather than simply getting smaller.","week":"1"},{"labs":[["Cellular ATP","down"],["Intracellular sodium","up"],["Intracellular potassium","down"],["Cell volume","up"]],"opts":["Failure of the sodium-potassium pump","Failure of simple diffusion","Failure of osmosis","Excessive facilitated diffusion of potassium"],"c":0,"why":"The sodium-potassium ATPase is primary active transport and stops the moment ATP runs out. Sodium then leaks in and potassium leaks out down their gradients, and the net gain of intracellular particles drags water in behind them.","week":"1"},{"labs":[["ATP consumed by the transporter","n"],["Rate of glucose entry as extracellular glucose rises","up"],["Rate of entry once all carriers are occupied","n"],["Intracellular glucose compared with extracellular glucose","down"]],"opts":["Facilitated diffusion through a carrier protein","Simple diffusion through the bilayer","Primary active transport","Exocytosis"],"c":0,"why":"Saturation is the fingerprint of a protein carrier: once every binding site is occupied the rate cannot climb further no matter how steep the gradient. No ATP is spent because the solute is still moving downhill.","week":"1"},{"labs":[["ATP consumed","n"],["Lipid solubility of the molecule","up"],["Transport rate as the gradient steepens","up"],["Saturation at high concentration","n"]],"opts":["Simple diffusion through the phospholipid bilayer","Facilitated diffusion through a channel","Osmosis","Secondary active transport"],"c":0,"why":"Small nonpolar molecules dissolve straight through the hydrophobic tails, so there is no protein to run out of. That is why the rate keeps climbing with the gradient instead of leveling off the way a carrier-mediated process does.","week":"1"},{"labs":[["Nuclear DNA content","up"],["Chromosome number","n"],["Centrosome number","up"],["Chromosome condensation","n"]],"opts":["S phase of interphase","G1 phase","Metaphase","Telophase"],"c":0,"why":"Replication doubles the DNA mass, but a chromosome with two sister chromatids attached at one centromere is still counted as one chromosome, so the number stays at forty-six. Condensation into visible rods does not happen until prophase.","week":"1"},{"labs":[["Chromosome condensation","up"],["Nuclear envelope","abn"],["Spindle tension on the kinetochores","up"],["Sister chromatids still joined at the centromere","n"],["Chromosome position along the cell equator","abn"]],"opts":["Metaphase","Anaphase","Prophase","Cytokinesis"],"c":0,"why":"The defining moment is chromosomes held single file on the equator with spindle fibers pulling equally from both poles. The chromatids have not separated yet, and that single detail is what distinguishes metaphase from anaphase.","week":"1"},{"labs":[["Rough endoplasmic reticulum","up"],["Golgi complex","up"],["Secretory vesicles near the plasma membrane","up"],["Smooth endoplasmic reticulum","n"]],"opts":["A cell specialized for exporting protein","A cell specialized for steroid hormone synthesis","A cell specialized for ATP production","A cell specialized for intracellular digestion"],"c":0,"why":"Ribosomes studding the rough ER build proteins destined for export or for membranes, and the Golgi is the downstream station that modifies and sorts them. Heavy traffic in that pathway with an unremarkable smooth ER points to protein secretion rather than lipid work.","week":"1"},{"labs":[["Smooth endoplasmic reticulum","up"],["Rough endoplasmic reticulum","down"],["Membrane-bound ribosomes","down"],["Steroid hormone output","up"]],"opts":["Smooth ER, the site of lipid and steroid synthesis and detoxification","Rough ER, the site of protein synthesis","Lysosome, the site of hydrolytic digestion","Peroxisome, the site of free radical neutralization"],"c":0,"why":"Smooth ER carries no ribosomes at all, which is exactly why membrane-bound ribosome counts fall as it expands. Its enzymes assemble lipids and steroid hormones and detoxify drugs, so adrenal cortex and liver cells build it up.","week":"1"},{"labs":[["Mitochondrial density","up"],["Cristae surface area","up"],["Oxygen consumption","up"],["ATP output","up"]],"opts":["Cardiac muscle, a continuously working aerobic tissue","A mature red blood cell","A cell relying entirely on anaerobic glycolysis","A cell arrested in G0"],"c":0,"why":"Cristae are inner membrane folds that multiply the surface holding the electron transport chain, so tissues that never rest pack in both mitochondria and folds. A mature red blood cell is the opposite extreme because it has no mitochondria whatsoever.","week":"1"},{"labs":[["Number of strands","down"],["Uracil content","up"],["Thymine content","down"],["Ribose content","up"]],"opts":["Messenger RNA","DNA","A structural protein","A membrane phospholipid"],"c":0,"why":"RNA differs from DNA at exactly three points: one strand instead of two, ribose instead of deoxyribose, and uracil substituting for thymine. Those three findings together identify the molecule as RNA no matter what job it is doing.","week":"1"}],"pairs":[{"clue":"The organelle that modifies, sorts, and packages finished proteins into vesicles for shipping","a":"Golgi apparatus","b":"Rough endoplasmic reticulum","why":"The rough ER builds and folds the protein; the Golgi is the next station downstream, adding sugar groups and deciding which vesicle the finished product leaves in. Students merge them because both handle the same molecule minutes apart.","week":"1","c":0},{"clue":"The movement of WATER across a selectively permeable membrane toward the more concentrated solution","a":"Osmosis","b":"Diffusion of solute","why":"Osmosis is a special case of diffusion in which the solvent moves precisely because the solute cannot. Naming which particle is actually crossing the membrane is the entire distinction.","week":"1","c":0},{"clue":"The solution that makes a red blood cell swell and burst","a":"Hypotonic solution","b":"Hypertonic solution","why":"The prefix always describes the SOLUTION, never the cell. Hypotonic means fewer nonpenetrating solutes outside than inside, so water moves inward; students who read the prefix as describing the cell reverse every tonicity question.","week":"1","c":0},{"clue":"Transport that moves a solute uphill against its concentration gradient by directly splitting ATP","a":"Primary active transport","b":"Facilitated diffusion","why":"Both use a membrane protein, which is why they look alike. Only active transport pushes against the gradient and pays for it; facilitated diffusion is passive and stops the instant the gradient is gone.","week":"1","c":0},{"clue":"Passive movement of a solute through a specific carrier with no ATP spent by that carrier","a":"Facilitated diffusion","b":"Secondary active transport","why":"Neither one burns ATP at the carrier itself, so the ATP question does not separate them. The difference is direction: secondary active transport hauls its passenger uphill using a gradient that ATP built somewhere else.","week":"1","c":0},{"clue":"The phase of mitosis in which sister chromatids are pulled apart toward opposite poles","a":"Anaphase","b":"Metaphase","why":"Metaphase is alignment with the chromatids still joined; anaphase begins the instant the centromeres split. The images look similar because both show a fully formed spindle, but only one shows separated chromatids.","week":"1","c":0},{"clue":"The longest portion of the cell cycle, when the cell grows, functions, and replicates its DNA","a":"Interphase","b":"Prophase","why":"Interphase (G1, S, and G2) occupies roughly ninety percent of the cycle and is where all the real work happens. Mitosis is the brief division event, not the cell's normal state.","week":"1","c":0},{"clue":"Copying the base sequence of a gene into messenger RNA inside the nucleus","a":"Transcription","b":"Translation","why":"Transcription stays in the same chemical language, nucleic acid to nucleic acid, and never leaves the nucleus. Translation converts to a different language, nucleotides to amino acids, and happens at the ribosome.","week":"1","c":0},{"clue":"The three-base sequence carried on messenger RNA that specifies one amino acid","a":"Codon","b":"Anticodon","why":"The codon rides on mRNA and carries the instruction; the anticodon is the complementary triplet on the transfer RNA that base-pairs with it and delivers the matching amino acid.","week":"1","c":0},{"clue":"The membrane-bound sac of acid hydrolases that digests worn organelles and engulfed bacteria","a":"Lysosome","b":"Peroxisome","why":"Both are small enzyme-filled vesicles, which is why they get swapped. Lysosomes digest with acid hydrolases in an acidic interior; peroxisomes use catalase to neutralize free radicals and hydrogen peroxide.","week":"1","c":0},{"clue":"The cytoplasmic structure that organizes microtubules and forms the mitotic spindle","a":"Centrosome, containing the centrioles","b":"Centromere","why":"The names are nearly identical, but the centrosome sits at the poles and builds the spindle, while the centromere is the constricted region of the chromosome where sister chromatids are joined and kinetochores attach.","week":"1","c":0},{"clue":"The dense region inside the nucleus where ribosomal RNA is made and ribosomal subunits are assembled","a":"Nucleolus","b":"Nuclear pore","why":"The nucleolus is the manufacturing site; the nuclear pore is only the doorway the finished subunits pass through on their way to the cytoplasm. One builds, the other admits traffic.","week":"1","c":0},{"clue":"Engulfing a large solid particle such as a bacterium by wrapping the membrane around it","a":"Phagocytosis","b":"Pinocytosis","why":"Phago means eating and takes in solid particles; pino means drinking and takes in droplets of extracellular fluid with dissolved solutes. Both are endocytosis and both cost ATP, so only the cargo separates them.","week":"1","c":0},{"clue":"The structural framework that gives the plasma membrane its bilayer arrangement","a":"Phospholipid bilayer","b":"Cholesterol","why":"Phospholipids self-assemble into two layers because their polar heads face water while their nonpolar tails hide from it. Cholesterol wedges between them as a fluidity buffer but does not create the structure.","week":"1","c":0},{"clue":"The division of the cytoplasm that physically produces two separate daughter cells","a":"Cytokinesis","b":"Telophase","why":"Telophase is a nuclear event: envelopes reform and chromosomes decondense. Cytokinesis is the cleavage furrow pinching the cytoplasm in two. They overlap in time, which is why students treat them as one step.","week":"1","c":0},{"clue":"The daughter cells produced by mitosis are best described as","a":"Two diploid cells genetically identical to the parent","b":"Four haploid cells with new gene combinations","why":"Mitosis makes copies for growth and repair, so the chromosome number and the genetic content are preserved. The haploid, genetically shuffled outcome belongs to meiosis, which serves gamete formation instead.","week":"1","c":0},{"clue":"The inner mitochondrial folds that hold the electron transport chain","a":"Cristae","b":"Matrix","why":"Cristae are membrane folds whose surface area sets how much ATP synthesis machinery can be housed. The matrix is the fluid interior where the citric acid cycle and mitochondrial DNA sit.","week":"1","c":0},{"clue":"The intravenous fluid that will not shift water into or out of a patient's cells","a":"0.9 percent sodium chloride","b":"0.45 percent sodium chloride","why":"Normal saline at 0.9 percent matches the osmolarity of body fluids, so there is no net water movement. Half-strength saline is hypotonic and drives water into cells, which is exactly the clinical use of the tonicity rule.","week":"1","c":0}],"redflags":[{"s":"A patient receives a rapid intravenous infusion of sterile water and free hemoglobin appears in the plasma","act":1,"why":"Sterile water is profoundly hypotonic, so water floods into red blood cells until the membrane ruptures. This is why intravenous fluids must be made isotonic before they enter a vein.","week":"1"},{"s":"A red blood cell placed in 0.9 percent sodium chloride keeps its normal biconcave shape and volume","act":0,"why":"Isotonic surroundings mean water enters and leaves at the same rate, so volume holds steady. Stability here is the expected result, not evidence that transport has stopped.","week":"1"},{"s":"The sodium-potassium pump consumes roughly a quarter of a resting cell's ATP supply","act":0,"why":"Maintaining the sodium and potassium gradients is a continuous, expensive housekeeping job. That high baseline cost is normal and is exactly why cells die so quickly when ATP production fails.","week":"1"},{"s":"A cell exposed to a metabolic poison shows falling ATP, rising intracellular sodium, and progressive swelling","act":1,"why":"With the sodium-potassium pump stalled, sodium accumulates inside and raises the intracellular solute load, so osmosis pulls water in. Swelling is the visible endpoint of an energy failure, not a membrane defect.","week":"1"},{"s":"Epithelial cells lining the small intestine are replaced every few days by mitosis","act":0,"why":"Tissues exposed to constant abrasion and digestive enzymes maintain a permanently active stem cell population. Rapid turnover here is normal physiology, which is also why these cells are hit hard by drugs that target dividing cells.","week":"1"},{"s":"Cultured skin cells keep dividing after they contact neighbors on all sides and begin piling into disorganized layers","act":1,"why":"Normal cells stop dividing when crowded, a control called contact inhibition. Losing that brake is a defining behavior of transformed cells and signals that cell cycle regulation has broken down.","week":"1"},{"s":"A cell proceeds past the G2 checkpoint carrying unrepaired double-strand DNA breaks","act":1,"why":"The G2 checkpoint exists to confirm that replication finished accurately before the irreversible act of separating chromosomes. Dividing with damaged DNA passes the error to both daughter cells permanently.","week":"1"},{"s":"A mature red blood cell cannot undergo mitosis because it has extruded its nucleus","act":0,"why":"Losing the nucleus is a normal maturation step that frees interior space for hemoglobin. The trade-off is a finite lifespan of about 120 days with no capacity for repair or division.","week":"1"},{"s":"An infant's cells cannot break down a specific membrane lipid, and undigested material steadily accumulates inside swollen lysosomes","act":1,"why":"A single missing hydrolytic enzyme leaves its substrate permanently undigested, so the lysosome becomes a storage bin rather than a recycling center. Progressive cellular congestion follows, most severely in neurons.","week":"1"},{"s":"Worn-out organelles are enclosed in a vesicle that fuses with a lysosome and is digested","act":0,"why":"This is autophagy, the routine quality-control system that recycles damaged components into reusable amino acids and lipids. Ongoing self-digestion at this scale is maintenance, not injury.","week":"1"},{"s":"A patient's neutrophils reach a bacterium but cannot extend membrane around it to form a phagosome","act":1,"why":"Phagocytosis is the only route by which a particle that large crosses the plasma membrane. If the engulfment step fails, the organism is never delivered to a lysosome and the infection is never cleared.","week":"1"},{"s":"A skeletal muscle fiber contains many nuclei distributed just beneath its plasma membrane","act":0,"why":"Skeletal muscle fibers form by the fusion of many precursor cells, so multinucleation is their normal architecture. The extra nuclei let one very long cell supply mRNA along its entire length.","week":"1"},{"s":"A single base substitution in a gene changes one amino acid and distorts the folded shape of the whole protein","act":1,"why":"Protein function depends on three-dimensional shape, and shape is dictated by the amino acid sequence. One wrong residue at a critical position can misfold the entire molecule, which is how a point mutation produces disease.","week":"1"},{"s":"A mature neuron has exited the cell cycle and remains in G0 rather than preparing to divide","act":0,"why":"G0 is a stable resting state, not a stalled one. Highly specialized cells such as neurons commit their resources to function instead of division, which is normal but also explains their limited capacity to regenerate.","week":"1"}],"chains":[{"title":"Hemolysis in a hypotonic solution","start":"A red blood cell is dropped into a beaker of distilled water","steps":["The surrounding water contains far fewer nonpenetrating solute particles than the cytosol, so the extracellular fluid is hypotonic to the cell","Water diffuses down its own concentration gradient, crossing the bilayer directly and moving faster through aquaporin channels, into the cell","Cell volume rises, the biconcave disc rounds into a sphere, and the plasma membrane is stretched taut","Membrane tension exceeds what the phospholipid bilayer and its cytoskeletal anchors can withstand","The membrane ruptures and hemoglobin spills into the surrounding fluid, which is hemolysis"],"why":"Water is the mobile particle in this system because the membrane blocks the solute. Since the solute cannot move to equalize the two compartments, the solvent must, and the cell has no mechanism to refuse the incoming water.","week":"1"},{"title":"From gene to secreted protein","start":"A signal instructs the cell to manufacture a protein destined for export","steps":["RNA polymerase separates the DNA strands at the gene and transcribes the template strand into messenger RNA inside the nucleus","The processed mRNA passes through a nuclear pore into the cytoplasm and binds to a ribosome","Transfer RNAs whose anticodons pair with each mRNA codon deliver their amino acids, and the ribosome links them into a growing polypeptide chain","Because the chain carries an export signal, the ribosome docks on the rough endoplasmic reticulum and the protein folds as it enters the ER lumen","Transport vesicles carry it to the Golgi apparatus for final modification and sorting, then a secretory vesicle fuses with the plasma membrane and releases the protein by exocytosis"],"why":"DNA never leaves the nucleus, so its information has to be copied into a portable messenger before it can be used. Each subsequent handoff, from ribosome to ER to Golgi, adds processing that the previous station is not equipped to perform.","week":"1"},{"title":"How the sodium-potassium pump defends the cell","start":"ATP binds the sodium-potassium ATPase embedded in the plasma membrane","steps":["Three intracellular sodium ions bind the pump, ATP is split, and the carrier protein becomes phosphorylated","The phosphorylated carrier changes shape and releases those three sodium ions into the extracellular fluid","Two extracellular potassium ions bind, the phosphate group is released, and the carrier snaps back to its original shape, delivering the potassium inside","Each complete cycle exports three positive charges and imports only two, leaving the cell interior negative relative to the outside","Because sodium is continuously removed, total intracellular solute stays below the level that would draw water in, so cell volume holds steady"],"why":"The three-for-two exchange is deliberately unequal, and that single design feature does two jobs at once: it establishes the membrane potential every excitable cell depends on, and it prevents the osmotic swelling that would otherwise follow sodium leaking inward.","week":"1"},{"title":"One turn of the cell cycle","start":"A cell in G1 passes its checkpoint and commits to dividing","steps":["During S phase every chromosome is replicated, producing two identical sister chromatids joined at a single centromere","In G2 the cell grows, duplicates its organelles, and verifies at a checkpoint that replication was complete and error free","In prophase chromatin condenses into visible chromosomes, the nuclear envelope disassembles, and the spindle grows out from the two centrosomes","In metaphase the spindle aligns the chromosomes along the cell equator, with a microtubule attached to the kinetochore of each chromatid","In anaphase the centromeres split and the chromatids are dragged to opposite poles, telophase rebuilds two nuclei, and cytokinesis pinches the cytoplasm into two genetically identical diploid daughter cells"],"why":"The order is forced by the chemistry: DNA must be copied before it can be divided, and it must be aligned before it can be pulled apart. Each checkpoint sits immediately before a step that cannot be undone once it begins.","week":"1"},{"title":"Bringing a large molecule in by receptor-mediated endocytosis","start":"A cholesterol-carrying LDL particle contacts the outer surface of the plasma membrane","steps":["The particle binds specific receptor proteins embedded in the membrane, which is what makes this route selective","The occupied receptors cluster together into a coated pit, and ATP-driven proteins bend the membrane inward","The pit deepens and pinches off, forming an intracellular vesicle carrying both the particle and its receptors","The vesicle fuses with a lysosome, whose hydrolytic enzymes digest the contents in an acidic interior","Released cholesterol and amino acids enter the cytosol for use, and the receptors are recycled back to the plasma membrane"],"why":"The particle is far too large and too polar to slip through the bilayer, so the cell must wrap membrane around it instead. Specificity comes entirely from the receptor, which is why this pathway is selective while pinocytosis takes in whatever fluid is nearby.","week":"1"},{"title":"Absorbing glucose against its gradient in the small intestine","start":"The sodium-potassium pump on the basolateral surface of an intestinal cell exports sodium using ATP","steps":["Continuous sodium export keeps intracellular sodium low, creating a steep inward sodium gradient","On the luminal surface, a cotransporter protein binds one sodium ion and one glucose molecule at the same time","Sodium moving down its own gradient into the cell releases energy that drags glucose in alongside it, even though glucose is moving uphill","Intracellular glucose concentration rises above the concentration in the blood","Glucose then exits the opposite side of the cell by facilitated diffusion through a passive carrier and enters the capillary"],"why":"No ATP ever touches the cotransporter itself; the energy was banked earlier as a sodium gradient by a different pump. That one-step-removed energy source is precisely what the word secondary means in secondary active transport.","week":"1"},{"title":"Oxygen crossing a membrane by simple diffusion","start":"Oxygen in the alveolar air sits at a higher partial pressure than oxygen in the capillary blood","steps":["A concentration gradient therefore exists across the thin respiratory membrane","Because oxygen is small and nonpolar, it dissolves directly into the hydrophobic fatty acid tails of the phospholipid bilayer","Random molecular motion carries more oxygen molecules from the high-concentration side to the low-concentration side than in the reverse direction","Net movement continues with no carrier protein and no ATP expenditure, driven only by that gradient","Hemoglobin inside the red blood cells binds the arriving oxygen, keeping dissolved oxygen in the plasma low and holding the gradient open"],"why":"Simple diffusion has no transport protein that can be saturated, so its rate is governed only by how steep the gradient is, how thin the membrane is, how much surface area is available, and how lipid soluble the molecule happens to be.","week":"1"}]},"2":{"labs":[{"labs":[["Apparent cell layers on cross section","up"],["Cells contacting the basement membrane","n"],["Cilia on the free surface","up"],["Goblet cells","up"]],"opts":["Simple columnar epithelium","Pseudostratified ciliated columnar epithelium","Stratified columnar epithelium","Transitional epithelium"],"c":1,"why":"The <b>n<\/b> line decides it. Layer count is defined by contact with the basement membrane, not by where nuclei sit. Here every cell still touches it, so this is a single layer whose short basal stem cells simply have not reached the surface yet, which staggers the nuclei and fakes stratification. Cilia plus mucus-making goblet cells place it in the conducting airway.","week":"2"},{"labs":[["Cell height","down"],["Number of cell layers","n"],["Diffusion distance across the layer","down"],["Secretory granules","down"]],"opts":["Simple cuboidal epithelium","Transitional epithelium","Simple squamous epithelium","Nonkeratinized stratified squamous epithelium"],"c":2,"why":"Diffusion slows as the barrier thickens, so any surface built for exchange must minimise both cell height and layer number. A single sheet of flattened cells holds the barrier under a micrometre. The absent secretory granules rule out a gland or duct lining, and one layer rules out anything stratified.","week":"2"},{"labs":[["Cell height","up"],["Apical microvilli","up"],["Mitochondria per cell","up"],["Number of cell layers","n"],["Goblet cells","up"]],"opts":["Simple columnar epithelium with a microvillus brush border","Simple squamous epithelium","Pseudostratified columnar epithelium","Stratified cuboidal epithelium"],"c":0,"why":"Tall cells give room for the organelles that absorption needs, microvilli multiply the apical surface area many times over, and the mitochondrial load betrays active transport, which costs ATP. A single layer keeps the transport path short. Height plus one true layer is the signature of the intestinal lining.","week":"2"},{"labs":[["Number of cell layers","up"],["Keratin in the surface cells","up"],["Nuclei in the surface cells","down"],["Blood vessels inside the epithelium","down"]],"opts":["Nonkeratinized stratified squamous epithelium","Transitional epithelium","Simple squamous epithelium","Keratinized stratified squamous epithelium"],"c":3,"why":"Missing nuclei at the surface is the giveaway: those cells are dead, packed with keratin, and act as a waterproof shield of protein rather than as living cells. They die because the epithelium has no vessels of its own and the surface layers sit beyond diffusion range of the dermal capillaries. Nonkeratinized versions keep their nuclei and stay moist.","week":"2"},{"labs":[["Apparent layers when the organ is empty","up"],["Apparent layers when the organ is full","down"],["Dome-shaped surface cells","abn"],["Permeability to water and solutes","down"]],"opts":["Transitional epithelium (urothelium)","Nonkeratinized stratified squamous epithelium","Pseudostratified columnar epithelium","Simple cuboidal epithelium"],"c":0,"why":"Layer count that changes with organ volume can only happen if the cells slide over one another and unfold stored apical membrane. The impermeability is just as diagnostic: concentrated urine would otherwise pull water out of the wall by osmosis, so the surface cells are sealed by tight junctions and membrane plaques.","week":"2"},{"labs":[["Collagen fibre content","up"],["Ground substance between the fibres","down"],["Blood vessels","down"],["Strength along one axis","up"],["Speed of healing after a tear","down"]],"opts":["Areolar connective tissue","Dense regular connective tissue","Dense irregular connective tissue","Elastic connective tissue"],"c":1,"why":"Packing collagen into parallel bundles with almost no matrix between them buys enormous strength in the single direction the muscle pulls, but crowds out vessels. Poor perfusion means few cells and little oxygen for collagen synthesis, which is the direct mechanical reason tendons and ligaments heal so slowly.","week":"2"},{"labs":[["Blood vessels in the tissue","down"],["Cells sitting in lacunae","abn"],["Ground substance (proteoglycan) content","up"],["Rate of repair after injury","down"]],"opts":["Compact bone","Dense irregular connective tissue","Hyaline cartilage","Areolar connective tissue"],"c":2,"why":"Bone cells also sit in lacunae, so that finding alone cannot separate the two. Vascularity does: bone is richly perfused and remodels, while cartilage has no vessels and feeds its chondrocytes by slow diffusion through a stiff, water-swollen proteoglycan gel. Poor delivery limits mitosis and matrix synthesis, so repair is slow and often incomplete.","week":"2"},{"labs":[["Nuclei per cell","up"],["Striations","abn"],["Intercalated discs","down"],["Cell length","up"]],"opts":["Cardiac muscle cell","Smooth muscle cell","Skeletal muscle fibre","Myofibroblast in granulation tissue"],"c":2,"why":"Striations only tell you sarcomeres are present, which is true of cardiac muscle too. The combination that is unique here is many peripheral nuclei in one very long unbranched cell with no cell-to-cell junctions, because the fibre was formed by dozens of myoblasts fusing into a single cell rather than by cells joining end to end.","week":"2"},{"labs":[["Nuclei per cell","n"],["Striations","abn"],["Intercalated discs","up"],["Gap junctions between cells","up"]],"opts":["Skeletal muscle","Smooth muscle","Cardiac muscle","Elastic connective tissue"],"c":2,"why":"The <b>n<\/b> means the ordinary one central nucleus, which excludes the multinucleate skeletal fibre, while the striations exclude smooth muscle. Short separate cells must be mechanically anchored and electrically linked, and the intercalated disc does both jobs at once, which is what allows the chambers to contract as one unit.","week":"2"},{"labs":[["Ability to fire an action potential","down"],["Myelin production","up"],["Axons wrapped by this single cell","up"],["Mitotic capacity","up"]],"opts":["Multipolar neuron","Astrocyte","Microglial cell","Oligodendrocyte"],"c":3,"why":"Not conducting rules out the neuron, and neurons are also essentially amitotic while glia keep dividing. Among the glia, only two make myelin, and the number of axons served separates them: one CNS cell sends processes to many internodes on many axons, whereas a peripheral Schwann cell wraps exactly one internode of one axon.","week":"2"},{"labs":[["Capillary density","up"],["Fibroblast number","up"],["Collagen content","down"],["Tensile strength","down"],["Macrophage number","up"]],"opts":["Mature scar","Granulation tissue","Normal dermis","Keratinized epidermis"],"c":1,"why":"This is the proliferative phase caught mid-stride. New capillary loops are sprouting to supply the repair, macrophages are still clearing debris, and fibroblasts have arrived but have not yet laid down or cross-linked much collagen, which is exactly why strength is at its lowest. A mature scar shows the mirror image: collagen high, vessels low.","week":"2"},{"labs":[["Hematocrit","up"],["Red blood cell count","up"],["Plasma protein concentration","n"],["Erythropoietin","up"]],"opts":["Dehydration with hemoconcentration","Iron-deficiency anemia","Acclimatization to high altitude","Acute hemorrhage one hour ago"],"c":2,"why":"Blood is a connective tissue with a fluid matrix, so a rising hematocrit can mean more cells or less plasma. The normal plasma protein is the discriminator: if plasma volume had shrunk, the proteins would have concentrated along with the cells. Normal protein with high erythropoietin means true expansion of red cell mass driven by low tissue oxygen.","week":"2"}],"pairs":[{"clue":"The barrier that oxygen must cross between alveolar air and capillary blood.","a":"Simple squamous epithelium","b":"Simple cuboidal epithelium","why":"Diffusion rate is inversely related to barrier thickness. A flattened cell is a fraction of a micrometre thick at its margins, so the air-blood barrier stays thin enough for gas to equilibrate in under a second. Cuboidal cells are several times thicker and carry the organelles of secretion and absorption, so they line ducts and tubules, not exchange surfaces.","week":"2","c":0},{"clue":"Nuclei sit at three different heights and cilia cover the top, yet every cell reaches the basement membrane.","a":"Pseudostratified ciliated columnar epithelium","b":"Stratified columnar epithelium","why":"Layers are counted by contact with the basement membrane, never by nuclear position. In a truly stratified sheet only the deepest cells touch it. Here the short cells are basal stem cells that have not yet grown to the surface, so the tissue is one layer with staggered nuclei.","week":"2","c":0},{"clue":"Epithelium of the ureter and bladder that is rounded and six cells thick when empty and flat and three thick when full.","a":"Transitional epithelium","b":"Nonkeratinized stratified squamous epithelium","why":"Both are stratified and both resist abrasion, so protection cannot separate them. Only transitional stores spare apical membrane in vesicles and lets its cells slide over one another, and only it seals the wall with tight junctions and membrane plaques so hypertonic urine cannot draw water out of the tissue.","week":"2","c":0},{"clue":"Striated muscle whose short cells are joined end to end by dark transverse bands.","a":"Cardiac muscle","b":"Skeletal muscle","why":"Striations mean sarcomeres and both tissues have them, so striations are worthless for telling them apart. Only cardiac muscle is built of separate branched cells, and separate cells need a junctional complex to survive being pulled on and to share current. A skeletal fibre is one giant fused cell and needs no such junction.","week":"2","c":0},{"clue":"Spindle-shaped cell with a single central nucleus and no striations in the wall of the small intestine.","a":"Smooth muscle cell","b":"Cardiac muscle cell","why":"Smooth muscle looks unstriped because its actin and myosin run obliquely to dense bodies instead of lining up into sarcomeres. That lattice lets the cell shorten across a huge range of lengths and hold tension cheaply for hours, which is what a hollow organ wall needs. Cardiac muscle is striated, branched and confined to the heart.","week":"2","c":0},{"clue":"The connective tissue that makes up a tendon.","a":"Dense regular connective tissue","b":"Dense irregular connective tissue","why":"Both are collagen-dominated and both are strong. Regular arrangement means every bundle is parallel to the single line of pull, concentrating all the tensile strength on one axis. Irregular arrangement weaves fibres in every plane, giving moderate strength from any direction, which is what a dermis or an organ capsule is loaded from.","week":"2","c":0},{"clue":"The cartilage of the intervertebral disc and the pubic symphysis.","a":"Fibrocartilage","b":"Hyaline cartilage","why":"Fibrocartilage inserts thick visible bundles of collagen between rows of chondrocytes, so it resists compression like cartilage and tension like a tendon at the same time. That hybrid is what a weight-bearing shock absorber requires. Hyaline collagen is fine and hidden in the matrix and would shear apart under those loads.","week":"2","c":0},{"clue":"The cartilage of the external ear and the epiglottis, which springs back after being folded.","a":"Elastic cartilage","b":"Fibrocartilage","why":"Recoil requires coiled elastin fibres that stretch and snap back, and elastic cartilage packs its matrix with them. Fibrocartilage's collagen resists being stretched but has no stored recoil, so it holds shape under load rather than returning to shape after deformation.","week":"2","c":0},{"clue":"Large multinucleate bone cell sitting in a shallow pit it has just eaten out of the matrix.","a":"Osteoclast","b":"Osteoblast","why":"The osteoclast comes from the white blood cell line and forms by fusion, which is why it has many nuclei. It seals a ruffled border against bone, pumps acid to dissolve the mineral and enzymes to digest the collagen. The osteoblast is a single-nucleus connective tissue cell doing the opposite job, secreting osteoid.","week":"2","c":0},{"clue":"One glial cell whose processes myelinate internodes on dozens of different axons in the spinal cord.","a":"Oligodendrocyte","b":"Schwann cell","why":"A Schwann cell wraps its whole body around exactly one internode of one axon and keeps an outer cytoplasmic sleeve, the neurilemma, that later guides a regrowing axon back to its target. Oligodendrocytes serve many axons and leave no such sleeve, which is a large part of why peripheral nerves regenerate and central tracts largely do not.","week":"2","c":0},{"clue":"Glial cell whose end-feet wrap capillaries, help form the blood-brain barrier and mop up spilled potassium and neurotransmitter.","a":"Astrocyte","b":"Microglial cell","why":"Astrocytes are the housekeeping and interface cell of nervous tissue, controlling what enters from the blood and stabilising the ionic environment neurons need to keep firing. Microglia are immune cells derived from blood monocytes; they phagocytose debris and pathogens and have no barrier or buffering role.","week":"2","c":0},{"clue":"The membrane lining the pleural cavity.","a":"Serous membrane","b":"Mucous membrane","why":"The deciding question is whether the cavity opens to the outside world. Serous membranes line closed cavities and are a mesothelium of simple squamous cells on areolar tissue that filters a thin watery fluid. Mucous membranes line tracts that do open to the exterior and secrete viscous mucin to trap and lubricate.","week":"2","c":0},{"clue":"The membrane lining the cavity of the knee joint.","a":"Synovial membrane","b":"Serous membrane","why":"Synovial membrane is the one major body membrane with no epithelium at all. It is areolar and adipose connective tissue whose surface cells secrete a hyaluronan-rich viscous fluid that both lubricates the joint and delivers nutrients to avascular articular cartilage. Serous membranes always have a mesothelium and produce a thin watery filtrate.","week":"2","c":0},{"clue":"The serous layer that is fused to the surface of the lung itself.","a":"Visceral pleura","b":"Parietal pleura","why":"Visceral means on the organ, parietal means on the cavity wall, and the thin film of serous fluid between them makes the two layers cling by surface tension. That coupling is why the lung is pulled outward when the chest wall expands, and why breaching the seal lets the lung collapse.","week":"2","c":0},{"clue":"The outcome in which lost cells are replaced by identical functioning cells.","a":"Regeneration","b":"Fibrosis","why":"Which one occurs depends on whether the tissue's cells can still divide and whether the connective scaffold survived. Epithelia and bone divide readily and regenerate. Cardiac muscle and neurons are permanent tissues, and deep wounds that destroy the scaffold, so collagen fills the defect instead, restoring strength but not the original function.","week":"2","c":0},{"clue":"Beefy red, moist, granular tissue filling a wound bed on day four that bleeds at the lightest touch.","a":"Granulation tissue","b":"Mature scar","why":"The redness and bleeding come from a dense field of newly sprouted capillary loops that are leaky and structurally immature, and their presence means the repair is proceeding normally. A scar is the endpoint of the same process after the vessels regress and cross-linked collagen dominates, so it is pale, avascular and firm.","week":"2","c":0},{"clue":"The structure inside an intercalated disc that carries an action potential from one cardiac cell to the next.","a":"Gap junction","b":"Desmosome","why":"Gap junctions are protein channels giving direct ionic continuity between cytoplasms, so current spreads without any chemical synapse and the myocardium behaves as one functional unit. Desmosomes are mechanical rivets anchored to intermediate filaments; they stop the cells tearing apart during contraction but carry no current at all.","week":"2","c":0},{"clue":"The simple squamous epithelium lining the inside of an artery.","a":"Endothelium","b":"Mesothelium","why":"These are the same tissue type with different addresses and jobs. Endothelium lines the cardiovascular and lymphatic lumen, providing a smooth non-clotting surface and controlling permeability and vessel diameter through the substances it releases. Mesothelium lines serous cavities and secretes serous fluid.","week":"2","c":0}],"redflags":[{"s":"On postoperative day five the edges of an abdominal incision separate and pink watery fluid drains from the gap.","act":1,"why":"Collagen in a five-day-old wound is sparse and not yet cross-linked, so tensile strength is at its lowest point of the whole repair. Separation means the fibrous bridge has failed before it ever formed, and the wound must be supported and re-closed rather than allowed to heal open.","week":"2"},{"s":"A long-term smoker's bronchial lining is now stratified squamous with no cilia and no goblet cells.","act":1,"why":"The airway has traded its normal epithelium for a tougher one, which sounds protective but abolishes the mucociliary escalator. Without mucus production and ciliary sweeping, inhaled particles and bacteria are no longer cleared upward, so they reach and stay in the alveoli.","week":"2"},{"s":"Six months after a tibial fracture the x-ray still shows a gap with no bony callus bridging it.","act":1,"why":"Bone is one of the few tissues that regenerates rather than scars, and it normally forms a cartilage then bony callus within weeks because it is richly vascular. No callus at six months means the blood supply, stability or apposition needed for that sequence is absent and the bone will not unite on its own.","week":"2"},{"s":"Fluid in the pericardial serous cavity has increased until the ventricles can no longer fill during diastole.","act":1,"why":"The serous fluid film is normally only a few millilitres, just enough to let the layers glide. The pericardial sac is fibrous and does not stretch acutely, so any added volume raises pressure on the heart from outside and mechanically limits filling.","week":"2"},{"s":"Eight months after a burn, a raised firm scar keeps enlarging and now extends well past the original wound margins.","act":1,"why":"Normal remodelling balances collagen synthesis against breakdown and stops at the wound edge. Continued growth beyond the injured area means synthesis has escaped that control, producing a mass of excess collagen that restricts movement and does not resolve on its own.","week":"2"},{"s":"An adult woman has a hematocrit of 21 percent with pale conjunctivae and breathlessness on climbing stairs.","act":1,"why":"Hematocrit is the fraction of blood volume that is the cellular part of this fluid connective tissue, and almost all of it is erythrocytes carrying hemoglobin. At that value the oxygen-carrying capacity of the blood is roughly half of normal, because that capacity sits in the haemoglobin of the cellular fraction rather than in the plasma matrix, so tissues can only be supplied by raising cardiac output and extraction.","week":"2"},{"s":"A knee is hot, tensely swollen and cannot be bent, and aspiration returns a large volume of cloudy joint fluid.","act":1,"why":"The synovial membrane both produces and reabsorbs joint fluid. Heat and a large cloudy effusion mean the membrane is inflamed and leaking cells and protein, and the pressure inside a closed capsule can compress the vessels feeding the avascular articular cartilage.","week":"2"},{"s":"A deep open ulcer over the sacrum has shown no red granulation tissue after three weeks of care.","act":1,"why":"Granulation tissue is the visible sign that capillaries and fibroblasts have entered the wound, and repair cannot proceed without it. Its absence means perfusion or ongoing pressure is preventing the proliferative phase from ever starting, so the defect is stalled rather than slowly healing.","week":"2"},{"s":"Two days after a clean surgical incision the wound line is pink, slightly swollen, warm and tender to touch.","act":0,"why":"These are the expected signs of the inflammatory phase. Chemical mediators dilate local arterioles and raise capillary permeability, so more blood arrives, which produces the heat and redness, while fluid and leukocytes enter the tissue and produce the swelling and pain that guard the site.","week":"2"},{"s":"A construction worker has thick, hard, painless pads of keratin over his palms.","act":0,"why":"Stratified squamous epithelium responds to repeated friction by increasing basal cell division and keratin deposition. The result is a thicker dead surface layer that absorbs abrasion, an adaptive thickening of a normal protective tissue rather than a disease.","week":"2"},{"s":"A torn knee meniscus heals far more slowly and less completely than a skin laceration of the same size.","act":0,"why":"The meniscus is fibrocartilage, which is largely avascular; nutrients and oxygen must diffuse through dense matrix and cell numbers are low. Skin sits on a vascular dermis with a highly mitotic basal layer, so the difference in healing reflects the normal difference in blood supply.","week":"2"},{"s":"A healed forearm scar has no hair follicles or sweat glands, is paler than surrounding skin and stretches less.","act":0,"why":"Fibrosis restores continuity with dense collagen, but it does not rebuild epidermal appendages or the elastic fibre network of the dermis, and the excess capillaries of granulation tissue regress as it matures. These features are the expected permanent signature of repair by scar.","week":"2"},{"s":"After two months living at 3,500 metres, a healthy hiker's hematocrit has risen from 43 to 52 percent.","act":0,"why":"Lower inspired oxygen reduces renal tissue oxygenation, which raises erythropoietin and drives the red marrow to produce more erythrocytes. This is the normal adaptive remodelling of a connective tissue's cell population to a chronic demand, and it reverses on returning to sea level.","week":"2"}],"chains":[{"title":"Repair of a clean skin incision by primary intention","start":"A scalpel divides the epidermis and cuts into the vascular dermis, and the edges are held together with sutures.","steps":["Blood escapes from the severed dermal vessels, platelets stick to exposed collagen and aggregate, and fibrinogen dissolved in the plasma matrix polymerises into a fibrin mesh that plugs the gap and dries at the surface into a scab.","Mediators released by injured cells and mast cells dilate local arterioles and open the capillary walls, so plasma, then neutrophils, then macrophages enter the site; this produces the redness, heat, swelling and pain of inflammation while the phagocytes clear clot debris and bacteria.","With the debris removed, endothelial cells sprout new capillary loops into the fibrin scaffold and fibroblasts migrate along it and begin secreting collagen, converting the clot into soft, red, highly vascular granulation tissue.","Basal cells of the epidermis at the wound margin divide and crawl across the moist granulation surface beneath the scab until the advancing sheets meet, at which point contact inhibition stops migration and the cells stratify and keratinise, restoring the barrier.","Over the following weeks to months the collagen is cross-linked and reoriented along the lines of mechanical stress while the surplus capillaries regress, leaving a pale avascular scar that regains most but never all of the original tensile strength."],"why":"The sequence shows the central rule of tissue repair: the epithelium truly regenerates because its basal cells keep dividing, while the dermal connective tissue is patched by fibrosis. Each stage exists to make the next possible, since fibrin is the scaffold fibroblasts crawl on and new capillaries are what deliver the oxygen collagen synthesis requires.","week":"2"},{"title":"The mucociliary escalator of the trachea","start":"Dust-laden air enters the trachea, which is lined by pseudostratified ciliated columnar epithelium.","steps":["Goblet cells within the epithelium and submucosal glands beneath it release mucin, which swells in water to form a sticky viscous sheet floating on a thinner watery layer that surrounds the cilia.","Particles carried in the airstream cannot follow the sharp turns of the airway, so they strike the wall and are trapped in the mucus sheet along with any bacteria they carry.","Each ciliated cell beats its cilia in a coordinated cycle, with a stiff power stroke that reaches up and catches the mucus sheet and a limp recovery stroke that stays down in the watery layer, so force is applied in one direction only.","Thousands of cells beating in wave-like coordination propel the whole mucus sheet, particles included, upward toward the pharynx at roughly a centimetre per minute.","At the pharynx the mucus is swallowed and destroyed in gastric acid, so the delicate simple squamous surface of the alveoli is never asked to filter and stays thin enough for gas exchange."],"why":"This chain is the standard argument for why form follows function in epithelium: neither specialisation works alone. Mucus without cilia would pool and obstruct, and cilia without mucus would have nothing to grip, so the airway needs a single layer containing both secretory and motile cell types.","week":"2"},{"title":"Endochondral ossification: replacing a cartilage model with bone","start":"In the limb bud a hyaline cartilage model of the future femur is laid down, wrapped in perichondrium.","steps":["The perichondrium surrounding the hyaline cartilage model becomes a periosteum, and its osteoblasts lay down a bone collar around the middle of the shaft.","Enclosed by that collar, the central chondrocytes hypertrophy and the cartilage matrix around them calcifies.","Cut off from diffusion through the now-calcified matrix, those chondrocytes die and leave cavities behind.","A periosteal bud carrying the nutrient artery and osteoprogenitor cells penetrates the collar, and osteoblasts deposit bone on the calcified cartilage remnants to form the primary ossification centre.","Osteoclasts hollow out the medullary cavity while secondary ossification centres form in the epiphyses, leaving cartilage only at the epiphyseal plates and articular surfaces."],"why":"The whole process is driven by one property of cartilage: it is avascular and diffusion-fed, so it cannot survive being mineralised or grown thick. That limitation explains both why the model must be destroyed to become bone and why lengthening can only continue at a thin surviving plate of cartilage.","week":"2"},{"title":"Spread of excitation through cardiac muscle","start":"The sinoatrial node fires and depolarises the first atrial cardiac muscle cell to threshold.","steps":["That cell is joined end to end with its neighbours by intercalated discs, and each disc contains gap junctions, which are aligned protein channels that make the two cytoplasms electrically continuous.","Positive current entering the first cell flows directly through those channels into the adjoining cells, with no neurotransmitter and no synaptic delay.","The neighbouring cells are pushed to threshold and fire their own action potentials, passing current onward, so depolarisation propagates cell to cell across the entire connected mass of the chamber.","Because there are no separately innervated motor units, every cell in that mass contracts in the same beat, and the branched arrangement lets the wave wrap around the chamber and squeeze it as one unit.","The desmosomes in the same intercalated discs anchor the cells to each other's intermediate filaments so the sheet does not tear apart under that shared load, while the long calcium plateau of the cardiac action potential keeps the cell refractory until contraction is nearly over, preventing tetanus and guaranteeing time to refill."],"why":"This explains why cardiac muscle behaves as a functional syncytium even though it is not one anatomical cell. The intercalated disc is doing two separate jobs with two separate structures, and losing either one would cost either the synchronised beat or the mechanical integrity of the wall.","week":"2"},{"title":"Myelination and saltatory conduction in a peripheral nerve","start":"A Schwann cell wraps its plasma membrane repeatedly around one segment of a motor axon.","steps":["Successive wraps squeeze the cytoplasm out from between the membrane layers, leaving concentric sheets of lipid that form a high-resistance, low-capacitance insulating collar around that internode.","Voltage-gated sodium channels are excluded from the axon membrane buried under the myelin and become concentrated at the bare gaps between adjacent Schwann cells, the nodes of Ranvier.","When an action potential is generated at one node, the sodium current entering there cannot leak out across the insulated internode, so it flows down the axoplasm and depolarises the next node instead.","That node reaches threshold and regenerates a full action potential, and the process repeats, so the impulse effectively jumps from node to node rather than being rebuilt at every point along the membrane.","Skipping all those regeneration steps makes conduction many times faster and much cheaper in ATP, because only the small nodal patches have to be pumped back to resting ionic conditions afterward."],"why":"The key idea students invert is that myelin does not conduct anything; it prevents leakage. Speed comes from reducing the number of places the action potential has to be rebuilt, which is also why stripping myelin slows or blocks conduction even though the axon itself is intact.","week":"2"},{"title":"Why epithelium is avascular, and what that forces it to become","start":"Epithelium contains no blood vessels of its own, so every epithelial cell depends on diffusion from capillaries in the connective tissue beneath it.","steps":["Oxygen and nutrients cross the basement membrane and diffuse upward through the sheet, and their concentration falls steadily with distance from that boundary.","Where a surface must permit exchange, keeping the tissue to a single flat layer keeps both the supply distance and the diffusion barrier minimal, which is why exchange surfaces are simple squamous.","Where a surface is instead abraded, the tissue must stack layers for protection, but the added thickness puts the outermost cells beyond the reach of diffusion.","Mitosis is therefore restricted to the basal layer sitting on the basement membrane, and each division pushes older daughter cells toward the surface and further from their supply, so they progressively accumulate keratin, lose their organelles and nucleus, and die.","The dead keratinised surface cells are shed continuously and replaced from below, so the barrier renews itself indefinitely while never requiring a blood supply within the epithelium."],"why":"One structural fact, the absence of vessels, predicts the shape of every epithelium on the exam. It explains why exchange linings are thin and single-layered, why protective linings are thick and topped by dead cells, and why the basal layer is always the mitotic one.","week":"2"}]},"3":{"labs":[{"labs":[["Blisters present","abn"],["Pain and sensitivity to light touch","up"],["Blanching with pressure","n"],["Hair follicles in wound bed intact","n"]],"opts":["Superficial partial-thickness (second-degree) burn","Superficial (first-degree) burn","Full-thickness (third-degree) burn","Deep burn extending into muscle"],"c":0,"why":"A blister means the epidermis has separated from the dermis at the basement membrane, so the injury is deeper than a first-degree burn. But blanching proves the dermal capillary plexus still fills, and the heightened pain proves free nerve endings are exposed and alive. Living vessels plus living nerves plus surviving follicles place the depth in the papillary dermis only.","week":"3"},{"labs":[["Sensation to pinprick in wound centre","down"],["Blanching with pressure","down"],["Wound surface texture","abn"],["Capillary refill in wound bed","down"]],"opts":["Full-thickness (third-degree) burn","Superficial partial-thickness burn","Superficial (first-degree) sunburn","Deep partial-thickness burn that will heal on its own"],"c":0,"why":"Painlessness is the discriminator, and it is counterintuitive to students who expect deeper to mean more painful. The sensory endings and the dermal vascular plexus both live in the dermis, so when nothing can be felt and nothing blanches, the entire dermis is gone along with the follicles and glands that would have regenerated epidermis.","week":"3"},{"labs":[["Entire anterior trunk involved","abn"],["Entire right upper limb involved","abn"],["Head and neck","n"],["Perineum","n"]],"opts":["18 percent","27 percent","36 percent","45 percent"],"c":1,"why":"The rule of nines divides the adult body into eleven 9 percent panels plus 1 percent for the perineum. The anterior trunk is two panels because chest and abdomen are counted separately, and a whole upper limb is a single panel counting front and back together. The uninvolved head and perineum are the values students most often add in by reflex.","week":"3"},{"labs":[["Sunlight exposure of skin","down"],["Serum 25-hydroxyvitamin D","down"],["Parathyroid hormone","up"],["Serum calcium","n"]],"opts":["Reduced cutaneous vitamin D synthesis, with calcium held normal by compensation","Primary hyperparathyroidism","Vitamin D toxicity from oversupplementation","Failure of the kidney to perform the final hydroxylation"],"c":0,"why":"Keratinocytes of the stratum basale and spinosum store 7-dehydrocholesterol, and UVB is what cleaves it to cholecalciferol. Throttle that first step and the storage form falls. The normal calcium is the trap: it is normal only because parathyroid hormone has been pushed up to defend it, so a normal value here signals successful compensation rather than health.","week":"3"},{"labs":[["Core body temperature","n"],["Cutaneous blood flow","up"],["Eccrine sweat rate","up"],["Skin surface temperature","up"]],"opts":["Normal thermoregulatory heat loss during exertion","Fever with an elevated hypothalamic set point","Heat stroke with thermoregulatory failure","Sympathetic vasoconstriction in response to cold"],"c":0,"why":"Dilating the dermal vessels moves warm blood to the surface for radiation and convection, and wetting that surface allows evaporation. The normal core temperature is the proof that the mechanism is winning. In heat stroke sweating stops and core temperature climbs; in fever the set point itself has moved and the skin initially vasoconstricts.","week":"3"},{"labs":[["Melanocyte number in stratum basale","n"],["Melanin content of keratinocytes","down"],["Tyrosinase activity","down"],["Pattern of pale skin","n"]],"opts":["Albinism","Vitiligo","Post-inflammatory hypopigmentation","Pallor from severe anemia"],"c":0,"why":"The melanocytes are present and correctly positioned; what fails is the enzyme that oxidises tyrosine into melanin inside the melanosome. Because every melanocyte in the body carries the same enzyme defect, the pallor is uniform rather than patchy, and the uniform pattern is what separates it from vitiligo.","week":"3"},{"labs":[["Melanocyte number within pale patches","down"],["Melanin in surrounding skin","n"],["Tyrosinase activity in unaffected skin","n"],["Pattern of pale skin","abn"]],"opts":["Vitiligo","Albinism","Carotenemia","Vitamin D deficiency"],"c":0,"why":"Fully pigmented skin sitting directly against completely unpigmented skin means the pigment chemistry works perfectly wherever melanocytes remain. The lesion is loss of the cells themselves in discrete areas, so this is a distribution problem rather than an enzyme problem.","week":"3"},{"labs":[["Arterial oxygen saturation","down"],["Deoxygenated hemoglobin in dermal capillaries","up"],["Melanin content","n"],["Colour of oral mucosa and nail beds","abn"]],"opts":["Cyanosis from poorly oxygenated blood showing through the dermis","Jaundice from accumulated bilirubin","Carotenemia from dietary intake","Increased melanin production"],"c":0,"why":"Skin colour has three contributors: melanin, carotene, and the hemoglobin visible in dermal capillaries. Here only the hemoglobin term has changed, and deoxygenated hemoglobin is dark and blue-toned. It shows first at the mucosa and nail beds because those sites have the least melanin masking the vessels beneath.","week":"3"},{"labs":[["Neutrophils in the wound","up"],["Local capillary permeability","up"],["Fibroblast activity","down"],["Wound tensile strength","down"]],"opts":["Inflammatory phase, roughly days one to three","Proliferative phase","Maturation (remodelling) phase","Hemostasis in the first minutes after injury"],"c":0,"why":"Increased capillary permeability is the delivery mechanism, letting plasma and phagocytes leave the vessel and enter the wound. Nothing is being rebuilt yet, which is exactly why fibroblast activity is still low. The wound is being cleaned before it is repaired.","week":"3"},{"labs":[["Fibroblast activity","up"],["Type III collagen","up"],["New capillary sprouting and granulation tissue","up"],["Wound tensile strength","down"]],"opts":["Proliferative phase","Inflammatory phase","Maturation (remodelling) phase","Fully healed skin"],"c":0,"why":"The apparent contradiction is the teaching point. Type III collagen is deposited quickly but the fibres are thin, poorly cross-linked and randomly oriented, so the defect visibly fills in with red granulation tissue while remaining mechanically weak. Appearance of healing runs well ahead of actual strength.","week":"3"},{"labs":[["Type III collagen","down"],["Type I collagen","up"],["Capillary density in the scar","down"],["Tensile strength compared with uninjured skin","down"]],"opts":["Maturation (remodelling) phase","Proliferative phase","Chronic non-healing wound","Inflammatory phase"],"c":0,"why":"Thin type III collagen is progressively swapped for thick cross-linked type I laid down along lines of mechanical stress, and the excess capillaries built during granulation regress. That is why a scar pales and firms over months. It still tops out around 80 percent of original strength because the regular dermal collagen weave and the appendages are never rebuilt.","week":"3"},{"labs":[["Stratum corneum thickness","up"],["Mitotic rate in stratum basale","up"],["Keratin content","up"],["Sensitivity to light touch","down"]],"opts":["Callus formed by accelerated basal mitosis and keratinisation","Scar tissue following a full-thickness burn","Normal thin skin such as the eyelid","Breakdown of the epidermal water barrier"],"c":0,"why":"The epidermis answers repeated friction by speeding up the journey it already makes. Basal cells divide faster, more cells complete keratinisation, and the dead squame layer piles up. Touch sensitivity falls because the Meissner corpuscles in the dermal papillae are now buried under a thicker dead layer, not because the receptors were damaged.","week":"3"}],"pairs":[{"clue":"The epidermal layer where mitosis occurs and where melanocytes and tactile (Merkel) cells reside","a":"Stratum basale","b":"Stratum spinosum","why":"Division is confined to the deepest layer because that is the only layer in contact with the basement membrane, and therefore the only one close enough to the dermal capillaries to be nourished. The spinosum is where the daughter cells begin building keratin filaments and the desmosomes that give it a spiny appearance.","week":"3","c":0},{"clue":"The translucent layer found only in the thick skin of the palms and soles","a":"Stratum lucidum","b":"Stratum granulosum","why":"The lucidum is an extra layer inserted between granulosum and corneum only where abrasion is highest, so its presence defines thick skin. The granulosum exists everywhere and is defined by its keratohyalin granules, not by its clarity.","week":"3","c":0},{"clue":"The layer where keratinocytes die and where lipids are extruded to waterproof the skin","a":"Stratum granulosum","b":"Stratum corneum","why":"The corneum is the finished barrier made of already dead cells, but a cell must still be alive to secrete. The lamellar granules that release the waterproofing lipids are extruded in the granulosum, and that lipid seal is what cuts the cell off from nutrients and kills it.","week":"3","c":0},{"clue":"The dermal layer containing dermal papillae, capillary loops and Meissner corpuscles","a":"Papillary dermis","b":"Reticular dermis","why":"The papillary layer is loose areolar tissue that projects fingers up into the avascular epidermis to feed it by diffusion and to place fine-touch receptors close to the surface. The reticular layer beneath is dense irregular connective tissue built for tensile strength, not for nutrition.","week":"3","c":0},{"clue":"The layer that is not technically part of the skin and anchors it to underlying muscle and bone","a":"Hypodermis (subcutaneous layer)","b":"Reticular dermis","why":"The skin proper is only epidermis plus dermis. The hypodermis lies below both and is areolar and adipose tissue serving fat storage, insulation and shock absorption. The reticular dermis is still skin and provides the collagen and elastin that give it strength and recoil.","week":"3","c":0},{"clue":"The gland that releases an oily secretion by rupturing its own cells into a hair follicle","a":"Sebaceous gland","b":"Apocrine sweat gland","why":"Sebaceous secretion is holocrine: the whole cell disintegrates and becomes the product, which is why sebum is lipid rich. Apocrine glands, despite the name, are merocrine in mechanism and release a viscous, milky, protein- and lipid-rich secretion by exocytosis.","week":"3","c":0},{"clue":"The sweat gland responsible for thermoregulatory sweating over most of the body surface","a":"Eccrine (merocrine) sweat gland","b":"Apocrine sweat gland","why":"Eccrine glands are numerous, open directly onto the skin surface, and secrete a dilute watery sweat whose evaporation removes latent heat. Apocrine glands are limited to axillary and anogenital regions, empty into hair follicles, and contribute essentially nothing to cooling.","week":"3","c":0},{"clue":"The part of a hair that is living and actively dividing","a":"Hair matrix in the bulb","b":"Hair shaft above the skin surface","why":"Only matrix cells sitting on the vascularised dermal papilla divide. Everything pushed beyond that point is dead keratinised cells, which is exactly why cutting hair is painless and why damage to the papilla, not the shaft, ends hair growth.","week":"3","c":0},{"clue":"The structure whose contraction causes goosebumps and helps express sebum","a":"Arrector pili muscle","b":"External root sheath","why":"The arrector pili is smooth muscle running from the papillary dermis to the follicle wall; sympathetic contraction pulls the follicle upright, dimples the surface, and squeezes the sebaceous gland lying in the angle. The root sheath is epithelium surrounding the hair and cannot contract.","week":"3","c":0},{"clue":"The structure actually responsible for nail growth","a":"Nail matrix","b":"Lunula","why":"The matrix is the proliferating epithelium tucked under the proximal nail fold, and its cells keratinise to form the nail plate. The lunula is only the whitish crescent where that thick matrix obscures the vessels beneath, making it a visible landmark rather than the growth engine.","week":"3","c":0},{"clue":"The fold of stratum corneum overlapping the proximal edge of the nail","a":"Eponychium (cuticle)","b":"Hyponychium","why":"The eponychium sits proximally where the nail plate emerges and seals that junction. The hyponychium is the thickened epidermis under the free distal edge that seals the nail bed from the outside world. Position is the whole distinction.","week":"3","c":0},{"clue":"The pigment synthesised in melanosomes and transferred into keratinocytes","a":"Melanin","b":"Carotene","why":"Melanin is built from tyrosine inside the melanocyte and handed off in vesicles that stack over keratinocyte nuclei as a UV shield. Carotene is not made by the body at all; it is a dietary yellow-orange pigment that passively accumulates in the lipid-rich stratum corneum and in hypodermal fat.","week":"3","c":0},{"clue":"The burn depth that blisters, blanches with pressure, and heals in about two weeks without scarring","a":"Superficial partial-thickness (second-degree) burn","b":"Full-thickness (third-degree) burn","why":"Blistering and blanching prove that dermal vessels and epidermal appendages survive, so new epithelium can spread out from surviving hair follicles and sweat gland ducts across the wound. A full-thickness burn destroys those sources, which is why it cannot re-epithelialise and requires grafting.","week":"3","c":0},{"clue":"The rule of nines value assigned to one entire lower limb in an adult","a":"18 percent","b":"9 percent","why":"Each lower limb is two 9 percent panels, anterior and posterior, whereas each upper limb totals only one panel for front and back combined. Students commonly carry the arm value down to the leg and underestimate the burn by half.","week":"3","c":0},{"clue":"The wound-healing phase in which a scar gains most of its final strength","a":"Maturation (remodelling) phase","b":"Proliferative phase","why":"The proliferative phase fills the defect quickly with fragile, disorganised type III collagen and granulation tissue, so the wound looks closed but is weak. Strength arrives later when that collagen is replaced by cross-linked type I and the fibres realign along lines of mechanical stress.","week":"3","c":0},{"clue":"The vitamin D precursor stored in epidermal keratinocytes","a":"7-dehydrocholesterol","b":"Calcitriol","why":"7-dehydrocholesterol is the cholesterol derivative UVB photolyses into cholecalciferol, and that single photochemical step is the skin's entire contribution. Calcitriol is the final active hormone produced two hydroxylations later, in liver and then kidney.","week":"3","c":0},{"clue":"The pigment change that becomes visible in the sclera first","a":"Jaundice from accumulated bilirubin","b":"Carotenemia from dietary carotene","why":"Bilirubin binds elastin, which is abundant in scleral connective tissue, so the eyes yellow before the skin does. Carotene is lipid soluble and settles into the thick stratum corneum of palms and soles and into subcutaneous fat, leaving the sclera white.","week":"3","c":0},{"clue":"The receptor for deep pressure and vibration, located in the reticular dermis and hypodermis","a":"Lamellar (Pacinian) corpuscle","b":"Tactile (Meissner) corpuscle","why":"The lamellar corpuscle's onion-layered capsule sits deep and its layers deform only with rapid or deep mechanical change, making it a vibration and deep pressure detector. Meissner corpuscles sit shallow in the dermal papillae, close to the surface, where they resolve light touch and texture.","week":"3","c":0}],"redflags":[{"s":"A burn that is dry, white and leathery, and the patient reports no sensation when the wound centre is touched with a pinprick","act":1,"why":"Absent sensation means the injury has destroyed the sensory endings that live in the dermis, and with them the hair follicles and sweat glands that would normally supply cells to resurface the wound. This is full-thickness injury and it cannot heal from within.","week":"3"},{"s":"Goosebumps and shivering after stepping out of a warm shower into cool air","act":0,"why":"Cutaneous thermoreceptors have triggered sympathetic contraction of the arrector pili muscles and skeletal muscle shivering. In humans the piloerection traps almost no air and is functionally vestigial, but the reflex itself is entirely normal heat-conserving physiology.","week":"3"},{"s":"A circumferential full-thickness burn encircling the entire chest","act":1,"why":"Full-thickness skin loses its elastin and contracts into a rigid, inelastic eschar. When that unyielding band completely surrounds the thorax it mechanically prevents the chest wall from expanding, so ventilation fails for purely structural reasons.","week":"3"},{"s":"Flushed skin and heavy sweating after thirty minutes of running, with normal alertness","act":0,"why":"Cutaneous vasodilation and eccrine sweating are the two normal routes of heat loss operating exactly as designed. Continued sweating and intact mental status confirm the hypothalamic control loop is functioning rather than failing.","week":"3"},{"s":"Hot, dry skin and confusion in someone exerting in the heat who has stopped sweating","act":1,"why":"When ambient temperature approaches skin temperature, radiation and convection stop working and evaporation becomes the only remaining avenue of heat loss. Loss of sweating removes it, so core temperature rises unopposed and central nervous tissue is affected.","week":"3"},{"s":"A mole that is asymmetric, has an irregular border, contains several colours, and has enlarged over three months","act":1,"why":"Normal melanocytes stay in the basal layer and produce pigment evenly. Asymmetry and colour variegation indicate melanocyte proliferation that has escaped normal regulation, and documented growth over time is the single most concerning feature.","week":"3"},{"s":"Yellow-orange discolouration of the palms and soles with white sclerae in someone eating large amounts of carrots and squash","act":0,"why":"Carotene is lipid soluble and deposits in the lipid-rich stratum corneum, which is thickest on palms and soles. The sclera stays white because carotene does not bind elastin the way bilirubin does, and that contrast is what separates carotenemia from jaundice.","week":"3"},{"s":"Blue-grey discolouration of the lips, tongue and nail beds at rest","act":1,"why":"These sites carry the least melanin, so the colour of blood in the dermal capillaries shows through most clearly. Blue at these sites means a high concentration of deoxygenated hemoglobin reaching the periphery, which is an oxygenation problem rather than a skin problem.","week":"3"},{"s":"A surgical scar that is paler, flatter and firmer at four months than it was at two months","act":0,"why":"This is exactly the maturation phase. Redundant granulation capillaries regress so the scar loses its redness, and type III collagen is replaced by cross-linked type I aligned along stress lines, which flattens and firms the tissue.","week":"3"},{"s":"Redness over the sacrum that does not blanch when pressed and does not fade after the pressure is relieved","act":1,"why":"Blanching proves that dermal capillaries can still be emptied and refilled, which is reactive hyperemia and reversible. Redness that will not blanch means blood has leaked out of damaged vessels into the tissue, marking actual tissue injury.","week":"3"},{"s":"Fingernails growing about three millimetres per month with a whitish crescent visible at the base of the thumbnail","act":0,"why":"Roughly 0.1 mm a day, about 3 mm a month, is normal output from the nail matrix, and the lunula is simply the region where the matrix is thick enough to hide the vascular nail bed beneath it. Both are expected anatomy.","week":"3"},{"s":"A pinched fold of forearm skin that tents and returns to shape slowly, together with dry mucous membranes","act":1,"why":"Skin turgor depends on the dermal ground substance holding water between the collagen and elastin fibres. When interstitial volume falls, the dermis loses the hydration that lets it snap back, so slow recoil is a physical marker of fluid depletion.","week":"3"},{"s":"Thinner, drier skin with reduced sweating and slower wound healing in an eighty-year-old","act":0,"why":"Aging predictably reduces sebaceous and eccrine gland output, dermal collagen and elastin content, dermal blood supply and basal-layer turnover rate. Each finding follows directly from those normal changes, so together they describe expected aging rather than disease.","week":"3"},{"s":"A partial-thickness burn that on day four is increasingly swollen, painful and warm at its margins with purulent drainage","act":1,"why":"The burn destroyed the stratum corneum barrier that normally excludes microorganisms, and the moist protein-rich wound is ideal for growth. Inflammation intensifying well past the expected window signals infection, which can deepen a partial-thickness wound into full-thickness loss.","week":"3"}],"chains":[{"title":"A keratinocyte's journey from stratum basale to desquamation","start":"A stem cell in the stratum basale divides while anchored to the basement membrane","steps":["The daughter cell is pushed up into the stratum spinosum, where it builds keratin filaments and desmosomes that bind it tightly to its neighbours","In the stratum granulosum it fills with keratohyalin granules and extrudes lipid-filled lamellar granules into the space between cells","That extruded lipid seals the intercellular space and cuts the cell off from dermal nutrients, so its nucleus and organelles are broken down and the cell dies","In the stratum corneum the flattened dead cell is now a keratin-packed squame cemented in place by the lipid it secreted, and this layer is the water barrier","Desmosomes at the surface are enzymatically degraded and the squame flakes away, roughly four weeks after the original division"],"why":"The barrier is built by the cell's own programmed death, which is why the waterproofing lipids must be secreted one layer before the corneum while the cell is still alive, and why the corneum is dead by definition rather than by accident.","week":"3"},{"title":"Sunlight to active vitamin D","start":"UVB radiation penetrates the epidermis and reaches keratinocytes of the stratum basale and spinosum","steps":["UVB cleaves the 7-dehydrocholesterol stored in those keratinocytes, converting it to cholecalciferol, vitamin D3","Cholecalciferol diffuses into the papillary dermal capillaries and is carried to the liver, where it is hydroxylated to 25-hydroxyvitamin D","The kidney adds a second hydroxyl group, producing 1,25-dihydroxyvitamin D, called calcitriol, the active hormone","Calcitriol increases calcium and phosphate absorption from the small intestine and calcium reabsorption in the kidney tubule","Rising blood calcium suppresses parathyroid hormone secretion, closing the negative feedback loop"],"why":"The skin performs only the first photochemical step, and the two activating hydroxylations happen elsewhere. That division of labour explains why sun exposure alone cannot correct calcium problems caused by liver or kidney failure, and why the skin is properly described as an endocrine organ.","week":"3"},{"title":"How the skin sheds heat when core temperature rises","start":"Warmed blood reaches the preoptic area of the hypothalamus and exceeds the temperature set point","steps":["The hypothalamus withdraws sympathetic vasoconstrictor tone from the dermal arterioles","Blood floods the papillary dermal capillary loops and the arteriovenous anastomoses, so the skin warms and reddens","Heat passes from that enlarged surface blood volume into the environment by radiation and convection","Sympathetic cholinergic fibres simultaneously stimulate eccrine glands to pour dilute sweat onto the skin surface","Evaporation of that sweat carries away latent heat, and core temperature falls back toward the set point"],"why":"Radiation and convection only work while the environment is cooler than the skin, so in hot surroundings evaporation is the only mechanism left. That is why anything blocking sweating, whether high humidity or gland failure, collapses heat loss entirely.","week":"3"},{"title":"Why ultraviolet exposure darkens the skin","start":"Ultraviolet radiation reaches the melanocytes scattered along the stratum basale","steps":["UV-induced DNA damage in keratinocytes and melanocytes upregulates tyrosinase inside the melanosomes","Tyrosinase oxidises tyrosine along the synthetic pathway and the melanosomes progressively fill with melanin pigment","Melanocyte dendrites deliver the pigment-loaded melanosomes into the surrounding keratinocytes","Inside each keratinocyte the melanosomes are positioned over the nucleus on the sun-facing side, forming a pigment cap","The cap absorbs incoming ultraviolet before it can reach nuclear DNA, so the skin appears darker and is better shielded"],"why":"All people carry roughly the same number of melanocytes, so differences in skin colour come from how much melanin is produced, how it is packaged, and how it is distributed among keratinocytes, never from a difference in melanocyte count.","week":"3"},{"title":"Healing of a deep cut, in causal order","start":"The blade severs dermal vessels and blood escapes into the wound","steps":["Vasoconstriction and platelet plugging arrest the bleeding, and fibrin forms a clot that dries at the surface into a scab","Inflammatory mediators make nearby capillaries leaky, and neutrophils followed by macrophages migrate in to clear bacteria and dead tissue","Macrophages release growth factors that recruit fibroblasts and drive capillary sprouting, producing red granulation tissue rich in type III collagen","Epithelial cells migrate inward from the wound edges and outward from surviving hair follicles, spreading beneath the scab until the surface is recovered","Over months the type III collagen is replaced by cross-linked type I aligned along lines of stress, the excess capillaries regress, and the scar pales and strengthens"],"why":"Each stage triggers the next, which is why blocking macrophage signalling stalls healing at inflammation and fibroblasts are never recruited. The scar never regains full strength because the regular dermal collagen weave, the follicles and the glands are replaced by dense scar rather than rebuilt.","week":"3"},{"title":"The skin's response to cold exposure","start":"Cutaneous thermoreceptors detect falling skin temperature and signal the hypothalamus","steps":["Sympathetic vasoconstrictor output to the dermal arterioles increases","Blood is shunted away from the papillary dermis through deeper arteriovenous anastomoses, so the skin pales and cools","The now cooler skin surface narrows the temperature gradient with the environment, reducing radiative and convective heat loss","Sympathetic stimulation also contracts the arrector pili muscles, raising the hairs and dimpling the skin into goosebumps","If core temperature continues to fall, the hypothalamus recruits shivering in skeletal muscle to generate additional heat"],"why":"The skin defends the core by sacrificing its own temperature. Reducing skin blood flow lowers the surface gradient and conserves heat, which is a different strategy from shivering, and the body only pays the metabolic cost of heat production once conservation proves insufficient.","week":"3"},{"title":"Why an extensive burn causes circulatory collapse","start":"Thermal energy destroys the stratum corneum and its intercellular lipid seal across a large surface area","steps":["With the waterproof barrier gone, water evaporates freely and continuously from the exposed dermis","Heat and inflammatory mediators also make the dermal capillaries leaky, so plasma escapes into the interstitium as oedema and into blisters","Circulating plasma volume falls while the burned surface keeps losing water and electrolytes to the air","Reduced blood volume lowers venous return and cardiac output, and arterial blood pressure drops","Because the losses scale with area burned, the rule of nines is used to estimate that area and calculate fluid replacement"],"why":"The immediate threat after a large burn is not the wound itself but the loss of what intact skin normally does. Watching fluid pour out of a body whose barrier has been removed is the clearest possible demonstration of the stratum corneum's everyday function.","week":"3"}]},"4":{"labs":[{"labs":[["Serum ionized calcium","down"],["Parathyroid hormone","up"],["Serum phosphate","down"],["Urinary calcium","down"],["Serum calcitriol","up"]],"opts":["Vitamin D toxicity","Normal PTH response to a low calcium intake","Calcitonin surge from thyroid C cells","Kidney failure to excrete phosphate"],"c":1,"why":"The fingerprint of PTH is that calcium and phosphate move in <b>opposite<\/b> directions. PTH pulls calcium back from the renal tubule and out of bone, but it simultaneously blocks phosphate reabsorption so the two minerals do not re-precipitate together in the blood. Falling urinary calcium with rising serum PTH means the axis is working, not failing.","week":"4"},{"labs":[["25-hydroxyvitamin D","down"],["Serum calcium","n"],["Parathyroid hormone","up"],["Serum phosphate","down"],["Alkaline phosphatase","up"]],"opts":["Immobilization bone loss","Calcitonin excess","Vitamin D deficiency with a compensatory PTH rise","Primary hyperparathyroidism"],"c":2,"why":"Without calcitriol the intestine cannot make its calcium transport proteins, so dietary calcium is barely absorbed. PTH climbs and holds serum calcium in the normal range by stripping mineral out of the skeleton. A <b>normal<\/b> calcium sitting on top of a high PTH and a high alkaline phosphatase means the bone, not the blood, is paying the bill.","week":"4"},{"labs":[["Serum calcium","down"],["Osteoclast ruffled-border activity","down"],["Urinary calcium excretion","up"],["Parathyroid hormone","up"]],"opts":["Calcitonin acting on osteoclasts","A PTH surge","Calcitriol excess","Estrogen withdrawal"],"c":0,"why":"Calcitonin is the only major hormone that speaks directly to the osteoclast, making its ruffled border retract so matrix dissolution stops. The rising PTH here is the feedback loop reacting to the falling calcium, not the cause of it, which is why reading the direction of osteoclast activity settles the question.","week":"4"},{"labs":[["Longitudinal growth rate","up"],["Epiphyseal plate width","n"],["Alkaline phosphatase for age","n"],["Serum calcium","n"],["Serum phosphate","n"]],"opts":["Osteoporosis","Rickets","Achondroplasia","Normal endochondral growth in a child"],"c":3,"why":"Alkaline phosphatase is an osteoblast enzyme, so a child laying down matrix at speed runs a value that would look high against an adult range but is normal for age. An open plate of normal width with normal mineral chemistry means cartilage is being replaced by bone as fast as it is produced, which is the definition of healthy interstitial growth.","week":"4"},{"labs":[["Alkaline phosphatase","up"],["Serum calcium","n"],["X-ray of the fracture site","abn"],["Local osteoblast activity","up"],["Parathyroid hormone","n"]],"opts":["The hematoma stage of repair","The bony (hard) callus stage of repair","Nonunion","Completed remodeling"],"c":1,"why":"Repair is osteoblast-dominated once the soft cartilaginous callus is being converted to woven bone, and osteoblasts release alkaline phosphatase as they mineralize osteoid. Systemic calcium stays normal because mineral is being redistributed to one site, not lost from the body, so a normal PTH is expected.","week":"4"},{"labs":[["Estrogen","down"],["Osteoclast activity","up"],["Bone mineral density","down"],["Serum calcium","n"],["Parathyroid hormone","n"]],"opts":["Loss of estrogen restraint on osteoclasts","Primary hyperparathyroidism","Vitamin D deficiency","Calcitonin deficiency"],"c":0,"why":"Estrogen normally shortens osteoclast lifespan and limits how deep each resorption pit gets. Remove it and resorption outruns formation even though every calcium-regulating hormone is behaving normally. That is why blood calcium is a poor screen for bone loss: the account is being drained, but the balance shown in the blood is defended.","week":"4"},{"labs":[["Serum calcium","up"],["Parathyroid hormone","up"],["Serum phosphate","down"],["Urinary calcium","up"],["Bone mineral density","down"]],"opts":["Vitamin D deficiency","Normal calcium homeostasis","Calcitonin excess","Unregulated PTH secretion"],"c":3,"why":"A rising calcium should bind the calcium-sensing receptor on the chief cells and switch PTH off. A PTH that stays high in the face of a high calcium proves the gland is driving the calcium rather than responding to it, and the low phosphate confirms PTH is the agent because it is still dumping phosphate in the urine.","week":"4"},{"labs":[["Mechanical loading of the skeleton","down"],["Urinary calcium","up"],["Bone mineral density","down"],["Parathyroid hormone","down"],["Serum calcium","n"]],"opts":["Vitamin D deficiency","Disuse (unloading) bone loss","Secondary hyperparathyroidism","Normal aging"],"c":1,"why":"Wolff's law runs in both directions: unstrained osteocytes stop restraining resorption, so bone that is not being used is dismantled. The calcium released has nowhere to go but the urine, and PTH falls because the body is now calcium-replete. A <b>suppressed<\/b> PTH is what separates mechanical bone loss from any hormone-driven cause.","week":"4"},{"labs":[["Sex steroid levels","up"],["Epiphyseal plate width","down"],["Longitudinal growth rate","down"],["Growth in bone width (appositional)","n"],["Serum calcium","n"]],"opts":["Rickets","A fracture through the growth plate","Pubertal closure of the epiphyseal plate","Normal 8-year-old skeleton"],"c":2,"why":"High sex steroid levels slow chondrocyte division in the proliferative zone so ossification finally catches up with cartilage production; the plate thins, then is replaced by the bony epiphyseal line. Length growth ends, but appositional growth from the periosteum continues, which is why bones can still thicken in adulthood.","week":"4"},{"labs":[["1,25-dihydroxyvitamin D (calcitriol)","down"],["25-hydroxyvitamin D","n"],["Serum phosphate","up"],["Serum calcium","down"],["Parathyroid hormone","up"]],"opts":["Failure of renal activation of vitamin D","Dietary calcium excess","Calcitonin excess","Disuse bone loss"],"c":0,"why":"Vitamin D takes two hydroxylations, one in the liver and the final one in the kidney. A normal storage form with a low active form localizes the block precisely to the renal 1-alpha-hydroxylase step. High phosphate is the clincher: dietary vitamin D lack lowers phosphate through PTH, but a failing kidney retains it.","week":"4"},{"labs":[["Synovial fluid clarity","n"],["Synovial fluid viscosity","n"],["Synovial fluid white cell count","n"],["Joint temperature","n"]],"opts":["Septic (infected) joint","Hemarthrosis","Normal synovial joint fluid","Gouty joint"],"c":2,"why":"Hyaluronan secreted by the synovial membrane gives normal fluid its egg-white viscosity and its transparency, and it is what lubricates and feeds the avascular articular cartilage. Any inflammatory process floods the cavity with cells and enzymes that both cloud the fluid and thin it, so a panel that is normal on every axis is itself the diagnostic finding.","week":"4"},{"labs":[["Serum ionized calcium","down"],["Serum albumin","n"],["Neuromuscular excitability","up"],["Chvostek sign","abn"],["Parathyroid hormone","up"]],"opts":["Hypercalcemia","True ionized hypocalcemia","A low-albumin artifact","Normal calcium with anxiety"],"c":1,"why":"Extracellular calcium normally sits on the outside of voltage-gated sodium channels and raises the threshold for opening. Remove it and neurons depolarize too easily, producing tetany and facial twitching. The normal albumin matters because roughly half of serum calcium is protein-bound, so a low total calcium with low albumin would be a measurement artifact rather than real.","week":"4"}],"pairs":[{"clue":"The mature bone cell sitting in a lacuna, maintaining matrix and sensing mechanical strain","a":"Osteocyte","b":"Osteoblast","why":"The osteoblast is the active builder working on a bone surface. When it walls itself into the matrix it has just secreted, it changes job description entirely and becomes an osteocyte, switching from construction to monitoring and signaling.","week":"4","c":0},{"clue":"Large multinucleated cell with a ruffled border that secretes acid and enzymes to dissolve bone matrix","a":"Osteoclast","b":"Osteoblast","why":"Beyond the clast-equals-break memory hook, these cells have different family trees: osteoclasts fuse from monocyte and macrophage precursors, while osteoblasts arise from mesenchymal osteoprogenitor cells. That is why they respond to different signals.","week":"4","c":0},{"clue":"Bone tissue built as a lattice of trabeculae aligned along lines of stress, with red marrow in the spaces","a":"Spongy (cancellous) bone","b":"Compact (cortical) bone","why":"Compact bone is the dense osteon-based outer shell engineered to transmit weight down the shaft. Spongy bone trades solid mass for struts, which keeps the skeleton light enough to move and leaves open space for blood cell production.","week":"4","c":0},{"clue":"The canal running lengthwise down the middle of an osteon, carrying its blood vessel and nerve","a":"Central (Haversian) canal","b":"Perforating (Volkmann) canal","why":"Orientation is the whole distinction. Central canals run parallel to the long axis inside each osteon; perforating canals run perpendicular, connecting the periosteal blood supply inward to those central canals.","week":"4","c":0},{"clue":"Hair-thin channels through the matrix that let osteocytes contact each other by gap junctions","a":"Canaliculi","b":"Lacunae","why":"Lacunae are the chambers that hold the cells; canaliculi are the hallways between them. Since mineralized matrix is impermeable, these channels are the only route for nutrients and waste, which is why an osteocyte cut off from them dies.","week":"4","c":0},{"clue":"Ossification that replaces a hyaline cartilage model with bone","a":"Endochondral ossification","b":"Intramembranous ossification","why":"Intramembranous ossification builds bone directly inside a fibrous membrane and produces the flat skull bones and the clavicle. Endochondral ossification needs a cartilage template first and forms every long bone, which is why only endochondral bones have growth plates.","week":"4","c":0},{"clue":"The process responsible for growth in bone LENGTH","a":"Interstitial growth at the epiphyseal plate","b":"Appositional growth beneath the periosteum","why":"Appositional growth adds bone to the outer surface and widens the shaft while osteoclasts enlarge the medullary cavity from within. Only cartilage can grow from the inside, so only the epiphyseal plate can push the epiphysis away from the diaphysis.","week":"4","c":0},{"clue":"A bone of the axial skeleton","a":"Sternum","b":"Clavicle","why":"The axial skeleton is the central column: skull, vertebrae, ribs and sternum. The clavicle belongs to the pectoral girdle, and girdles are classified with the limbs they anchor, so it is appendicular despite sitting on the trunk.","week":"4","c":0},{"clue":"A bone of the appendicular skeleton","a":"Scapula","b":"Sacrum","why":"Same rule read the other way. The scapula is part of the pectoral girdle and therefore appendicular, while the sacrum is five fused vertebrae and stays with the vertebral column in the axial skeleton.","week":"4","c":0},{"clue":"The lateral bone of the forearm, on the thumb side","a":"Radius","b":"Ulna","why":"The ulna is medial and forms the true hinge of the elbow: its trochlear notch, bounded above by the olecranon and below by the coronoid process, grips the trochlea of the humerus, and the olecranon drops into the humeral olecranon fossa at full extension. The radius is the mobile one, rolling across the ulna to produce pronation and taking most of the load at the wrist.","week":"4","c":0},{"clue":"The structural class of a skull suture","a":"Fibrous joint","b":"Synovial joint","why":"Structural classification asks what material binds the bones together, which gives fibrous, cartilaginous or synovial. Functional classification asks how much motion is allowed, which gives synarthrosis, amphiarthrosis or diarthrosis. A suture is fibrous by structure and a synarthrosis by function.","week":"4","c":0},{"clue":"The slightly movable joint between the two pubic bones","a":"Cartilaginous symphysis","b":"Fibrous syndesmosis","why":"A symphysis is united by a compressible pad of fibrocartilage that acts as a shock absorber. A syndesmosis, like the distal tibiofibular joint, is bound by a ligament or interosseous membrane. Both are amphiarthroses functionally, but the binding tissue differs.","week":"4","c":0},{"clue":"The synovial joint that permits rotation around a single longitudinal axis, as when you shake your head no","a":"Pivot joint","b":"Hinge joint","why":"Both are uniaxial, which is the trap. A hinge moves in the sagittal plane only, producing flexion and extension, while a pivot spins a rounded bony process inside a ring of bone and ligament, producing rotation.","week":"4","c":0},{"clue":"The synovial joint at the base of the thumb that allows opposition","a":"Saddle joint","b":"Condyloid joint","why":"In a saddle joint each surface is concave in one direction and convex in the other, so the bones can rock in two planes and add a conjunct rotation. A condyloid joint, like a knuckle, is biaxial too but its oval surfaces cannot produce true opposition.","week":"4","c":0},{"clue":"Turning the sole of the foot medially so it faces the midline","a":"Inversion","b":"Supination","why":"These are region-specific terms. Supination and pronation describe the forearm, where the radius rolls to turn the palm up or down. Inversion and eversion are the ankle equivalents and occur at the subtalar joint, not the talocrural hinge.","week":"4","c":0},{"clue":"A fracture in which the broken bone end has pierced the skin","a":"Open (compound) fracture","b":"Comminuted fracture","why":"These describe two independent axes. Open versus closed states whether the fracture communicates with the outside and therefore whether infection is a risk. Comminuted states that the bone shattered into three or more fragments, which speaks to healing time and stability.","week":"4","c":0},{"clue":"The incomplete fracture typical of children, where one side of the shaft bends and the other cracks","a":"Greenstick fracture","b":"Stress fracture","why":"Children's bone has a higher proportion of collagen to mineral, so it deforms before it snaps, exactly like a green twig. A stress fracture is a hairline crack from repetitive submaximal loading in fully mineralized bone, where remodeling cannot keep pace with microdamage.","week":"4","c":0},{"clue":"The hormone released when blood calcium falls","a":"Parathyroid hormone","b":"Calcitonin","why":"Both hormones come from glands in the neck, which is why they get swapped. PTH is the rescue hormone for LOW calcium and acts on bone, kidney and gut. Calcitonin comes from thyroid parafollicular cells, is released when calcium is HIGH, and does one thing: silence the osteoclast.","week":"4","c":0}],"redflags":[{"s":"A tibial fracture in which the bone end has broken through the skin","act":1,"why":"An open fracture converts the sterile marrow cavity into a contaminated wound. Cortical bone has a limited blood supply, so antibiotics and immune cells reach it poorly and a bone infection there is very difficult to clear. This needs urgent irrigation and stabilization.","week":"4"},{"s":"A firm bulge that can be felt over the site of a clavicle fracture about four weeks after the injury","act":0,"why":"That is the hard callus. Repair deliberately over-builds a bulky cuff of woven bone to splint the break, and osteoclasts will sculpt it back down over the following months during remodeling. The bump is evidence that healing is on schedule.","week":"4"},{"s":"After a forearm cast is applied, the patient reports pain out of proportion to the injury, numbness in the fingers, and a tense swollen forearm","act":1,"why":"Swelling inside a closed fascial compartment raises tissue pressure above capillary perfusion pressure, so blood cannot enter even though the pulse may still be present. Muscle and nerve begin dying within hours, making this a time-critical emergency.","week":"4"},{"s":"An alkaline phosphatase level above the adult reference range in an otherwise healthy 13-year-old","act":0,"why":"Alkaline phosphatase is released by osteoblasts as they mineralize new matrix, and an adolescent in a growth spurt is running the largest bone-building project of their life. Pediatric reference ranges are set higher precisely because of this.","week":"4"},{"s":"A 70-year-old sustains a vertebral fracture while sneezing","act":1,"why":"This is a fragility fracture: the force applied should never break healthy bone. The event is a readout of skeletal mineral density rather than of the trauma, and it predicts further fractures, so it changes management from treating a break to treating a skeleton.","week":"4"},{"s":"Painless clicking when a teenager cracks the knuckles, with full pain-free motion afterward","act":0,"why":"Pulling on the joint suddenly increases the volume of the synovial cavity, dropping the pressure so dissolved gas comes out of solution with an audible pop. Nothing in the cartilage or capsule is damaged, and the joint cannot repeat it until the gas redissolves.","week":"4"},{"s":"A serum calcium of 13.5 mg/dL in a patient who is confused, constipated and urinating excessively","act":1,"why":"High extracellular calcium raises the threshold for voltage-gated sodium channels, so neurons and smooth muscle become sluggish, producing confusion and constipation. Calcium also interferes with the kidney's response to ADH, which explains the fluid loss and worsens the calcium level further.","week":"4"},{"s":"An X-ray of a 17-year-old showing a thin dense line where the epiphyseal plate used to be","act":0,"why":"That is the epiphyseal line, the mineralized scar left after sex steroids shut down chondrocyte division and ossification consumed the last cartilage. It marks the expected end of growth in length, not an injury.","week":"4"},{"s":"Positive Trousseau sign, with carpal spasm when a blood pressure cuff is inflated, two days after thyroid surgery","act":1,"why":"The parathyroid glands sit on the posterior thyroid and can be bruised or removed during thyroid surgery. Losing PTH drops calcium quickly, and low extracellular calcium destabilizes nerve membranes so ischemia from the cuff provokes tetany.","week":"4"},{"s":"A child's fracture line that runs through the epiphyseal plate","act":1,"why":"The plate is the only tissue capable of lengthening the bone. Injury there can fuse part of the plate prematurely, so the bone either stops growing or grows asymmetrically into an angular deformity. It is managed and followed differently from a shaft fracture.","week":"4"},{"s":"Yellow fatty marrow occupying the medullary cavity of an adult femur","act":0,"why":"Red marrow is progressively converted to yellow marrow with age as hematopoietic demand falls. In adults blood cell production retreats to flat and irregular bones such as the sternum, ribs, ilium and vertebrae plus the proximal epiphyses, so a fatty femoral shaft is expected.","week":"4"},{"s":"A knee that is hot, red, exquisitely tender to any motion, with cloudy joint fluid and fever","act":1,"why":"The synovial cavity is a closed avascular space, and articular cartilage has no blood supply to deliver immune defense. Bacterial enzymes and inflammatory cells can destroy cartilage within days, and once it is gone it does not regenerate, so this is a joint emergency.","week":"4"},{"s":"Six months after a tibial fracture the gap still shows no bridging bone and the site moves under load","act":1,"why":"Bone union requires both blood supply and mechanical stability. Persistent motion at the site keeps disrupting the fragile new capillaries, so the callus differentiates into fibrous tissue rather than bone, producing a nonunion that will not heal without intervention.","week":"4"},{"s":"A 6-year-old with bowed legs, widened wrists, and delayed closure of the fontanelles","act":1,"why":"Without calcitriol the hypertrophic zone of the growth plate cannot mineralize, so cartilage piles up and the plate widens visibly at the wrists and knees. The osteoid that is laid down stays soft, and unmineralized bone bends under body weight instead of supporting it.","week":"4"}],"chains":[{"title":"Endochondral ossification of a long bone","start":"A hyaline cartilage model shaped like the future bone forms in the embryo.","steps":["A bone collar is laid down around the shaft by the periosteum while the chondrocytes at the center hypertrophy and calcify their surrounding matrix.","Cut off from diffusion, those chondrocytes die and leave cavities, and a periosteal bud carrying blood vessels and osteoprogenitor cells invades the center.","Osteoblasts deposit spongy bone on the calcified cartilage remnants, creating the primary ossification center in the diaphysis.","Osteoclasts hollow that spongy bone into the medullary cavity while secondary ossification centers appear in the epiphyses.","Cartilage survives in only two places, the articular surfaces and the epiphyseal plates, and the plates continue lengthening the bone until puberty."],"why":"Long bones are not built out of cartilage; cartilage is a temporary scaffold that gets destroyed from the inside out. Understanding that order explains why the very last cartilage to disappear is exactly the tissue responsible for growth in length.","week":"4"},{"title":"Growth in length at the epiphyseal plate","start":"Chondrocytes in the resting zone of the epiphyseal plate begin dividing.","steps":["In the proliferative zone the daughter cells stack into vertical columns, pushing the epiphysis further away from the diaphysis.","In the hypertrophic zone the older chondrocytes swell and their lacunae enlarge, adding still more length to each column.","In the calcification zone the matrix between the columns mineralizes, sealing off diffusion so those chondrocytes die.","Capillaries and osteoblasts advance from the diaphysis into the emptied lacunae and deposit bone on the calcified cartilage spicules."],"why":"The plate stays roughly the same thickness the whole time because cartilage is added on the epiphyseal side at the same rate it is replaced by bone on the diaphyseal side. Growth stops not when cartilage runs out but when division slows enough for ossification to catch up.","week":"4"},{"title":"Repair of a simple fracture","start":"The fracture tears blood vessels in the periosteum and the marrow cavity.","steps":["Blood pools and clots at the break as a fracture hematoma, and osteocytes at the fracture ends die once their canaliculi lose their blood supply.","Capillaries and fibroblasts invade the clot and chondroblasts lay down cartilage, producing a soft fibrocartilaginous callus that splints the fragments.","Osteoblasts replace that soft callus with woven spongy bone, converting it into a bulky hard bony callus that spans the break.","Osteoclasts pare away the excess bone on the outer surface while osteoblasts add compact bone along the lines of stress, restoring the original contour."],"why":"Repair recapitulates development, passing through a cartilage stage first because cartilage is avascular and can survive the low-oxygen environment of a fresh injury. It also explains why movement at the site stalls healing at the fibrous stage.","week":"4"},{"title":"The parathyroid hormone response to falling blood calcium","start":"Blood ionized calcium falls below the set point.","steps":["Calcium-sensing receptors on parathyroid chief cells detect the drop and the glands secrete parathyroid hormone.","PTH binds osteoblasts, which display RANKL and recruit osteoclasts to resorb matrix, releasing both calcium and phosphate into the blood.","PTH increases calcium reabsorption in the distal renal tubule while simultaneously blocking phosphate reabsorption so phosphate is lost in the urine.","PTH activates 1-alpha-hydroxylase in the kidney, producing calcitriol, which raises calcium absorption from the small intestine.","Rising blood calcium binds the parathyroid calcium-sensing receptors and PTH secretion shuts off."],"why":"PTH acts on three organs at once, and the phosphate-dumping step is not a side effect but a requirement: if phosphate rose along with calcium the two would precipitate back out of solution and the whole rescue would fail.","week":"4"},{"title":"The calcitonin response to rising blood calcium","start":"Blood calcium rises above the set point, for example after a large calcium load.","steps":["Parafollicular C cells in the thyroid gland sense the rise and release calcitonin.","Calcitonin binds receptors on osteoclasts and their ruffled borders retract, stopping acid and enzyme secretion onto the matrix.","With resorption suppressed, ongoing osteoblast deposition removes calcium from the blood unopposed and locks it into new matrix.","The kidney excretes more calcium in the urine and blood calcium returns toward the set point."],"why":"Calcitonin is a single-target brake on one cell type rather than a multi-organ hormone, which is why its effect is fast but modest and why it matters most during childhood growth, pregnancy and lactation rather than in routine adult regulation.","week":"4"},{"title":"Activation of vitamin D and mineralization of bone","start":"UVB light strikes 7-dehydrocholesterol in the skin.","steps":["The skin converts it to cholecalciferol, vitamin D3, which enters the circulation.","The liver hydroxylates it to 25-hydroxyvitamin D, calcidiol, the storage form that blood tests actually measure.","In the kidney, PTH-driven 1-alpha-hydroxylase adds the second hydroxyl group, producing calcitriol, the active hormone.","Calcitriol enters intestinal epithelial cells and increases production of calcium transport proteins, raising absorption of dietary calcium.","The absorbed calcium supplies the hydroxyapatite crystals that osteoblasts deposit onto the collagen osteoid they have laid down."],"why":"The hormone needs two separate organs to finish it, so skin, liver or kidney failure can each produce the same soft-bone result. Only the kidney step is hormonally regulated, and that is exactly where PTH plugs into the pathway.","week":"4"},{"title":"Mechanical loading remodels bone (Wolff's law)","start":"Repeated weight-bearing loads deform the bone matrix by a tiny amount.","steps":["That deformation drives fluid through the canaliculi, shearing the osteocyte processes running inside them.","The strained osteocytes reduce their output of sclerostin, releasing the brake on nearby osteoblasts.","Osteoblasts deposit fresh osteoid and mineralize it along the lines of stress, thickening compact bone and reorienting trabeculae toward the load.","In regions receiving no strain, osteocytes signal in the opposite direction and osteoclasts remove the bone that is no longer earning its keep."],"why":"Bone is remodeled where it is strained rather than uniformly, which is why the osteocyte, the cell that looks entombed and inactive, is actually the sensor deciding where the skeleton is reinforced and where it is dismantled.","week":"4"}]},"5":{"labs":[{"labs":[["A band width","n"],["I band width","down"],["H zone width","down"],["Sarcomere length, Z disc to Z disc","down"],["Thick filament length","n"]],"opts":["A skeletal muscle fibre in active contraction","A relaxed fibre sitting at optimal resting length","A fibre being passively stretched beyond resting length","A fibre locked in rigor after ATP has run out"],"c":0,"why":"Filaments slide past each other, they do not shorten. The A band is defined by the length of the thick filament itself, so it can never change; the I band and H zone are the two non-overlap regions, so both shrink as the thin filaments are dragged toward the M line. An unchanged A band beside a shrinking I band is the fingerprint of sliding filament contraction.","week":"5"},{"labs":[["A band width","n"],["I band width","up"],["H zone width","up"],["Thick and thin filament overlap","down"],["Maximum tension the fibre can generate","down"]],"opts":["A fibre stretched well beyond its optimal length","A fibre at optimal resting length","A fibre in mid-contraction","A fibre in fused tetanus"],"c":0,"why":"This is the descending limb of the length-tension relationship. Force depends on how many myosin heads can reach an exposed actin site, so pulling the filaments apart reduces overlap and reduces the number of possible cross-bridges even though the contractile machinery itself is perfectly healthy.","week":"5"},{"labs":[["Mitochondrial density","up"],["Myoglobin content","up"],["Capillary supply per fibre","up"],["Fibre diameter","down"],["Myosin ATPase speed","down"]],"opts":["A slow oxidative, type I fibre","A fast glycolytic, type IIx fibre","A fast oxidative-glycolytic, type IIa fibre","A smooth muscle cell"],"c":0,"why":"Everything here is built for sustained aerobic ATP production: mitochondria to make it, myoglobin and capillaries to keep oxygen arriving, and a small diameter so oxygen has a short diffusion distance to the centre of the cell. The slow ATPase is what separates type I from type IIa, which also has plenty of mitochondria but splits ATP quickly.","week":"5"},{"labs":[["Glycogen stores","up"],["Myoglobin content","down"],["Mitochondrial density","down"],["Fibre diameter","up"],["Time to fatigue","down"]],"opts":["A fast glycolytic, type IIx fibre","A slow oxidative, type I fibre","A cardiac muscle cell","A fast oxidative-glycolytic, type IIa fibre"],"c":0,"why":"Low myoglobin is why these fibres look pale, and it goes hand in hand with few mitochondria: the cell has committed to anaerobic glycolysis, which is why it stockpiles glycogen. The large diameter delivers high power but worsens oxygen diffusion, so power and rapid fatigue are two sides of the same design.","week":"5"},{"labs":[["Muscle ATP concentration","n"],["Muscle creatine phosphate","down"],["Blood lactate","up"],["Muscle pH","down"]],"opts":["A thirty second all-out sprint","Quiet standing at rest","A two hour steady jog at conversational pace","Skeletal muscle in rigor mortis"],"c":0,"why":"The clue that decides this is the normal ATP. Creatine phosphate acts as a buffer, handing its phosphate straight to ADP as fast as ATP is consumed, so measured ATP barely moves while creatine phosphate collapses. A falling creatine phosphate with rising lactate is the signature of maximal anaerobic work, not of ATP failure.","week":"5"},{"labs":[["Oxygen consumption","up"],["Ventilation rate","up"],["Blood lactate","up"],["Muscle creatine phosphate","down"],["Muscle force output","down"]],"opts":["The first minutes of recovery after intense exercise, repaying the oxygen debt","The first minutes of intense exercise","Resting baseline before any exercise","A sustained isometric contraction"],"c":0,"why":"Oxygen uptake is high while force output is zero, which only makes sense during recovery. The extra oxygen is not powering contraction; it is being spent to rebuild creatine phosphate, reload myoglobin and haemoglobin, and convert lactate back toward pyruvate and glucose.","week":"5"},{"labs":[["Motor nerve action potential","n"],["Acetylcholine released into the cleft","n"],["End plate potential amplitude","down"],["Muscle fibre action potential","down"],["Sensation in the limb","n"]],"opts":["Nicotinic receptors on the motor end plate are blocked, as with curare","Acetylcholine release from the axon terminal has failed","Acetylcholinesterase is missing from the synaptic cleft","Calcium release from the sarcoplasmic reticulum has failed"],"c":0,"why":"Normal nerve firing plus normal transmitter release localises the fault to the receiving side of the synapse, which is exactly what a receptor blocker does. Intact sensation confirms the sensory pathway is untouched, and if the sarcoplasmic reticulum were at fault the muscle action potential would still be present because that step comes after excitation.","week":"5"},{"labs":[["Acetylcholine concentration in the cleft","up"],["Duration of end plate depolarisation","up"],["Acetylcholine released per nerve impulse","n"],["Muscle response of repetitive twitching then weakness","abn"]],"opts":["Acetylcholinesterase is inhibited so acetylcholine is never cleared","Nicotinic receptors are blocked","Voltage-gated calcium channels on the axon terminal are blocked","Sarcoplasmic reticulum calcium pumps have failed"],"c":0,"why":"Release per impulse is normal, so the problem is not the nerve but the clean-up. Acetylcholinesterase normally ends the signal within milliseconds; without it the transmitter rebinds again and again, first causing repetitive firing and then holding the end plate so depolarised that sodium channels cannot reset, which produces weakness.","week":"5"},{"labs":[["Muscle ATP","down"],["Cytosolic calcium","up"],["Myosin heads bound to actin","up"],["Ability of cross-bridges to detach","down"]],"opts":["Rigor mortis after death","A normal tetanic contraction","Normal relaxation after a contraction","Short-term fatigue during a long run"],"c":0,"why":"This exposes the most counter-intuitive point in the cross-bridge cycle: ATP is needed to release myosin from actin, not to attach it. When ATP disappears, the calcium pumps also fail so calcium leaks out and keeps the binding sites exposed, and every head that attaches can never let go.","week":"5"},{"labs":[["Stimulus frequency","up"],["Cytosolic calcium between stimuli","up"],["Relaxation between stimuli","down"],["Peak tension","up"],["Number of motor units active","n"]],"opts":["Fused tetanus produced by wave summation","Recruitment of additional motor units","A single maximal twitch","Treppe, the staircase effect"],"c":0,"why":"The unchanged motor unit count rules out recruitment, so the extra force must come from within the fibres already working. Stimuli arrive faster than the sarcoplasmic reticulum can reclaim calcium, so calcium never falls off troponin, cross-bridge cycling never stops, and the individual twitches merge into a smooth plateau.","week":"5"},{"labs":[["Striations on microscopy","down"],["Troponin content","down"],["Gap junctions between cells","up"],["Nuclei per cell","n"],["Speed of contraction","down"]],"opts":["Single-unit smooth muscle","Cardiac muscle","Skeletal muscle","A fast glycolytic skeletal fibre"],"c":0,"why":"No sarcomeres means no striations and no troponin, because the thin filaments anchor to scattered dense bodies rather than to Z discs. Calcium therefore works through calmodulin and myosin light chain kinase instead of moving a blocking protein, and the gap junctions let a whole sheet contract as one slow unit.","week":"5"},{"labs":[["Striations on microscopy","n"],["Nuclei per cell","n"],["Cell-to-cell electrical coupling","up"],["Voluntary control","down"],["Spontaneous rhythmicity","up"]],"opts":["Cardiac muscle","Skeletal muscle","Multi-unit smooth muscle","A slow oxidative skeletal fibre"],"c":0,"why":"Cardiac muscle is the only tissue that is striated yet uninucleate, and the single nucleus is the fastest way to separate it from skeletal muscle at the microscope. Intercalated discs carry the coupling, which is why the tissue behaves as one functional syncytium, and pacemaker cells give it rhythm without any nerve input at all.","week":"5"}],"pairs":[{"clue":"The sarcomere band whose width does not change during contraction","a":"The A band","b":"The I band","why":"The A band is simply the length of the thick filament, and thick filaments never shorten, they only slide. The I band is the thin-filament-only region at each end of the sarcomere, so it is consumed as the thin filaments are pulled inward.","week":"5","c":0},{"clue":"The structure that anchors thin filaments and defines the boundary of one sarcomere","a":"The Z disc","b":"The M line","why":"Both are protein anchoring plates, which is why they are swapped. The Z disc sits at each end of the sarcomere and holds the thin filaments, so Z disc to Z disc is the definition of sarcomere length; the M line sits in the centre and holds the thick filaments in register.","week":"5","c":0},{"clue":"The region of the sarcomere that contains thick filaments only","a":"The H zone","b":"The I band","why":"Both are regions of no overlap, which is why they are confused. The H zone sits in the centre of the A band where thin filaments have not yet reached, while the I band sits at the sarcomere ends where thick filaments do not reach.","week":"5","c":0},{"clue":"The regulatory protein that actually binds calcium in skeletal muscle","a":"Troponin","b":"Tropomyosin","why":"Troponin C is the calcium receptor and acts as the switch. Tropomyosin is the rope lying in the groove of actin that physically covers the myosin-binding sites, and it moves only because troponin changes shape and drags it aside.","week":"5","c":0},{"clue":"The membrane structure that carries the action potential deep into the fibre","a":"The T tubule","b":"The sarcoplasmic reticulum","why":"A T tubule is an inward fold of the sarcolemma, so it is open to extracellular fluid and can conduct an action potential. The sarcoplasmic reticulum is a closed internal store that holds calcium and never carries an impulse.","week":"5","c":0},{"clue":"The channel that actually releases stored calcium into the cytosol","a":"The ryanodine receptor on the terminal cisternae","b":"The dihydropyridine receptor on the T tubule","why":"These two are physically linked, which is why students swap them. The dihydropyridine receptor is the voltage sensor that detects the action potential; the ryanodine receptor is the gate it mechanically pulls open.","week":"5","c":0},{"clue":"The connective tissue sheath that surrounds a single muscle fibre","a":"Endomysium","b":"Perimysium","why":"Endo means within, so endomysium wraps one cell and carries the capillaries and nerve endings that serve it. Perimysium bundles many fibres together into a fascicle and carries the larger vessels running between bundles.","week":"5","c":0},{"clue":"The attachment of a muscle that stays relatively fixed while the muscle shortens","a":"The origin","b":"The insertion","why":"Muscles pull the insertion toward the origin, so the origin is usually the more proximal and more stable bone. Identifying the origin correctly is what lets you predict the direction of movement from the attachments alone.","week":"5","c":0},{"clue":"The muscle chiefly responsible for producing a given movement","a":"The agonist, or prime mover","b":"A synergist","why":"A synergist adds force to the same movement or stabilises an intervening joint so the prime mover's pull is not wasted. The agonist is the one whose contraction alone would still produce the motion.","week":"5","c":0},{"clue":"The muscle that opposes the prime mover and must relax for the movement to occur","a":"The antagonist","b":"A fixator","why":"An antagonist acts in the opposite direction across the same joint and is reciprocally inhibited during movement. A fixator instead immobilises the origin bone so the prime mover has a stable base to pull against.","week":"5","c":0},{"clue":"The energy source that regenerates ATP during the first ten to fifteen seconds of maximal effort","a":"Creatine phosphate","b":"Anaerobic glycolysis","why":"Creatine kinase moves a phosphate group straight onto ADP in one enzymatic step, so it is nearly instantaneous but tiny in capacity. Glycolysis requires many sequential steps and a supply of glycogen, so it ramps up only as creatine phosphate falls.","week":"5","c":0},{"clue":"The enzyme that terminates the signal at the neuromuscular junction","a":"Acetylcholinesterase","b":"Choline acetyltransferase","why":"Acetylcholinesterase sits in the synaptic cleft attached to the basement membrane and splits acetylcholine into acetate and choline within milliseconds. Choline acetyltransferase works inside the neuron doing the opposite job, rebuilding acetylcholine from recycled choline.","week":"5","c":0},{"clue":"One motor neuron together with every muscle fibre it innervates","a":"A motor unit","b":"A fascicle","why":"A motor unit is a functional grouping defined by innervation, and its fibres are scattered through the muscle so that recruiting one unit produces weak, evenly spread tension. A fascicle is an anatomical bundle wrapped in perimysium and contains fibres belonging to many different motor units.","week":"5","c":0},{"clue":"A contraction in which the muscle generates tension but does not change length","a":"An isometric contraction","b":"An isotonic contraction","why":"Isometric means same length: the load exceeds the force generated, so cross-bridges cycle and consume ATP without net filament sliding. Isotonic means constant tension, and there the load is overcome so the bone actually moves.","week":"5","c":0},{"clue":"The contraction in which the muscle lengthens while still producing force","a":"An eccentric contraction","b":"A concentric contraction","why":"In an eccentric contraction the external load exceeds muscle force, so attached cross-bridges are torn apart as the muscle pays out under control. That high strain on the Z discs is why lowering a weight or running downhill causes the most soreness, whereas a concentric contraction shortens the muscle.","week":"5","c":0},{"clue":"The rise in force produced when stimuli arrive faster than the fibre can fully relax","a":"Wave summation","b":"Recruitment","why":"Wave summation is a frequency effect inside fibres that are already active, caused by cytosolic calcium not having time to be pumped back into the sarcoplasmic reticulum. Recruitment is a numbers effect, the nervous system switching on additional and progressively larger motor units.","week":"5","c":0},{"clue":"The lever system operating when biceps brachii flexes the elbow","a":"A third-class lever, with the effort between the fulcrum and the load","b":"A second-class lever, with the load between the fulcrum and the effort","why":"The insertion on the radius lies between the elbow joint, which is the fulcrum, and the weight in the hand, which is the load. Placing the effort in the middle sacrifices force for speed and range of motion, whereas a second-class lever such as rising onto the toes places the load in the middle and favours force.","week":"5","c":0},{"clue":"What the word rectus tells you in the name rectus abdominis","a":"The direction of the fibres, running straight and parallel to the midline","b":"The relative size of the muscle within its group","why":"Muscle names encode several different attributes at once, and mixing the categories is the usual error. Direction terms are rectus, oblique and transversus; size terms are maximus, minimus, longus and brevis; other parts of a name may give shape, number of heads, attachments or action.","week":"5","c":0}],"redflags":[{"s":"Cola-coloured urine with severe, generalised muscle aching two days after an extreme unaccustomed workout","act":1,"why":"Myoglobin released from broken fibres is small enough to be filtered by the glomerulus, so it pigments the urine and can obstruct the tubules. Muscle protein appearing in urine is never part of a normal training response.","week":"5"},{"s":"Deep muscle soreness and stiffness that begins about a day after downhill running and fades over three to four days","act":0,"why":"Delayed onset muscle soreness follows the microscopic Z-disc strain of eccentric loading, where cross-bridges are pulled apart while still attached. The inflammation and repair that follow are the very process that produces adaptation.","week":"5"},{"s":"Drooping eyelids and double vision that are mild on waking and clearly worse by evening, with completely normal sensation","act":1,"why":"Weakness that worsens with repeated use and spares sensation points to failure of transmission at the neuromuscular junction. As the readily releasable pool of acetylcholine falls with each impulse, a junction with too few working receptors drops below threshold.","week":"5"},{"s":"Breathing and heart rate remaining elevated for several minutes after a hard flight of stairs, then settling on their own","act":0,"why":"This is repayment of the oxygen debt. Oxygen is still required after the work has stopped in order to reload myoglobin, resynthesise creatine phosphate and clear accumulated lactate, so ventilation cannot return to baseline the instant the muscle stops.","week":"5"},{"s":"A sudden pop at the back of the ankle with a palpable gap above the heel and complete inability to push off","act":1,"why":"A ruptured tendon can no longer transmit force from the muscle belly to the bone. That is why the action is lost entirely rather than merely weakened, and why the muscle belly retracts and bunches up.","week":"5"},{"s":"A calf cramp during a long run that releases with passive stretching and does not return","act":0,"why":"A cramp is a burst of uncontrolled motor unit firing, favoured by fatigue and by fluid or electrolyte shifts. Stretching loads the Golgi tendon organ, which inhibits the alpha motor neuron and breaks the cycle, and full function returns at once.","week":"5"},{"s":"Rapidly rising body temperature, generalised muscle rigidity and dark urine developing shortly after a general anaesthetic","act":1,"why":"An abnormal ryanodine receptor dumps calcium out of the sarcoplasmic reticulum continuously, so cross-bridges cycle without stopping. The heat is the waste product of runaway ATP hydrolysis and the rigidity is contraction that cannot be switched off.","week":"5"},{"s":"A four-year-old boy whose calves look unusually large but who is progressively weaker and walks his hands up his thighs to stand","act":1,"why":"Size and strength have become uncoupled here: the bulk is fat and fibrous tissue replacing lost fibres, not working contractile protein. Progressive weakness in a growing child is the opposite of the expected developmental trend.","week":"5"},{"s":"A cyclist whose resting heart rate has fallen and whose thigh muscles are visibly larger after six months of training","act":0,"why":"This is hypertrophy plus cardiovascular adaptation, both normal responses to repeated overload. Skeletal muscle grows by adding myofibrils and sarcomeres to existing fibres rather than by producing new fibres.","week":"5"},{"s":"Visible rippling twitches under the skin together with progressive weakness and visible wasting of the small hand muscles","act":1,"why":"Fasciculation combined with atrophy and weakness suggests the motor neuron itself is degenerating. Fibres that lose their innervation also lose the trophic support that maintains them, so the muscle shrinks as well as weakens.","week":"5"},{"s":"Brief painless twitching of one eyelid or one calf after a poor night of sleep and several coffees, with full strength preserved","act":0,"why":"Benign fasciculation reflects spontaneous firing of excitable axon terminals, not loss of the motor unit. The absence of any weakness or wasting tells you the neuron and the fibres it supplies are structurally intact.","week":"5"},{"s":"Being unable to let go after a firm handshake, with the hand unclenching only slowly over several seconds","act":1,"why":"Delayed relaxation means the sarcolemma keeps firing after the stimulus has ended, so calcium keeps being released and cross-bridges keep cycling. That is a membrane ion channel problem, and it is distinguishable from fatigue because the muscle is too active rather than too weak.","week":"5"},{"s":"A forearm that is tense and rock hard after a fracture, with pain far out of proportion, numbness, and severe pain on passive stretch of the fingers","act":1,"why":"Pressure inside a closed fascial compartment has risen above capillary perfusion pressure, so the muscle is ischaemic even while a distal pulse can still be felt. Stretching an already ischaemic muscle is what makes the pain disproportionate.","week":"5"},{"s":"Legs feeling heavy and shaky immediately after an all-out sprint, with normal strength restored within about ten minutes","act":0,"why":"This is short-term fatigue arising inside the fibre from accumulated inorganic phosphate, disturbed sodium and potassium gradients and reduced calcium release. It reverses as the pumps restore those gradients and creatine phosphate is regenerated.","week":"5"}],"chains":[{"title":"Signal transfer across the neuromuscular junction","start":"An action potential travels down the motor neuron and arrives at the axon terminal","steps":["Voltage-gated calcium channels in the terminal membrane open and calcium enters from the extracellular fluid","Calcium causes synaptic vesicles to fuse with the presynaptic membrane and release acetylcholine into the synaptic cleft","Acetylcholine diffuses across the cleft and binds nicotinic receptors on the motor end plate","The receptor channels open, sodium entry outweighs potassium exit, and a local end plate potential depolarises the sarcolemma","The end plate potential reaches threshold, voltage-gated sodium channels open, and an action potential spreads across the whole sarcolemma"],"why":"Each step converts the signal into a different currency, electrical to chemical and back to electrical, and every conversion is a place the sequence can be interrupted. Calcium entry into the terminal is the specific trigger for release, which is why blocking terminal calcium channels silences the muscle even though the nerve is firing perfectly.","week":"5"},{"title":"Excitation-contraction coupling","start":"An action potential sweeps along the sarcolemma of the muscle fibre","steps":["The impulse travels into the T tubules, carrying depolarisation deep between the myofibrils so the centre of the fibre is excited at the same instant as the surface","Dihydropyridine receptors embedded in the T tubule membrane sense the voltage change and alter their shape","That shape change mechanically pulls open the ryanodine receptors on the adjacent terminal cisternae of the sarcoplasmic reticulum","Stored calcium floods into the cytosol and calcium concentration rises roughly a hundredfold","Calcium binds troponin C, troponin rotates tropomyosin off the myosin-binding sites on actin, and cross-bridge formation becomes possible"],"why":"This chain explains why a fibre contracts as a whole rather than only at its surface, and why calcium is called the coupler between excitation and contraction. Troponin is the only calcium receptor in skeletal muscle, so no amount of depolarisation can generate force until calcium reaches it.","week":"5"},{"title":"The cross-bridge cycle","start":"Binding sites on actin are exposed and ATP has already been hydrolysed on the myosin head, leaving it cocked and energised","steps":["The energised myosin head binds the exposed site on actin, forming a cross-bridge","Inorganic phosphate is released and the head pivots toward the M line in the power stroke, dragging the thin filament inward","ADP is released and the head is left tightly bound to actin in the low-energy rigor state","A fresh ATP molecule binds the myosin head, which weakens its affinity for actin so the head detaches","Myosin ATPase splits that ATP and re-cocks the head, ready to repeat the cycle for as long as calcium remains elevated"],"why":"ATP is used twice in this cycle for two different jobs: hydrolysis cocks the head, but simple binding is what releases it from actin. That distinction is exactly why a muscle with no ATP left locks up rigidly instead of going limp.","week":"5"},{"title":"Switching contraction off","start":"The motor neuron stops firing","steps":["Acetylcholinesterase in the synaptic cleft splits the remaining acetylcholine into acetate and choline within milliseconds","End plate channels close, the sarcolemma repolarises, and no further action potentials travel down the T tubules","SERCA pumps in the sarcoplasmic reticulum membrane spend ATP to move calcium back into storage against its gradient","Cytosolic calcium falls and calcium dissociates from troponin C","Tropomyosin slides back over the myosin-binding sites, cross-bridges can no longer form, and the fibre is returned to resting length by elastic recoil, gravity or an antagonist muscle"],"why":"Relaxation is an active, ATP-consuming process, which surprises students who assume switching off is free. It also explains why a muscle cannot lengthen itself: something external must pull the sarcomere back out once the cross-bridges have released.","week":"5"},{"title":"The ATP supply sequence in working muscle","start":"A rested muscle begins to contract, drawing on the small pool of ATP already sitting in the cytosol","steps":["The stored ATP is enough for only a few seconds of maximal activity","Creatine kinase transfers a phosphate group from creatine phosphate directly to ADP, regenerating ATP for roughly the next ten to fifteen seconds","As creatine phosphate falls, anaerobic glycolysis breaks glycogen down to pyruvate for two ATP per glucose, and pyruvate is converted to lactate so glycolysis can keep running without oxygen","If effort continues at a lower intensity, oxygen delivery catches up and pyruvate enters the mitochondria for aerobic respiration, yielding far more ATP per glucose","As glycogen dwindles over prolonged moderate work, fatty acid oxidation takes over as the dominant aerobic fuel"],"why":"The systems hand off in order of speed rather than in order of size, and speed and capacity trade off against each other. The fastest source has the smallest reserve, so the intensity of the effort dictates which pathway dominates and therefore how long the effort can be sustained.","week":"5"},{"title":"Repaying the oxygen debt","start":"Intense exercise stops and the muscle falls silent","steps":["Oxygen consumption and ventilation remain well above resting level even though no external work is being performed","Oxygen reloads onto myoglobin inside the fibres and onto haemoglobin in the blood","Aerobic ATP production resynthesises creatine phosphate and restores the cytosolic ATP pool","Lactate is taken up and reconverted to pyruvate in muscle and heart, or carried to the liver and rebuilt into glucose","Elevated body temperature, heart rate and ventilation drift back down to baseline as the last of these stores are restored"],"why":"The extra oxygen is not paying for the contraction that already happened; it is paying to rebuild the stores and gradients that the contraction spent. That is precisely why heavy breathing outlasts the exercise instead of stopping with it.","week":"5"},{"title":"Grading the force of a whole muscle","start":"A single threshold stimulus produces one twitch in one small motor unit","steps":["The latent period, contraction phase and relaxation phase all complete before the next stimulus arrives, so tension falls back to zero","Stimuli begin arriving faster than the sarcoplasmic reticulum can reclaim calcium, so a second twitch adds onto the residual tension of the first in wave summation","At higher frequency the fibre only partially relaxes between stimuli, producing unfused tetanus with a visibly rippling force trace","At high enough frequency relaxation disappears entirely, calcium stays high, and tension plateaus at fused tetanus, several times the force of a single twitch","The nervous system adds further force by recruiting additional motor units, activating the smallest and most fatigue-resistant ones first and the largest last"],"why":"Force is graded in two independent ways, and confusing them is the classic exam error. Frequency raises force within units that are already firing because calcium accumulates in the cytosol, while recruitment raises force by increasing how many units are firing at all.","week":"5"}]},"6":{"labs":[{"labs":[["Na+ influx into the axon","up"],["K+ efflux","n"],["Membrane potential moving toward 0 mV and above","up"],["Voltage-gated Na+ activation gates","abn"]],"opts":["Repolarizing phase","Depolarizing (rising) phase of the action potential","Resting membrane potential","Hyperpolarizing undershoot"],"c":1,"why":"The discriminator is the <b>lag<\/b> between the two channel types. At threshold the fast voltage-gated Na+ activation gates open in a fraction of a millisecond while the slow K+ channels have barely begun to respond, so inward positive current has nothing opposing it. Each Na+ that enters depolarizes the membrane further and opens still more Na+ channels, a positive-feedback loop that carries the potential up regardless of how strong the original stimulus was.","week":"6"},{"labs":[["Na+ influx","down"],["K+ efflux","up"],["Membrane potential returning toward -70 mV","down"],["Ability to fire a second action potential","down"]],"opts":["Depolarizing phase","Threshold being crossed","Repolarizing phase","Fully recovered resting neuron"],"c":2,"why":"Two independent events end the spike at once: the Na+ <b>inactivation<\/b> gate (a separate gate from the activation gate) swings shut and stops the inward current, and the slow voltage-gated K+ channels finally open and let positive charge leave. Because those Na+ channels cannot be reopened until the membrane repolarizes, the cell is in its absolute refractory period, which is why no second impulse is possible no matter how strong the stimulus.","week":"6"},{"labs":[["Membrane potential compared with -70 mV","down"],["K+ efflux","up"],["Na+ inactivation gates (now reset)","n"],["Stimulus strength needed to fire again","up"]],"opts":["Absolute refractory period","Relative refractory period during the hyperpolarizing undershoot","Peak of the action potential","Ordinary resting neuron"],"c":1,"why":"The reset Na+ gates are the key finding. Slow K+ channels close late, so extra K+ escapes and drives the potential below rest; but with the Na+ channels available again the cell is not dead to stimulation, merely further from threshold. That combination, excitable but harder to excite, is the definition of the relative refractory period and it is what sets the maximum firing frequency of a neuron.","week":"6"},{"labs":[["Intracellular K+ compared with extracellular","up"],["Intracellular Na+ compared with extracellular","down"],["Membrane potential","n"],["Membrane permeability to K+ versus Na+","up"]],"opts":["A neuron at its resting membrane potential","A neuron at the peak of an action potential","A neuron whose Na+/K+ pump has been poisoned","A neuron in the absolute refractory period"],"c":0,"why":"All four values being at their normal set points is itself the signature. The resting potential is a <b>permeability<\/b> phenomenon, not a pumping phenomenon: because the membrane holds far more K+ leak channels than Na+ leak channels, K+ escapes faster than Na+ enters and leaves impermeant proteins and phosphates behind, settling the interior near -70 mV, just short of the potassium equilibrium potential.","week":"6"},{"labs":[["Intracellular Na+","up"],["Intracellular K+","down"],["Negativity of the resting membrane potential","down"],["Number of action potentials the axon can sustain","down"]],"opts":["A local anesthetic blocking voltage-gated Na+ channels","Loss of the myelin sheath","Inhibition of the Na+/K+ ATPase","Blockade of postsynaptic acetylcholine receptors"],"c":2,"why":"Only pump failure changes the ion <b>concentrations<\/b> themselves. The ATPase exports three Na+ for every two K+ it imports; stop it and the gradients bleed away, the potassium equilibrium potential drifts toward zero, and the membrane rests less negative. Channel blockers and demyelination leave the gradients intact, which is why they never show this collapse of intracellular Na+ and K+.","week":"6"},{"labs":[["Resting membrane potential","n"],["Na+/K+ pump activity","n"],["Graded potential at the stimulus site","n"],["Action potential propagated down the axon","down"]],"opts":["Voltage-gated Na+ channels blocked","Na+/K+ ATPase inhibited","Choroid plexus secretion reduced","Extracellular K+ elevated"],"c":0,"why":"The normal resting potential and normal graded potential prove the pump and the leak channels are fine and that the stimulus did reach the membrane. What fails is the regenerative step: with the voltage-gated Na+ channels plugged, threshold can be reached and still nothing happens, so the all-or-none spike is never launched and the pain signal never leaves the region.","week":"6"},{"labs":[["Conduction velocity along the axon","down"],["Current leaking across the internodal membrane","up"],["Voltage-gated Na+ channel density at the nodes","n"],["Resting membrane potential","n"]],"opts":["Damage to the sensory receptor","Loss of the myelin sheath","Failure of synaptic vesicle release","Failure of the Na+/K+ pump"],"c":1,"why":"Myelin contributes nothing to the ion gradients, so a normal resting potential and normal nodal channel density point away from pump or channel problems. Its job is insulation: high membrane resistance forces local current to travel inside the axoplasm to the next node instead of leaking outward. Strip it and the local depolarization decays before it can bring the next node to threshold, so conduction slows or fails outright.","week":"6"},{"labs":[["CSF clarity","n"],["CSF glucose (about two-thirds of blood glucose)","n"],["CSF protein","n"],["White blood cells in CSF","n"]],"opts":["Blood in the subarachnoid space","Bacterial infection of the meninges","Normal cerebrospinal fluid from the subarachnoid space","Obstruction of the cerebral aqueduct"],"c":2,"why":"An entirely normal panel is a positive finding, because it demonstrates what the blood-CSF barrier does. Tight-junctioned ependymal cells of the choroid plexus secrete a selectively modified filtrate rather than letting plasma leak through, so cells and large proteins are excluded while glucose crosses by carrier transport and equilibrates to roughly two-thirds of the blood level.","week":"6"},{"labs":[["Heart rate","up"],["Pupil diameter","up"],["Bronchiole diameter","up"],["Gastrointestinal motility and secretion","down"],["Blood flow to skeletal muscle","up"]],"opts":["Parasympathetic (vagal) discharge","Sympathetic mass discharge","Somatic motor activation alone","Complete loss of autonomic tone"],"c":1,"why":"The giveaway is that many unrelated organs move together and in opposite directions. One sympathetic preganglionic neuron diverges onto many postganglionic neurons and the adrenal medulla adds a hormonal arm, so norepinephrine and epinephrine hit beta-1 receptors on the heart, beta-2 receptors in bronchioles and muscle vessels, and alpha receptors in gut and skin vessels simultaneously.","week":"6"},{"labs":[["Heart rate","down"],["Pupil diameter","down"],["Salivary and digestive secretion","up"],["Bronchiole diameter","down"]],"opts":["Craniosacral (parasympathetic) outflow","Thoracolumbar (sympathetic) outflow","Epinephrine released from the adrenal medulla","Blockade of acetylcholine at ganglionic nicotinic receptors"],"c":0,"why":"These are the effects of acetylcholine at muscarinic receptors, delivered mainly by the vagus and by the oculomotor nerve to the pupil. Parasympathetic ganglia sit on or inside the target organ and each preganglionic fiber diverges very little, which is why the response is organ-specific and reversible rather than the whole-body surge seen with sympathetic discharge.","week":"6"},{"labs":[["Extracellular K+","up"],["Outward K+ leak at rest","down"],["Negativity of the resting membrane potential","down"],["Gap between resting potential and threshold","down"]],"opts":["Falling extracellular K+ hyperpolarizing the membrane","Rising extracellular K+ moving the resting potential closer to threshold","Blocked K+ leak channels with normal extracellular K+","Rising extracellular Na+"],"c":1,"why":"The resting potential tracks the potassium equilibrium potential. Raising K+ outside the cell shrinks the concentration gradient that drives K+ out, so less positive charge leaves and the interior sits less negative. The cell now needs a smaller stimulus to reach threshold, which is exactly why potassium is the ion that most directly changes the excitability of nerve and muscle.","week":"6"},{"labs":[["Acetylcholine concentration in the synaptic cleft","up"],["Duration of the postsynaptic depolarization","up"],["Acetylcholine released per impulse","n"],["Number of postsynaptic receptors","n"]],"opts":["Fewer vesicles released per impulse","Postsynaptic receptors blocked","Acetylcholinesterase inhibited","Transmitter reuptake accelerated"],"c":2,"why":"Normal release and normal receptor numbers localize the defect to signal <b>termination<\/b>. A chemical synapse is normally shut off within about a millisecond because acetylcholinesterase in the cleft hydrolyzes the transmitter; block the enzyme and the same amount of acetylcholine binds the same receptors over and over, stretching a brief EPSP into a prolonged depolarization.","week":"6"}],"pairs":[{"clue":"The glial cell that myelinates axons in the central nervous system","a":"Oligodendrocyte","b":"Schwann cell","why":"Both make myelin, but the geometry differs and that difference has consequences. One oligodendrocyte extends several flat processes and myelinates internodes on many different CNS axons, so it cannot easily rebuild a damaged segment. A Schwann cell wraps its entire body around a single internode of one PNS axon and survives injury, leaving a hollow tube that a regrowing axon can follow, which is why peripheral nerves regenerate and central ones largely do not.","week":"6","c":0},{"clue":"The most abundant glial cell of the CNS, whose end-feet wrap capillaries and help establish the blood-brain barrier","a":"Astrocyte","b":"Microglia","why":"Astrocytes are the large star-shaped structural and metabolic partners of neurons: they anchor neurons to blood vessels, induce the tight junctions that make the blood-brain barrier, and mop up excess K+ and neurotransmitter from the extracellular fluid. Microglia are small, are the only glia derived from blood monocytes rather than neural tissue, and act as the resident phagocytes of the CNS.","week":"6","c":0},{"clue":"The structure that produces cerebrospinal fluid","a":"Choroid plexus","b":"Arachnoid granulations","why":"These sit at opposite ends of the same one-way circuit. The choroid plexus is a capillary tuft covered by ependymal cells inside each ventricle that actively secretes CSF. Arachnoid granulations are tufts of arachnoid pushing into the dural venous sinuses that act as one-way valves returning CSF to venous blood. Production feeds the loop, reabsorption drains it, and the two are normally matched.","week":"6","c":0},{"clue":"The meningeal layer that clings directly to the brain surface, dipping into every gyrus and sulcus","a":"Pia mater","b":"Arachnoid mater","why":"Pia is the delicate innermost membrane fused to the nervous tissue itself and it follows every contour. Arachnoid is the middle web-like layer that bridges straight over sulci rather than dipping into them, and the gap this creates between arachnoid and pia is the subarachnoid space where CSF and the cerebral vessels actually run.","week":"6","c":0},{"clue":"The space that normally contains circulating cerebrospinal fluid","a":"Subarachnoid space","b":"Subdural space","why":"The subarachnoid space is a genuine anatomical space between arachnoid and pia, filled with CSF, and it is the space entered by a lumbar puncture. The subdural space is only a <b>potential<\/b> space; arachnoid is normally pressed against dura and the space exists only when a bridging vein tears and forces the layers apart.","week":"6","c":0},{"clue":"The brain region containing the cardiac, vasomotor, and respiratory rhythm centers","a":"Medulla oblongata","b":"Hypothalamus","why":"The medulla is the output stage. It holds the autonomic nuclei that directly drive heart rate, vessel diameter, and breathing rhythm, and it is where the vagus originates. The hypothalamus is the higher-level integrator that sets homeostatic targets for temperature, hunger, thirst and hormone release, and it achieves them by commanding the medulla and the pituitary rather than by acting on organs itself.","week":"6","c":0},{"clue":"The region that coordinates balance, posture, and the timing and smoothness of voluntary movement","a":"Cerebellum","b":"Basal nuclei","why":"The cerebellum receives a copy of the motor command plus continuous proprioceptive feedback, compares intended with actual movement, and sends error corrections; damage produces clumsy, poorly timed, uncoordinated movement. The basal nuclei act earlier in the sequence, helping to start desired movements, suppress unwanted ones, and set background muscle tone.","week":"6","c":0},{"clue":"The relay station where nearly all sensory information except smell is sorted and edited before reaching the cerebral cortex","a":"Thalamus","b":"Hypothalamus","why":"The thalamus is the sensory gateway of the diencephalon; every ascending pathway except olfaction synapses there before cortex. The hypothalamus lies beneath it, and the prefix describes position only, not function, since its role is autonomic and endocrine control. Olfaction is the exception because smell projects directly to the cortex, an evolutionary holdover.","week":"6","c":0},{"clue":"The lobe containing the primary motor cortex on the precentral gyrus","a":"Frontal lobe","b":"Parietal lobe","why":"The central sulcus is the landmark that separates them. The gyrus immediately in front of the sulcus is motor output (precentral, frontal); the gyrus immediately behind it is somatosensory input (postcentral, parietal). Both carry an inverted body map with disproportionately large hand and face representation, which is why students mistake one homunculus for the other.","week":"6","c":0},{"clue":"The neuron carrying a signal from a peripheral receptor toward the central nervous system","a":"Sensory (afferent) neuron","b":"Motor (efferent) neuron","why":"Afferent means arriving, efferent means exiting, and the cell body locations follow that logic. A sensory neuron is usually unipolar with its cell body parked outside the CNS in the dorsal root ganglion, so its process runs from receptor to cord uninterrupted. The motor neuron is multipolar with its cell body inside the ventral horn of the cord.","week":"6","c":0},{"clue":"The spinal nerve root carrying motor commands away from the spinal cord","a":"Ventral (anterior) root","b":"Dorsal (posterior) root","why":"Ventral root axons arise from the multipolar motor neurons of the ventral horn and leave the cord, which is why the ventral root has no ganglion on it. The dorsal root carries sensory axons inward, and because their cell bodies are clustered outside the cord it carries the visible bead of the dorsal root ganglion. The two merge distally into a mixed spinal nerve.","week":"6","c":0},{"clue":"The interval during which no stimulus, however strong, can trigger a second action potential","a":"Absolute refractory period","b":"Relative refractory period","why":"The distinction is whether the Na+ channels are physically available. During the absolute period the inactivation gates are shut and cannot reopen until the membrane repolarizes, so stimulus strength is irrelevant. During the relative period those gates have reset but the membrane is hyperpolarized and further from threshold, so a stronger than normal stimulus will succeed.","week":"6","c":0},{"clue":"The membrane change that varies in size with stimulus strength, can summate, and fades with distance","a":"Graded potential","b":"Action potential","why":"Graded potentials arise from ligand-gated or mechanically gated channels; the current leaks back out as it spreads, so amplitude decays and only summation at the axon hillock can push the cell to threshold. The action potential is regenerated at every step by voltage-gated channels, so it is all-or-none, constant in amplitude, and does not weaken along the axon no matter how far it travels.","week":"6","c":0},{"clue":"The autonomic division whose preganglionic neurons arise from the lateral horns of thoracic and upper lumbar cord segments","a":"Sympathetic division","b":"Parasympathetic division","why":"Sympathetic outflow is thoracolumbar with short preganglionic fibers ending in the sympathetic chain close to the cord and long postganglionic fibers fanning out, which supports mass discharge. Parasympathetic outflow is craniosacral with long preganglionic fibers reaching ganglia on or inside the target organ and very short postganglionic fibers, which keeps its effects local and discrete.","week":"6","c":0},{"clue":"The neurotransmitter released by every preganglionic autonomic neuron, sympathetic and parasympathetic alike","a":"Acetylcholine","b":"Norepinephrine","why":"Every autonomic ganglionic synapse is cholinergic and acts on nicotinic receptors, so the divisions are indistinguishable at that first synapse. They diverge only at the second neuron: parasympathetic postganglionic fibers stay cholinergic on muscarinic receptors, while sympathetic postganglionic fibers switch to norepinephrine, with sweat glands as the classic cholinergic exception.","week":"6","c":0},{"clue":"The arrangement that produces the fastest conduction along an axon","a":"Large-diameter myelinated axon using saltatory conduction","b":"Large-diameter unmyelinated axon","why":"Diameter helps by lowering internal resistance to current flow, so a fat axon does beat a thin one. But insulation is the far larger multiplier: myelin blocks ion movement across the internode so current is forced to the next node of Ranvier, and only the nodes, where voltage-gated Na+ channels are densely packed, must be brought to threshold.","week":"6","c":0},{"clue":"The name for a cluster of neuron cell bodies located inside the central nervous system","a":"Nucleus","b":"Ganglion","why":"The vocabulary depends on address, not structure. Cell body clusters are nuclei in the CNS and ganglia in the PNS, and the parallel rule applies to axons: a bundle is a tract centrally and a nerve peripherally. This is why the dorsal root ganglion sits outside the cord while the sensory relay it projects to is called a nucleus.","week":"6","c":0},{"clue":"In a cross-section of the spinal cord, where the neuron cell bodies and unmyelinated processes lie","a":"Gray matter, in the central butterfly-shaped region","b":"White matter, in the outer region","why":"The cord is arranged opposite to the cerebrum: gray inside, white outside. Whiteness comes from the lipid of myelin, so the outer rim is entirely ascending and descending myelinated tracts, while the inner butterfly holds cell bodies, dendrites and synapses. That is why a reflex is integrated centrally in the cord and long-distance signals travel peripherally in it.","week":"6","c":0}],"redflags":[{"s":"Clear fluid draining from the nose after a head injury that tests positive for glucose","act":1,"why":"Nasal mucus contains essentially no glucose, but CSF is a glucose-containing filtrate. Glucose-positive drainage means the meninges and a skull base bone, usually the cribriform plate, have been breached, so the sterile subarachnoid space is now open to the outside.","week":"6"},{"s":"Fever with a stiff neck, headache, and intolerance of bright light","act":1,"why":"Inflamed meninges become exquisitely pain-sensitive, so flexing the neck and stretching them provokes reflex resistance. The concern is anatomical: the subarachnoid space is one continuous fluid compartment surrounding the entire brain and cord, so an infection seeded there is not contained locally.","week":"6"},{"s":"One pupil dilated and unresponsive to light while the other reacts normally","act":1,"why":"The parasympathetic constrictor fibers travel on the surface of the oculomotor nerve, so they are the first fibers compressed when pressure inside the skull rises. Losing them unopposes the sympathetic dilator, and the asymmetry indicates a one-sided mass effect rather than any normal variation in pupil size.","week":"6"},{"s":"Sudden loss of sensation and voluntary movement below a single body level after a fall","act":1,"why":"Every ascending and descending pathway to the lower body is funneled through the white matter of the cord. Damage at one level therefore interrupts all of them at once, and everything below is disconnected from the brain even though the cord segments and reflex arcs down there may still be intact.","week":"6"},{"s":"A positive Babinski sign, with the great toe extending and the toes fanning, in an adult","act":1,"why":"Infants show this response because their corticospinal tracts are not yet myelinated. Once descending upper motor neuron control matures, the reflex converts to toe flexion permanently, so its reappearance in an adult means that descending inhibitory control over the spinal reflex has been interrupted.","week":"6"},{"s":"A falling level of consciousness accompanied by a rising blood pressure, widening pulse pressure, and slowing heart rate","act":1,"why":"Brainstem centers raise systemic pressure to keep pushing blood into a skull whose pressure is climbing, and the baroreceptor reflex answers that surge by slowing the heart. The triad therefore reports that the medulla itself is being compressed, not that the cardiovascular system is behaving normally.","week":"6"},{"s":"Tingling around the mouth and involuntary muscle twitching when serum calcium falls","act":1,"why":"Extracellular calcium normally sits on voltage-gated Na+ channels and stabilizes them, keeping threshold comfortably above the resting potential. Remove calcium and threshold shifts closer to rest, so neurons and muscle fibers begin to fire spontaneously without any stimulus at all.","week":"6"},{"s":"Abrupt one-sided facial and arm weakness with slurred speech that appears over a few minutes","act":1,"why":"A deficit that is both sudden and focal maps onto the territory of a single cerebral vessel. Neurons store almost no glycogen and depend on continuous glucose and oxygen to run the Na+/K+ ATPase, so once perfusion stops the resting potential collapses within minutes.","week":"6"},{"s":"A brisk symmetric knee extension when the patellar tendon is tapped","act":0,"why":"The tap stretches muscle spindles, whose afferents synapse directly on alpha motor neurons in the ventral horn. A prompt, equal response on both sides simply proves the sensory limb, the cord segment, the motor limb and the muscle are all intact, and it is the expected result of testing.","week":"6"},{"s":"Both pupils constricting when light is shone into only one eye","act":0,"why":"Optic nerve fibers from each eye project to pretectal nuclei on both sides, which then drive parasympathetic output down both oculomotor nerves. The consensual response is therefore built into the normal wiring, and its presence is reassuring rather than abnormal.","week":"6"},{"s":"Sweaty palms, a pounding heart, and goosebumps just before speaking in front of the class","act":0,"why":"This is a textbook sympathetic mass discharge. The same thoracolumbar outflow that raises heart rate through beta-1 receptors also drives cholinergic sweat glands and the arrector pili muscles, so these findings appear together as a normal anticipatory response and settle on their own.","week":"6"},{"s":"Drowsiness, increased salivation, and audible bowel sounds after a large meal","act":0,"why":"Eating shifts autonomic balance toward parasympathetic dominance. Vagal acetylcholine at muscarinic receptors increases gastrointestinal motility and secretion and slows the heart slightly, while blood flow is diverted to the digestive tract, which is the expected rest-and-digest state.","week":"6"},{"s":"A brief dip of the membrane potential below -70 mV immediately after an action potential","act":0,"why":"Voltage-gated K+ channels are slow to close as well as slow to open, so K+ continues leaving past the point of full repolarization. The resulting undershoot is a normal part of every single action potential and is precisely what creates the relative refractory period that limits firing frequency.","week":"6"}],"chains":[{"title":"The action potential, phase by phase","start":"A summated graded depolarization reaches -55 mV at the axon hillock","steps":["Voltage-gated Na+ channels open and Na+ rushes inward down both its concentration and electrical gradients","The inflow of positive charge drives the membrane toward +30 mV, and that rising voltage opens still more Na+ channels in a self-reinforcing loop","Na+ inactivation gates swing shut while the slow voltage-gated K+ channels finally open, so K+ now flows outward","The loss of positive charge repolarizes the membrane, and the lagging K+ channels overshoot into a brief hyperpolarization below -70 mV","K+ channels close and the Na+/K+ pump quietly restores the original gradients while leak channels return the membrane to rest"],"why":"The positive-feedback step is what makes the response all-or-none: once threshold is crossed the Na+ influx reinforces itself and the sequence runs to completion identically every time, so a stronger stimulus produces more frequent spikes rather than bigger ones.","week":"6"},{"title":"Chemical transmission across a synapse","start":"An action potential arrives at the presynaptic axon terminal","steps":["Depolarization of the terminal membrane opens voltage-gated Ca2+ channels","Ca2+ enters from the extracellular fluid and triggers synaptic vesicles to dock and fuse with the presynaptic membrane","Neurotransmitter is expelled by exocytosis into the synaptic cleft and diffuses across the tiny gap","The transmitter binds chemically gated receptors on the postsynaptic membrane, opening ion channels that create an excitatory or inhibitory postsynaptic potential","Enzymatic breakdown, reuptake into the terminal, or diffusion away removes the transmitter and terminates the signal"],"why":"Calcium is the single step that converts membrane voltage into vesicle release, and it exists only on the presynaptic side. That is why a chemical synapse conducts in one direction only and why it costs a fraction of a millisecond of synaptic delay.","week":"6"},{"title":"Saltatory conduction along a myelinated axon","start":"An action potential fires at the initial segment of a myelinated axon","steps":["The lipid wrapping of myelin raises membrane resistance and prevents ions from crossing the membrane along the internode","Local current is therefore forced to spread passively through the axoplasm rather than leaking outward","That current arrives at the next node of Ranvier, where voltage-gated Na+ channels are densely clustered","The node is depolarized past threshold and regenerates a fresh, full-amplitude action potential","The process repeats node to node, so the impulse appears to jump and travels many times faster than continuous conduction"],"why":"Myelin does not make an individual action potential any faster. It removes the need to regenerate one at every patch of membrane, so the slow step of opening and closing channels happens only at the nodes.","week":"6"},{"title":"The monosynaptic stretch reflex","start":"The patellar tendon is tapped, suddenly stretching the quadriceps","steps":["Muscle spindles embedded in the quadriceps are stretched and their sensory endings depolarize","Afferent impulses travel through the femoral nerve into the dorsal root, whose cell bodies sit in the dorsal root ganglion","The afferent fiber synapses directly onto an alpha motor neuron in the ventral horn of the lumbar cord","That motor neuron fires out through the ventral root to the quadriceps, which contracts and extends the knee","A collateral branch of the same afferent excites an inhibitory interneuron that silences the hamstring motor neurons"],"why":"Speed comes from having exactly one synapse and from the spinal cord acting as the integrating center; the brain is informed afterward but is never in the loop, which is what makes the response involuntary and stereotyped.","week":"6"},{"title":"Establishing the resting membrane potential","start":"A neuron at rest with its Na+/K+ ATPase running","steps":["The pump ejects three Na+ for every two K+ it imports, building a steep Na+ gradient outward and a K+ gradient inward","The membrane carries far more K+ leak channels than Na+ leak channels, so K+ escapes much faster than Na+ enters","Every K+ that leaves carries a positive charge with it, stranding large impermeant proteins and phosphates inside the cell","The accumulating negative charge inside begins pulling K+ back in, opposing the concentration gradient that pushes it out","The membrane settles near -70 mV, close to but slightly less negative than the potassium equilibrium potential because of the small steady Na+ leak"],"why":"The potential is generated by selective permeability, not by the pump directly. The pump's job is to maintain the gradients that permeability then converts into voltage, with only a small extra negativity contributed by its unequal three-for-two exchange.","week":"6"},{"title":"Formation and circulation of cerebrospinal fluid","start":"Blood plasma is filtered at the choroid plexus of the lateral ventricles","steps":["Ependymal cells joined by tight junctions actively secrete a selectively modified filtrate into the ventricles as CSF","The fluid flows from the lateral ventricles through the interventricular foramina into the third ventricle, then down the cerebral aqueduct into the fourth","It escapes the fourth ventricle through the median and lateral apertures into the subarachnoid space surrounding the brain and spinal cord","Circulating there, the CSF buoys the brain so it effectively weighs a fraction of its true mass, cushions it from impact, and carries away metabolic waste","Arachnoid granulations projecting into the dural venous sinuses return the fluid to venous blood at the same rate it is produced"],"why":"The circuit is one-way and continuously balanced, so a blockage anywhere along it raises pressure in every compartment upstream while the choroid plexus keeps secreting regardless.","week":"6"},{"title":"The sympathetic fight-or-flight response","start":"The hypothalamus registers a threat and drives sympathetic outflow","steps":["Preganglionic neurons in the lateral horns of segments T1 through L2 fire and release acetylcholine onto nicotinic receptors in the sympathetic chain ganglia","Each preganglionic fiber synapses on many postganglionic neurons, whose long axons spread the signal across the body and release norepinephrine","Norepinephrine raises heart rate and force through beta-1 receptors, dilates bronchioles through beta-2 receptors, and constricts skin and gut vessels through alpha receptors","Some preganglionic fibers bypass the chain entirely and stimulate the adrenal medulla, which releases epinephrine directly into the bloodstream","Circulating epinephrine reaches every capillary bed, prolonging and amplifying the same effects and mobilizing glucose for skeletal muscle"],"why":"The anatomical divergence, one preganglionic neuron onto many postganglionic ones plus a hormonal arm with no synapse to limit it, is exactly why the sympathetic response is a body-wide mass discharge rather than an organ-by-organ adjustment.","week":"6"}]},"7":{"labs":[{"labs":[["Axial length of the eyeball","up"],["Distance visual acuity","down"],["Near visual acuity","n"],["Lens elasticity","n"]],"opts":["Hyperopia","Myopia","Presbyopia","Astigmatism"],"c":1,"why":"An eyeball that is too long for its refractive power brings parallel rays from a distant object to a point in front of the retina, so the image is already spreading again by the time it lands. Rays from a near object arrive diverging, so their focal point falls farther back and happens to land correctly, which is why near vision is untouched and why a concave (diverging) lens is the fix.","week":"7"},{"labs":[["Lens elasticity","down"],["Near point of accommodation (distance from the eye)","up"],["Distance visual acuity","n"],["Axial length of the eyeball","n"]],"opts":["Presbyopia","Myopia","Astigmatism","Cataract"],"c":0,"why":"Accommodation works only because the lens is elastic enough to recoil into a sphere the moment the zonular fibers slacken. Decades of added lens fibers stiffen the core, so even a maximally contracted ciliary muscle cannot round it. The eye's fixed geometry is normal, so distance vision, which requires no accommodation at all, stays sharp.","week":"7"},{"labs":[["Axial length of the eyeball","down"],["Near visual acuity","down"],["Distance visual acuity","n"],["Ciliary muscle effort during ordinary viewing","up"]],"opts":["Myopia","Astigmatism","Hyperopia","Retinal detachment"],"c":2,"why":"A short eyeball places the retina in front of the focal point, so the image would land behind the retina. A young ciliary muscle can accommodate to drag the focal point forward for distance, but that reserve is already partly spent, leaving nothing left for the extra power near work demands. A convex (converging) lens restores the balance.","week":"7"},{"labs":[["Bone conduction louder than air conduction on the affected side","abn"],["Weber tuning fork lateralizes to the affected ear","abn"],["Cochlear hair cell function","n"],["Tympanic membrane mobility","down"]],"opts":["Sensorineural loss at the hair cells","Conductive loss in the outer or middle ear","Damage to the vestibular branch of cranial nerve VIII","Normal hearing"],"c":1,"why":"Bone conduction delivers vibration through the skull straight into the cochlear fluids and skips the eardrum and ossicles entirely. If only the air route is blocked, the bypass route wins the comparison. The Weber tone seems louder in the bad ear because that ear is no longer hearing competing room noise, so the bone-conducted tone has the field to itself.","week":"7"},{"labs":[["Air conduction still louder than bone conduction","n"],["Weber tuning fork lateralizes to the better ear","abn"],["Threshold required to hear high-frequency tones","up"],["Hair cell population near the cochlear base","down"]],"opts":["Impacted cerumen in the canal","Fixation of the stapes at the oval window","Fluid filling the middle ear","Sensorineural loss at the cochlear hair cells"],"c":3,"why":"Every traveling wave that enters the cochlea passes the base first, and the base is exactly where the narrow stiff basilar membrane encodes high frequencies, so cumulative wear strips the top of the range first. Because the conducting apparatus is intact, air conduction still beats bone, and the tone shifts toward the ear whose hair cells still work.","week":"7"},{"labs":[["Rhodopsin content of the photoreceptor outer segments","up"],["Sensitivity to very dim light","up"],["Color discrimination","down"],["Visual acuity","down"]],"opts":["Photopic cone vision at the fovea","Fully dark-adapted rod vision","Optic nerve compression","Corneal edema"],"c":1,"why":"Many rods funnel onto a single bipolar and ganglion cell, so their weak individual signals add up and cross threshold together. That summation is what buys sensitivity, and it is also what destroys resolution, because the brain cannot tell which rod in the pool fired. A single pigment cannot encode wavelength, so the world comes in gray.","week":"7"},{"labs":[["Cone density","up"],["Rod density","down"],["Number of photoreceptors converging on each ganglion cell","down"],["Visual acuity","up"]],"opts":["Optic disc","Peripheral retina","Fovea centralis","Ora serrata"],"c":2,"why":"At this pit the overlying retinal layers are swept aside so light reaches the receptors unobstructed, and roughly one cone reports through its own bipolar cell to its own ganglion cell. That private line preserves the exact point in space each cone sampled, which is the anatomical basis of sharp vision and of why you must look directly at fine print.","week":"7"},{"labs":[["Rod and cone density","down"],["Ganglion cell axon density","up"],["Light detection at that point in the field","down"],["Entry of the central retinal artery","abn"]],"opts":["Macula lutea","Fovea centralis","Optic chiasm","Optic disc"],"c":3,"why":"This is a hole in the receptor sheet, the one place where ganglion cell axons turn and pierce the sclera and where the retinal vessels enter. No receptor can occupy that ground, so it produces a true physiological blind spot; the brain fills the gap from surrounding information, which is why nobody notices it.","week":"7"},{"labs":[["Ciliary muscle contraction","up"],["Tension on the zonular (suspensory) fibers","down"],["Lens convexity","up"],["Pupil diameter","down"]],"opts":["The near response (accommodation)","Viewing an object at a distance","A sympathetic fight-or-flight response","Presbyopia"],"c":0,"why":"The ciliary muscle behaves like a sphincter around the lens, so when it contracts the ring it forms gets smaller and the fibers slung from it go slack. Relieved of that outward pull, the elastic lens recoils into a rounder, more powerful shape. The pupil constricts at the same moment to block the peripheral rays that would blur the near image.","week":"7"},{"labs":[["Deflection of the cupula by moving endolymph","up"],["Displacement of otoliths on a gel membrane","n"],["Sensation of spinning or angular acceleration","up"],["Sensation of a sustained head tilt","n"]],"opts":["Maculae of the utricle and saccule","Crista ampullaris of a semicircular duct","Spiral organ of the cochlea","Olfactory epithelium"],"c":1,"why":"The membranous ducts turn with the skull but the endolymph inside lags because of inertia, and that relative flow pushes the gelatinous cupula and bends the hair cells embedded in it. The signal therefore reports change in rotation rate, not rotation itself, which is why a constant spin stops feeling like spinning once the fluid catches up.","week":"7"},{"labs":[["Receptor firing at the instant the stimulus is applied","up"],["Receptor firing after sixty seconds of unchanging stimulus","down"],["Conscious awareness of the stimulus over time","down"],["Receptor firing at the moment the stimulus is removed","up"]],"opts":["A tonic receptor such as a nociceptor","A phasic (rapidly adapting) receptor such as a lamellar corpuscle","A proprioceptive muscle spindle","A thermoreceptor tracking a fever"],"c":1,"why":"The onion-like lamellae of the capsule slide and redistribute a steady load away from the nerve ending, so only a change in pressure ever reaches the membrane. That is why the receptor fires twice, once when pressure arrives and once when it leaves, and why you stop feeling your waistband.","week":"7"},{"labs":[["Firing of visceral nociceptors in an internal organ","up"],["Tissue damage in the skin region that hurts","n"],["Pain reported over a specific dermatome","abn"],["Spinal segment shared by the visceral and somatic inputs","abn"]],"opts":["Referred pain from converging visceral and somatic afferents","Phantom pain from a missing body part","A local injury to the painful skin","Compression of a peripheral nerve"],"c":0,"why":"Visceral afferents enter the cord through the same dorsal roots as the somatic afferents of a particular dermatome and converge on the same second-order neurons. The cortex has spent a lifetime receiving that line from skin, so it assigns the pain to skin, even though the skin is entirely healthy.","week":"7"}],"pairs":[{"clue":"Supplies roughly two-thirds of the eye's refracting power, and that power cannot be changed.","a":"Cornea","b":"Lens","why":"Light bends at boundaries between media of different optical density, and the air-to-cornea boundary is by far the biggest jump light meets. The lens sits between two watery fluids, so it bends light only slightly, but it is the only refractive element that can change its own shape.","week":"7","c":0},{"clue":"The vascular pigmented tunic that feeds the outer retina and absorbs stray light.","a":"Choroid","b":"Retina","why":"The retina is the neural tunic that holds the photoreceptors; the choroid lies just outside it and supplies those receptors by diffusion, because photoreceptors are too metabolically demanding to survive on retinal vessels alone. Its melanin also stops light from scattering back through the receptors and smearing the image.","week":"7","c":0},{"clue":"Watery fluid produced continuously by the ciliary processes and drained at the scleral venous sinus.","a":"Aqueous humor","b":"Vitreous humor","why":"Because this fluid turns over constantly, production and drainage must stay balanced, and intraocular pressure is the direct result of that balance. Vitreous humor is a gel laid down before birth that is never replaced, so it cannot generate a pressure problem the same way.","week":"7","c":0},{"clue":"Contract this muscle and the pupil becomes smaller.","a":"Sphincter (circular) pupillae, parasympathetic","b":"Dilator (radial) pupillae, sympathetic","why":"Circular fibers form a ring, so shortening them narrows the aperture, exactly like closing a drawstring. Radial fibers run outward like spokes, so shortening them pulls the pupillary margin toward the periphery and widens the opening.","week":"7","c":0},{"clue":"Rounding the lens so that a close object comes into focus.","a":"Accommodation","b":"Convergence","why":"Accommodation is an intraocular event involving the ciliary muscle, zonules, and lens. Convergence is an extraocular event in which both medial recti aim the eyes at the same near point. They occur together in the near response, but they use different muscles and solve different problems.","week":"7","c":0},{"clue":"Focal point falls in front of the retina and is corrected with a concave lens.","a":"Myopia","b":"Hyperopia","why":"Too much refractive power for the length of the eye brings rays to a point early, so the image is spreading again when it strikes the retina. A diverging lens pre-spreads the incoming light so the focal point moves backward onto the receptor layer.","week":"7","c":0},{"clue":"Unequal curvature of the cornea or lens, so light in one meridian focuses at a different distance than light in another.","a":"Astigmatism","b":"Presbyopia","why":"This is a shape problem that blurs the image at every viewing distance, because no single focal point exists at all. Presbyopia is a loss of lens flexibility that leaves distance vision perfect and only shows itself when the eye is asked to add power for near work.","week":"7","c":0},{"clue":"The pigment that is almost fully bleached in daylight and takes several minutes to rebuild.","a":"Rhodopsin in rods","b":"Photopsin in cones","why":"Rod pigment is so sensitive that bright light bleaches essentially all of it, and the retinal must recombine with opsin before the rods work again, which is the whole reason dark adaptation is slow. Cone pigments are less sensitive and regenerate far faster, with cone dark adaptation essentially complete in about five minutes, while full rod dark adaptation takes twenty to thirty minutes or more.","week":"7","c":0},{"clue":"The site where ganglion cell axons exit the eye and the central retinal vessels enter.","a":"Optic disc","b":"Fovea centralis","why":"No photoreceptors can occupy the ground where axons turn and pierce the sclera, which creates the physiological blind spot. The fovea is the opposite arrangement, a pit cleared of overlying layers and packed with nothing but cones.","week":"7","c":0},{"clue":"The ossicle whose footplate rocks in the oval window.","a":"Stapes","b":"Malleus","why":"The handle of the malleus is fused to the tympanic membrane, so it receives vibration first and starts the chain. The chain ends at the stapes, which is the only ossicle in contact with the inner ear and therefore the one that converts air-borne vibration into fluid waves.","week":"7","c":0},{"clue":"Frequency is mapped along this structure: stiff and narrow at the base for high pitch, wide and floppy at the apex for low pitch.","a":"Basilar membrane","b":"Tectorial membrane","why":"The mechanical gradient of width and stiffness makes each region peak in response to a different frequency, which is the physical basis of pitch discrimination. The tectorial membrane is a fixed gel shelf overhead; it does not do frequency analysis, it simply gives the stereocilia something to shear against.","week":"7","c":0},{"clue":"Membrane-covered opening that bulges outward to relieve each pressure wave leaving the cochlea.","a":"Round window","b":"Oval window","why":"Perilymph is essentially incompressible, so if the cochlea were a closed rigid box the stapes could not move at all. This compliant escape hatch is what allows the basilar membrane to be displaced. The oval window is the entrance, not the exit.","week":"7","c":0},{"clue":"Receptor organ that reports head tilt and straight-line acceleration.","a":"Macula of the utricle and saccule","b":"Crista ampullaris","why":"The macula carries dense calcium carbonate crystals in a gel, making it heavier than the surrounding endolymph so gravity or linear acceleration drags it and shears the hair cells. The crista sits inside the ampulla of a duct and is moved only by endolymph flowing during rotation.","week":"7","c":0},{"clue":"Chemical sense whose receptor cells are replaceable bipolar neurons that reach the cortex without a thalamic relay.","a":"Olfaction","b":"Gustation","why":"An olfactory sensory neuron is both the receptor and the first-order neuron in one cell; its axon crosses the cribriform plate to the olfactory bulb and then goes straight to the temporal lobe and limbic structures, which is why odors trigger memory and emotion so directly. Taste receptor cells are modified epithelial cells that must synapse onto cranial nerves VII, IX, and X and relay in the thalamus.","week":"7","c":0},{"clue":"The visible bump on the surface of the tongue.","a":"Papilla","b":"Taste bud","why":"Taste buds are microscopic barrel-shaped clusters of gustatory epithelial cells buried in the walls and clefts of papillae, so an individual bud can never be seen with the naked eye. Naming the bump a taste bud confuses the container with its contents.","week":"7","c":0},{"clue":"Deep pressure and high-frequency vibration, onion-layered capsule, adapts within a second or two.","a":"Lamellar (Pacinian) corpuscle","b":"Tactile (Meissner) corpuscle","why":"Lamellar corpuscles lie deep in the dermis and hypodermis, and their concentric layers slide to dissipate any steady load, so only rapid changes reach the ending. Tactile corpuscles sit just under the epidermis in dermal papillae of hairless skin and report light touch and low-frequency flutter.","week":"7","c":0},{"clue":"Receptors that barely adapt at all, so the warning signal keeps arriving as long as the stimulus lasts.","a":"Nociceptors, which are free nerve endings","b":"Lamellar corpuscles","why":"A bare ending has no capsule to filter the stimulus, and adaptation would be dangerous for a signal whose entire purpose is to force protective behavior. Encapsulated receptors are built to filter, which makes them useless for sustained warnings.","week":"7","c":0},{"clue":"Ascending tract for pain and temperature that crosses within a segment or two of where the fibers entered the cord.","a":"Spinothalamic (anterolateral) tract","b":"Dorsal column-medial lemniscal pathway","why":"Pain and temperature second-order neurons decussate almost immediately in the spinal cord, so a cord lesion produces loss on the opposite side below it. Touch and proprioception fibers ascend on the same side and do not cross until the medulla, so the same lesion produces loss on the same side.","week":"7","c":0}],"redflags":[{"s":"A patient describes a sudden shower of new floaters and flashes of light, followed by a dark curtain sweeping across the field of one eye.","act":1,"why":"The neural retina is being separated from the pigment epithelium and choroid that nourish it by diffusion. Photoreceptors have an enormous metabolic demand and cannot survive long off that supply, so the delay before reattachment determines how much vision is permanently lost.","week":"7"},{"s":"Severe pain in one eye with colored halos around lights, a rock-hard globe, and a fixed mid-dilated pupil.","act":1,"why":"Aqueous humor is still being secreted by the ciliary processes while its drainage at the scleral venous sinus is obstructed, so intraocular pressure climbs quickly. The rising pressure compresses ganglion cell axons and the vessels feeding them, and the corneal edema it causes is what produces the halos.","week":"7"},{"s":"Clear watery fluid dripping from the ear canal after a blow to the side of the head.","act":1,"why":"A temporal bone fracture has opened the subarachnoid space into the middle ear, so what is draining is cerebrospinal fluid. The breach is a direct route for organisms to reach the meninges.","week":"7"},{"s":"A previously healthy adult wakes with hearing gone in one ear over a few hours, with no pain and no wax visible in the canal.","act":1,"why":"With the conducting apparatus visibly clear, the failure lies at the cochlear hair cells or the cochlear nerve, and human hair cells do not regenerate. The window in which intervention can preserve them is short, so this cannot be watched.","week":"7"},{"s":"New vertigo accompanied by double vision, slurred speech, and nystagmus that does not fatigue with repeated testing.","act":1,"why":"Central vestibular pathways travel through the brainstem alongside the nuclei and tracts for eye movement and speech. Deficits that cannot be explained by the labyrinth alone place the lesion above the inner ear.","week":"7"},{"s":"One-sided ringing with slowly progressive hearing loss and worsening balance on the same side.","act":1,"why":"The cochlear and vestibular fibers travel together as cranial nerve VIII through the narrow internal acoustic meatus, so a single lesion in that space picks off hearing and equilibrium on one side only. Genuinely one-sided nerve findings are the pattern that matters.","week":"7"},{"s":"One pupil stays dilated and fails to constrict whether light is shone into it or into the other eye, while the opposite pupil constricts to both.","act":1,"why":"Light striking either retina drives both Edinger-Westphal nuclei, so the reflex is normally consensual. A pupil that fails to both the direct and the consensual stimulus cannot have a sensory problem; the parasympathetic efferent in cranial nerve III is the only remaining link, and those fibers ride on the outside of the nerve where compression reaches them first.","week":"7"},{"s":"Complete and permanent loss of smell after a fracture across the bridge of the nose and forehead.","act":1,"why":"Olfactory sensory neuron axons cross the cribriform plate of the ethmoid in delicate bundles, and shearing at that plate severs them. The same breach also opens the nasal cavity to the meninges.","week":"7"},{"s":"A person stops noticing their own cologne within fifteen minutes even though visitors still comment on it.","act":0,"why":"Olfactory receptors adapt rapidly and central pathways add further habituation, so an unchanging odorant stops generating a reportable signal. A new odorant still comes through clearly, which is exactly the behavior that makes the sense useful as a change detector.","week":"7"},{"s":"Shining a penlight into the right eye makes the left pupil constrict as well.","act":0,"why":"Fibers from each retina project to pretectal nuclei on both sides, so the parasympathetic output goes to both eyes no matter which retina is stimulated. The consensual response is the expected finding, and its absence would be the abnormality.","week":"7"},{"s":"On walking into a dark theater a person sees almost nothing for several minutes, and when vision returns everything looks gray.","act":0,"why":"Daylight had bleached nearly all rhodopsin, and retinal must recombine with opsin before rods function again, which takes minutes. Rods carry a single pigment and cannot encode wavelength, so the recovered image is necessarily colorless.","week":"7"},{"s":"A forty-seven-year-old holds a menu at arm's length to read it but has no trouble seeing road signs.","act":0,"why":"The lens stiffens progressively with age, so the maximum power that accommodation can add falls and the near point recedes. Distance vision requires no accommodation at all, so it is untouched, and the pattern is universal rather than pathological.","week":"7"},{"s":"Ears feel blocked and muffled during airplane descent, then pop and clear when the person swallows.","act":0,"why":"Rising cabin pressure pushes the tympanic membrane inward and damps its vibration. Swallowing opens the pharyngotympanic tube, letting middle ear pressure equalize with ambient air so the membrane can move freely again.","week":"7"}],"chains":[{"title":"The pathway of light from object to occipital cortex","start":"Light reflected from an object strikes the anterior surface of the eye.","steps":["The cornea performs most of the refraction, and the light then passes through aqueous humor and the pupil, whose diameter the iris has already set for the ambient brightness.","The lens adds the adjustable remainder of the refraction and the vitreous humor transmits the light to the retina, where the image lands inverted and reversed.","Photons isomerize retinal within rhodopsin or a cone photopsin, the photoreceptor hyperpolarizes, and it reduces its release of glutamate onto bipolar cells.","Bipolar cells drive ganglion cells, whose axons converge at the optic disc, leave as the optic nerve, and partially decussate at the optic chiasm so that each optic tract carries the opposite half of the visual field.","Fibers relay in the lateral geniculate nucleus of the thalamus and travel through the optic radiation to the primary visual cortex of the occipital lobe, where the inverted retinal image is interpreted right side up."],"why":"This is the one chain that ties refraction, transduction, and central processing together, and it explains why the location of a lesion predicts the shape of the visual field deficit: damage before the chiasm affects one eye, damage at or after it affects the same half-field of both eyes.","week":"7"},{"title":"Accommodation and the near response","start":"A reader shifts gaze from a distant sign to a page held twenty-five centimeters away.","steps":["Rays from the near page arrive diverging, so with the eye's resting refractive power they would come to a focus behind the retina and the image blurs.","Parasympathetic fibers traveling in cranial nerve III fire, and the ciliary muscle contracts.","Because the ciliary muscle is a ring, contracting it reduces the diameter of that ring and slackens the zonular fibers slung between it and the lens capsule.","Released from outward tension, the elastic lens recoils into a rounder, more convex shape, its refractive power rises, and the focal point moves forward onto the retina.","At the same time the sphincter pupillae constricts the pupil to exclude blurring peripheral rays, and both medial recti converge the eyes so the sharp image falls on both foveae."],"why":"Students almost always reverse this chain because it feels backward that contracting a muscle relieves tension on the lens. Getting the ring geometry right is what makes presbyopia and the design of reading glasses make sense.","week":"7"},{"title":"The pathway of sound to the spiral organ","start":"A pressure wave in air is funneled by the auricle into the external acoustic meatus.","steps":["The wave sets the tympanic membrane vibrating at the frequency of the sound, and the handle of the malleus moves with it.","Malleus, incus, and stapes transmit and amplify the vibration, chiefly by concentrating the force collected over the large eardrum onto the far smaller footplate of the stapes at the oval window.","The rocking stapes generates pressure waves in the perilymph of the scala vestibuli, which pass to the scala tympani and are released by outward bulging of the round window.","The wave displaces the basilar membrane maximally at the position matched to its frequency, near the stiff narrow base for high pitch and near the wide floppy apex for low pitch.","Hair cells of the spiral organ, riding on the moving basilar membrane, shear against the fixed tectorial membrane, their stereocilia bend, mechanically gated channels open, the cells depolarize and release transmitter onto cochlear nerve fibers bound for the brainstem, thalamus, and temporal lobe."],"why":"The chain shows why hearing needs an impedance-matching middle ear at all: sound must cross from thin air into dense fluid, and without the eardrum-to-footplate force concentration nearly all of the energy would simply reflect away.","week":"7"},{"title":"Detecting head rotation in a semicircular duct","start":"The head begins to turn to the left.","steps":["The bony labyrinth and the membranous duct within it move immediately with the skull, but the endolymph inside lags behind because of its inertia.","The relative backward flow of endolymph presses on the gelatinous cupula sitting in the ampulla.","The cupula tips, bending the stereocilia of the crista ampullaris hair cells; bending toward the kinocilium depolarizes the cell and increases transmitter release, bending away hyperpolarizes it and decreases release.","The altered firing travels in the vestibular division of cranial nerve VIII to the vestibular nuclei and the cerebellum.","Output drives the vestibulo-ocular reflex, moving the eyes opposite to the head so gaze stays fixed, and adjusts postural muscle tone to keep balance."],"why":"Because the signal depends on fluid lagging behind bone, these receptors report only change in rotation. At a constant spin rate the endolymph catches up and the cupula returns to neutral, which is why a steadily rotating person stops feeling motion and why stopping produces a false sensation of spinning the other way.","week":"7"},{"title":"Olfactory transduction and its unusual central route","start":"An inhaled odorant molecule dissolves in the mucus covering the olfactory epithelium in the roof of the nasal cavity.","steps":["The dissolved molecule binds a G protein-coupled receptor on the olfactory cilia of a bipolar olfactory sensory neuron.","The G protein activates adenylyl cyclase, cyclic AMP rises, cation channels open, and the graded depolarization reaches threshold at the axon hillock.","The axon passes upward through a foramen of the cribriform plate of the ethmoid bone and synapses in a glomerulus of the olfactory bulb.","Mitral cell axons travel in the olfactory tract to the primary olfactory cortex of the temporal lobe and to limbic structures, without the thalamic relay every other sensory pathway uses."],"why":"The receptor cell is also the first-order neuron here, which is why smell is the only special sense whose receptors are replaced throughout life and why a fracture at the cribriform plate abolishes it. Skipping the thalamus is the anatomical reason odors evoke emotion and memory so much faster than they evoke a name.","week":"7"},{"title":"Why cardiac pain is felt in the arm and jaw","start":"Ischemic myocardium releases chemicals that activate visceral nociceptors in the heart wall.","steps":["Those visceral afferent fibers enter the spinal cord through the dorsal roots of segments T1 to T5, the same roots that carry somatic afferents from the chest wall, medial arm, and neck.","Visceral and somatic fibers converge onto the same second-order neurons in the dorsal horn, and the visceral input is far sparser and far less often used.","The second-order axons decussate within a segment or two and ascend in the spinothalamic tract to the thalamus.","The primary somatosensory cortex receives the signal along a line that has, throughout the person's life, carried information from skin, and it has no separate cortical map for the heart.","The cortex therefore localizes the pain to the corresponding dermatomes, and the person feels chest, left arm, and jaw pain even though those tissues are undamaged."],"why":"Referred pain is not mysterious once convergence is understood: perception is built from which pathway is active, not from where the signal truly began, and the brain defaults to the interpretation that has been correct thousands of times before.","week":"7"},{"title":"Dark adaptation on entering a dim room","start":"A person walks out of bright sunlight into a darkened theater.","steps":["In the sunlight almost all rhodopsin had been bleached, so the rods were effectively out of service and vision was carried entirely by cones.","In the dark the cones no longer receive enough photons to respond, and the rods are not yet functional, so for the first moments almost nothing is visible.","Retinal recombines with opsin inside the rod outer segments, a process requiring vitamin A, and rhodopsin is regenerated over several minutes.","As rhodopsin accumulates, rod sensitivity rises, and the convergence of many rods onto a single ganglion cell lets scattered weak signals summate above threshold.","Vision returns as a colorless, low-detail image that is sharpest slightly off center, because the fovea contains only cones and the rod population lies in the surrounding retina."],"why":"The chain explains three everyday observations from one mechanism: why adaptation is slow rather than instant, why dim scenes have no color, and why a faint star disappears when you look straight at it.","week":"7"}]},"8":{"labs":[{"labs":[["Blood in this chamber, oxygen content","down"],["Wall thickness compared with the left ventricle","down"],["Pressure generated during systole","down"],["Valve at its outflow, structure","n"]],"opts":["Right ventricle","Left ventricle","Left atrium","Right atrium"],"c":0,"why":"The chamber generating low pressure with a thin wall while handling deoxygenated blood must be pumping into the short, low-resistance pulmonary circuit. The right atrium also holds deoxygenated blood but does not generate ejection pressure at all, and its outflow valve is the tricuspid AV valve rather than a semilunar valve.","week":"8"},{"labs":[["Oxygen content of blood carried","up"],["Vessel wall thickness","down"],["Direction of flow relative to the heart","abn"],["Valves in the vessel wall","n"]],"opts":["Pulmonary vein","Pulmonary artery","Aorta","Superior vena cava"],"c":0,"why":"Vessels are named by the direction they travel, not by what they carry. A thin-walled vessel carrying oxygenated blood toward the heart is the pulmonary vein, the one place in the body where a vein carries oxygen-rich blood. The direction of flow is flagged as unusual precisely because it is the exception students are being asked to catch.","week":"8"},{"labs":[["P wave present and upright","n"],["PR interval duration","n"],["QRS complex following every P wave","n"],["Rate at 52 beats per minute in a trained endurance athlete","down"]],"opts":["Normal conduction with athletic bradycardia","Complete heart block","Atrial fibrillation","Sinus tachycardia"],"c":0,"why":"Every P wave is followed by a QRS at a normal interval, so the sinoatrial node is pacing and the atrioventricular node is conducting normally. In heart block the P waves would march independently of the QRS. The slow rate here reflects a large trained stroke volume, which lets the heart meet resting cardiac output at a lower rate.","week":"8"},{"labs":[["End-diastolic volume","up"],["Sarcomere stretch in ventricular wall","up"],["Stroke volume on the next beat","up"],["Sympathetic stimulation to the heart","n"]],"opts":["Frank-Starling mechanism from increased venous return","Sympathetic increase in contractility","Epinephrine release from the adrenal medulla","Increased afterload from vasoconstriction"],"c":0,"why":"Sympathetic input is flagged as normal, which rules out any neural or hormonal explanation. Stroke volume rose purely because the ventricle was stretched further before contracting, an intrinsic length-tension property of the cardiac muscle itself that requires no outside signal.","week":"8"},{"labs":[["Hematocrit","up"],["Red blood cell count","up"],["Erythropoietin secretion by the kidney","up"],["Arterial oxygen saturation at high altitude","down"]],"opts":["Normal acclimatization to high altitude","Dehydration alone","Iron deficiency","Bone marrow failure"],"c":0,"why":"The kidney senses low oxygen delivery and releases erythropoietin, which drives the red marrow to raise red cell production. Dehydration would raise hematocrit by shrinking plasma volume but would not raise erythropoietin or the absolute red cell count. This is a normal adaptive response, not a disease.","week":"8"},{"labs":[["Bleeding time","up"],["Platelet count","n"],["Prothrombin time","n"],["Fibrinogen level","n"]],"opts":["Defective platelet function with adequate platelet numbers","Thrombocytopenia","Vitamin K deficiency","Normal hemostasis"],"c":0,"why":"Platelet number and the clotting factor tests are all normal, so the problem is not how many platelets there are or whether fibrin can be made. Prolonged bleeding time isolates the platelet plug step, meaning platelets are present but cannot adhere or aggregate properly.","week":"8"},{"labs":[["Agglutination with anti-A serum","n"],["Agglutination with anti-B serum","n"],["Agglutination with anti-D (Rh) serum","abn"],["Anti-A and anti-B antibodies in the plasma","up"]],"opts":["Type O positive","Type AB negative","Type A positive","Type O negative"],"c":0,"why":"No clumping with anti-A or anti-B means neither A nor B antigen is on the cells, which defines type O, and type O plasma therefore carries both antibodies. Clumping with anti-D adds the Rh antigen, making it O positive. Students often reverse this and read no reaction as type AB.","week":"8"},{"labs":[["Systolic blood pressure","up"],["Diastolic blood pressure","n"],["Heart rate","up"],["Total peripheral resistance","down"]],"opts":["Normal cardiovascular response to moderate exercise","Hypertensive crisis","Hemorrhagic shock","Resting baseline in a sedentary adult"],"c":0,"why":"During exercise the rise in cardiac output pushes systolic pressure up, while vasodilation in the working skeletal muscle beds drops resistance enough to hold diastolic pressure steady. A pathological pressure elevation would raise diastolic pressure and resistance together rather than moving them in opposite directions.","week":"8"},{"labs":[["Vessel wall smooth muscle layer, tunica media","down"],["Lumen diameter for a given wall thickness","up"],["Internal one-way valves present","abn"],["Pressure of blood inside","down"]],"opts":["Vein","Muscular artery","Capillary","Arteriole"],"c":0,"why":"A thin muscular layer with a wide lumen and one-way valves describes a vessel built as a low-pressure reservoir, not a pressure conduit. Capillaries have no tunica media at all and no valves, and arterioles have a relatively thick media for their size because they are the main resistance vessels.","week":"8"},{"labs":[["Wall composed of a single layer of endothelium on a basement membrane","abn"],["Blood flow velocity","down"],["Total cross-sectional area of this vessel class","up"],["Smooth muscle in the wall","abn"]],"opts":["Capillary","Venule","Arteriole","Elastic artery"],"c":0,"why":"A single endothelial layer with no smooth muscle is the structural signature of the capillary, and that thinness is exactly what permits exchange. Flow is slowest here because the enormous combined cross-sectional area of the capillary beds spreads the same cardiac output across a vastly wider channel, maximizing exchange time.","week":"8"},{"labs":[["Blood flow through the coronary arteries","up"],["Ventricular myocardial tension","down"],["Aortic valve position","abn"],["Phase of the cardiac cycle","abn"]],"opts":["Ventricular diastole, when coronary perfusion peaks","Ventricular systole, at peak ejection","Isovolumetric contraction","Atrial systole"],"c":0,"why":"The coronary arteries branch from the aorta just above the aortic valve cusps, and during systole the contracting myocardium squeezes them shut. Only when the ventricle relaxes and the aortic valve closes does the elastic recoil of the aorta drive blood into the coronary ostia, so the heart uniquely feeds itself while resting.","week":"8"},{"labs":[["Heart rate","up"],["Stroke volume","down"],["Cardiac output","n"],["Blood pressure","n"]],"opts":["Compensated state maintaining output by raising rate","Increased cardiac output from exercise","Complete failure of cardiac output","Vagal slowing of the heart"],"c":0,"why":"Cardiac output is heart rate multiplied by stroke volume, so the two variables can trade off against each other. Here a faster rate exactly offsets a smaller ejection per beat, holding output and therefore pressure constant. Reading either the rate or the stroke volume alone would give the wrong answer.","week":"8"}],"pairs":[{"clue":"The valve between the left atrium and left ventricle","a":"Bicuspid (mitral) valve","b":"Tricuspid valve","why":"Both are atrioventricular valves anchored by chordae tendineae to papillary muscles, but the left side valve has two cusps and the right side has three. Remembering that the left is the bicuspid keeps the whole left-side pathway straight.","week":"8","c":0},{"clue":"The valve that closes to produce the second heart sound, S2","a":"Semilunar valves closing at the end of ventricular systole","b":"Atrioventricular valves closing at the start of ventricular systole","why":"Heart sounds are produced by valves snapping shut as blood pushes back against them. AV valve closure begins systole and makes S1; semilunar closure ends systole and makes S2, so the interval between S1 and S2 is the ejection period.","week":"8","c":0},{"clue":"The ECG wave produced by depolarization of the ventricles","a":"QRS complex","b":"T wave","why":"The QRS is ventricular depolarization and immediately precedes contraction; the T wave is ventricular repolarization and precedes relaxation. Atrial repolarization exists but is buried inside the QRS because the much larger ventricular signal masks it.","week":"8","c":0},{"clue":"The structure that normally sets the resting heart rate","a":"Sinoatrial node","b":"Atrioventricular node","why":"Both are autorhythmic, but the SA node reaches threshold fastest at roughly 60 to 100 times a minute and therefore captures the heart. The AV node is a slower backup at about 40 to 60, and it also supplies the deliberate delay that lets the atria empty before the ventricles fire.","week":"8","c":0},{"clue":"The vessel that carries deoxygenated blood away from the heart","a":"Pulmonary artery","b":"Pulmonary vein","why":"Arteries and veins are defined by direction of travel, not oxygen content. The pulmonary artery is the one artery carrying deoxygenated blood, and the pulmonary vein is the one vein carrying oxygenated blood.","week":"8","c":0},{"clue":"The vessel layer that determines resistance and directs blood flow","a":"Tunica media of the arterioles","b":"Tunica intima of the arterioles","why":"The tunica media is smooth muscle under sympathetic control, so its contraction narrows the lumen and raises resistance. The tunica intima is the smooth endothelial lining that reduces friction and prevents clotting but does not change vessel diameter.","week":"8","c":0},{"clue":"The chamber with the thickest myocardial wall","a":"Left ventricle","b":"Right ventricle","why":"Wall thickness tracks the pressure a chamber must generate. The left ventricle drives blood against the high resistance of the entire systemic circuit, while the right ventricle only pushes into the low-resistance pulmonary circuit and needs perhaps a third of the muscle.","week":"8","c":0},{"clue":"The formula for cardiac output","a":"Heart rate multiplied by stroke volume","b":"End-diastolic volume minus end-systolic volume","why":"The second expression is the definition of stroke volume itself, the amount ejected per beat. Cardiac output adds the time dimension by multiplying that per-beat quantity by the number of beats per minute, giving volume per minute.","week":"8","c":0},{"clue":"The factor that increases stroke volume through greater ventricular stretch before contraction","a":"Preload","b":"Afterload","why":"Preload is the degree of stretch at the end of diastole and raises stroke volume through the Frank-Starling mechanism. Afterload is the arterial pressure the ventricle must overcome to open the semilunar valve, and raising it reduces stroke volume.","week":"8","c":0},{"clue":"The plasma protein that is converted into the threads of a clot","a":"Fibrinogen converted to fibrin","b":"Prothrombin converted to thrombin","why":"Both are plasma proteins in the same cascade, but thrombin is the enzyme and fibrin is the structural product. Thrombin is what performs the conversion of fibrinogen into the insoluble fibrin mesh, so it acts on fibrinogen rather than becoming the mesh.","week":"8","c":0},{"clue":"The formed element that transports oxygen and lacks a nucleus at maturity","a":"Erythrocyte","b":"Leukocyte","why":"The mature red cell ejects its nucleus and organelles, which frees interior space for hemoglobin and lets the biconcave disc bend through capillaries. White cells retain nuclei because they must synthesize proteins to carry out immune functions.","week":"8","c":0},{"clue":"The universal donor blood type for red cells","a":"Type O negative","b":"Type AB positive","why":"O negative red cells display neither A, B, nor Rh antigens, so no recipient antibody can bind them. AB positive is the reverse case, the universal recipient, because that plasma contains no anti-A or anti-B antibodies to attack incoming cells.","week":"8","c":0},{"clue":"The straw-colored fluid portion of blood that still contains clotting proteins","a":"Plasma","b":"Serum","why":"Plasma is the liquid matrix of whole blood, roughly 55 percent of blood volume, and includes fibrinogen and the other clotting factors. Serum is what remains after blood has clotted, so by definition the clotting proteins have been consumed and removed.","week":"8","c":0},{"clue":"The receptors that detect a change in blood pressure and trigger a rapid reflex","a":"Baroreceptors in the carotid sinus and aortic arch","b":"Chemoreceptors in the carotid and aortic bodies","why":"Baroreceptors are stretch sensors in the vessel wall that report mechanical distension, which stands in for pressure. Chemoreceptors sit alongside them but respond to blood oxygen, carbon dioxide, and pH rather than to pressure.","week":"8","c":0},{"clue":"The artery that supplies most of the left ventricle and interventricular septum","a":"Left anterior descending branch of the left coronary artery","b":"Right coronary artery","why":"The left coronary artery divides into the anterior interventricular (left anterior descending) and circumflex branches serving the large-muscled left side. The right coronary artery mainly supplies the right atrium, right ventricle, and in most people the SA and AV nodes.","week":"8","c":0},{"clue":"The pressure that best represents average perfusion pressure driving blood into tissues","a":"Mean arterial pressure","b":"Pulse pressure","why":"Mean arterial pressure weights diastole more heavily because the heart spends about two thirds of the cycle in diastole, so it reflects the average driving force. Pulse pressure is the difference between systolic and diastolic and reflects the stiffness of the arteries and the size of the stroke volume.","week":"8","c":0},{"clue":"The cells that prevent blood loss by adhering to exposed collagen and forming a plug","a":"Platelets, which are cell fragments from megakaryocytes","b":"Neutrophils, the most numerous white blood cells","why":"Platelets are anucleate fragments shed from megakaryocytes in the marrow and function purely in hemostasis. Neutrophils are complete cells that phagocytize bacteria; both are abundant in blood but their roles do not overlap.","week":"8","c":0},{"clue":"The event that occurs during isovolumetric contraction","a":"All four valves are closed and pressure rises without any change in ventricular volume","b":"The semilunar valves open and blood is ejected into the great arteries","why":"Isovolumetric means the volume does not change, which is only possible when both the AV and semilunar valves are shut. Ejection cannot start until ventricular pressure climbs past arterial pressure and forces the semilunar valves open.","week":"8","c":0}],"redflags":[{"s":"A resting heart rate of 48 beats per minute in a well-trained marathon runner with normal blood pressure and no symptoms","act":0,"why":"Endurance training enlarges the ventricle and raises stroke volume, so the same cardiac output is met with fewer beats. Athletic bradycardia is an expected adaptation, not a conduction defect.","week":"8"},{"s":"Crushing substernal chest pressure with radiation to the left arm and jaw, lasting twenty minutes at rest","act":1,"why":"Coronary arteries perfuse the myocardium during diastole and have limited collateral supply, so an obstruction starves muscle that cannot be resupplied from a neighboring branch. Pain persisting at rest indicates the demand-supply gap is not being closed.","week":"8"},{"s":"Blood pressure falling by about 8 mmHg systolic on standing, with a brief lightheaded sensation that resolves in a few seconds","act":0,"why":"Gravity pools blood in the leg veins and momentarily reduces venous return. The baroreceptor reflex corrects it within seconds, which is exactly what the transient nature of the symptom demonstrates.","week":"8"},{"s":"On the ECG, P waves marching at a regular rate completely independent of the QRS complexes","act":1,"why":"This means the atrial signal is not reaching the ventricles at all, so the atrioventricular node or bundle is blocked. The ventricles are being driven by a slow escape pacemaker, which cannot reliably sustain cardiac output.","week":"8"},{"s":"Heart rate rising from 70 to 150 beats per minute during vigorous exercise, returning to baseline within several minutes of stopping","act":0,"why":"Sympathetic stimulation and withdrawal of vagal tone raise rate and contractility to meet increased tissue oxygen demand. Prompt recovery confirms the autonomic control loop is functioning normally.","week":"8"},{"s":"A brand new heart murmur heard between S1 and S2 with the patient reporting shortness of breath climbing one flight of stairs","act":1,"why":"A sound between S1 and S2 occurs during systole, when the AV valves should be sealed and the semilunar valves open. Turbulent flow at that moment means a valve is either leaking backward or narrowed, and the exertional symptom indicates output is being compromised.","week":"8"},{"s":"A hematocrit of 46 percent in an adult male","act":0,"why":"Male hematocrit normally runs roughly 42 to 52 percent, higher than female values because androgens stimulate erythropoietin. This value sits comfortably within the expected range.","week":"8"},{"s":"Blood pressure of 186 over 118 with headache and blurred vision","act":1,"why":"Pressure this high subjects the thin-walled arterioles and capillaries of the brain, kidney, and retina to shear stress far beyond their structural tolerance. The visual and neurologic symptoms signal that end-organ vessels are already being damaged.","week":"8"},{"s":"A splitting of the second heart sound that widens during inspiration and disappears on expiration","act":0,"why":"Inspiration lowers intrathoracic pressure and increases venous return to the right heart, so the right ventricle takes slightly longer to empty and the pulmonic valve closes a moment after the aortic. Physiologic splitting varying with the breath is normal.","week":"8"},{"s":"Bleeding from a shaving cut that continues to ooze forty minutes later despite continuous direct pressure","act":1,"why":"Vascular spasm and the platelet plug should have controlled a small cut within minutes, with fibrin stabilizing it shortly after. Failure at this timescale points to a genuine defect in platelet function, platelet number, or the coagulation cascade.","week":"8"},{"s":"A capillary refill time of under two seconds with warm pink fingertips after a patient comes in from the cold","act":0,"why":"Cutaneous vasoconstriction during cold exposure conserves core heat, and rewarming restores flow through the precapillary sphincters. Brisk refill confirms peripheral perfusion is adequate.","week":"8"},{"s":"Fever with shaking chills, back pain, and dark urine beginning fifteen minutes into a blood transfusion","act":1,"why":"Preformed recipient antibodies are agglutinating and hemolyzing the donor red cells, and the freed hemoglobin is being filtered into the urine where it can obstruct the renal tubules. This is an immediate immune reaction to an ABO-incompatible unit.","week":"8"},{"s":"White blood cell count rising to 12,500 during a bacterial throat infection, with a shift toward neutrophils","act":0,"why":"Leukocytosis with a neutrophil predominance is the expected marrow response to bacterial invasion, since neutrophils are the first phagocytic responders. This is the immune system working as designed, not a blood disorder.","week":"8"},{"s":"Unilateral calf swelling with warmth and tenderness after a twelve-hour flight without moving","act":1,"why":"Prolonged immobility removes the skeletal muscle pump that normally drives venous return against gravity, so blood stagnates in the deep leg veins. Stasis plus vessel wall changes promotes clot formation, and one-sided swelling indicates obstruction of venous outflow on that side.","week":"8"}],"chains":[{"title":"Pathway of blood through the heart","start":"Deoxygenated blood returns from the systemic veins into the right atrium","steps":["Blood passes the tricuspid valve into the right ventricle and is ejected through the pulmonary semilunar valve into the pulmonary trunk","Pulmonary arteries carry it to the lungs, where capillaries around the alveoli load oxygen and unload carbon dioxide","Pulmonary veins return the now oxygenated blood to the left atrium","Blood crosses the bicuspid (mitral) valve into the left ventricle, the thickest chamber","The left ventricle contracts and ejects blood past the aortic semilunar valve into the aorta for distribution to the body"],"why":"The circuit is a figure-eight in series, not two parallel loops, so every drop must pass through the lungs before it can pass through the body. This is why the right side is a low-pressure pump feeding one organ and the left is a high-pressure pump feeding everything else.","week":"8"},{"title":"The cardiac conduction sequence and the ECG it writes","start":"The sinoatrial node in the upper right atrial wall depolarizes spontaneously because its unstable pacemaker potential drifts to threshold fastest","steps":["The impulse spreads cell to cell through atrial gap junctions, depolarizing both atria and inscribing the P wave","At the atrioventricular node conduction slows deliberately, producing the flat PR segment and giving the atria time to finish topping off the ventricles","The signal races down the atrioventricular bundle and the right and left bundle branches in the interventricular septum","Purkinje fibers deliver it to the ventricular myocardium from the apex upward, inscribing the QRS complex as the ventricles depolarize and contract","Ventricular repolarization follows and writes the T wave, after which the myocardium is ready for the next cycle"],"why":"The pattern of the ECG is dictated by the anatomy of the conduction pathway: the AV nodal delay separates P from QRS, and apex-to-base Purkinje delivery is what lets the ventricles wring blood upward toward the outflow valves rather than squeezing randomly.","week":"8"},{"title":"One cardiac cycle and where the heart sounds come from","start":"Atrial systole contracts the atria and tops off the already largely filled ventricles, completing end-diastolic volume","steps":["Ventricular contraction begins and ventricular pressure rises above atrial pressure, snapping the AV valves shut and producing the first heart sound, S1 or lub","With all four valves closed the ventricles contract isovolumetrically, building pressure without changing volume or ejecting anything","When ventricular pressure exceeds aortic and pulmonary trunk pressure the semilunar valves open and ventricular ejection occurs, expelling the stroke volume","The ventricles relax, pressure falls below arterial pressure, and backflow closes the semilunar valves, producing the second heart sound, S2 or dub","Isovolumetric relaxation continues until ventricular pressure drops below atrial pressure, the AV valves open, and passive ventricular filling begins the next cycle"],"why":"Every event in the cycle is driven by a pressure gradient, and valves are purely passive flaps that open and close because of it. The heart sounds are the closing of valves, not the contraction of muscle, which is why S1 marks the start of systole and S2 marks its end.","week":"8"},{"title":"The Frank-Starling relationship links venous return to output","start":"Increased venous return, for example from the skeletal muscle pump during exercise, delivers more blood to the right atrium","steps":["Greater filling raises end-diastolic volume, so the ventricular walls are stretched further during diastole","Stretch pulls the sarcomeres toward their optimal length and improves the overlap of thick and thin filaments","More cross-bridges can form, so the ventricle contracts with greater force on the very next beat without any change in nervous or hormonal signaling","Stroke volume rises, and since cardiac output equals heart rate times stroke volume, output rises with it","The extra output moves the returned blood onward, so the two ventricles automatically stay matched and blood does not pool in the lungs or the systemic veins"],"why":"This is an intrinsic length-tension property of cardiac muscle itself, not a reflex. It is the reason the right and left ventricles pump identical outputs over time despite being controlled independently.","week":"8"},{"title":"Baroreceptor reflex response to a fall in blood pressure","start":"Blood pressure drops, for example on standing up quickly, and the arterial walls of the carotid sinus and aortic arch stretch less","steps":["Baroreceptors in those walls decrease their firing rate to the cardiovascular center in the medulla oblongata","The medulla responds by increasing sympathetic outflow and decreasing parasympathetic vagal outflow","Sympathetic stimulation raises heart rate (positive chronotropy) and contractility (positive inotropy), increasing cardiac output","Sympathetic stimulation of vascular smooth muscle causes arteriolar vasoconstriction, raising total peripheral resistance","Mean arterial pressure, which is cardiac output times peripheral resistance, rises back toward normal and baroreceptor firing returns to baseline"],"why":"Baroreceptors sense stretch, not pressure directly, so less stretch is read as less pressure. The reflex is negative feedback with a fast neural loop, which is why the correction happens within seconds rather than the minutes required by hormonal routes.","week":"8"},{"title":"Hemostasis after a small vessel is cut","start":"The vessel wall is damaged, exposing subendothelial collagen to the flowing blood","steps":["Vascular spasm occurs as smooth muscle in the vessel wall contracts reflexively, narrowing the lumen and slowing blood loss","Platelets adhere to the exposed collagen, become activated, change shape, and release chemicals that recruit more platelets, forming a platelet plug","The coagulation cascade is triggered by both intrinsic and extrinsic pathways, which converge on a common pathway that activates factor X","Activated factor X, with calcium and other factors, converts prothrombin to thrombin","Thrombin converts soluble fibrinogen into insoluble fibrin threads that mesh through the platelet plug, trapping cells and forming a stable clot"],"why":"The three steps escalate from fast and weak to slow and strong: spasm buys seconds, the platelet plug buys minutes, and fibrin provides the durable seal. Thrombin is the pivot because it both makes fibrin and feeds back to accelerate its own production.","week":"8"},{"title":"How the ABO blood typing reaction works","start":"Red blood cell membranes carry surface antigens, or agglutinogens, that are determined genetically as A, B, both, or neither","steps":["During infancy the plasma develops antibodies, or agglutinins, against whatever A or B antigen the person does not possess","A type A person therefore carries anti-B antibodies, and a type O person carries both anti-A and anti-B","If donor red cells carrying a foreign antigen enter that plasma, the recipient antibodies bind them at multiple sites","Cross-linked red cells clump together, which is agglutination, and this is the visible reaction on a typing slide","Agglutinated cells are then hemolyzed, releasing hemoglobin that can obstruct kidney tubules, which is why compatibility must be established before transfusion"],"why":"The key is that ABO antibodies are preformed and present without prior exposure, unlike Rh antibodies, which is why a first mismatched ABO transfusion reacts immediately while a first Rh exposure only sensitizes.","week":"8"}]},"9":{"labs":[{"labs":[["PO2 40 mmHg","down"],["PCO2 45 mmHg","up"],["Hb O2 saturation 75%","down"],["pH 7.37","down"]],"opts":["Blood in a systemic artery","Mixed venous blood in the pulmonary artery","Blood just leaving a pulmonary capillary","Alveolar gas"],"c":1,"why":"A saturation of 75% alongside a PO2 of 40 mmHg is the normal venous reserve. At rest, tissues extract only about a quarter of the oxygen carried, so blood returning to the right heart is still three-quarters loaded. The mildly raised PCO2 and mildly lowered pH come from the CO2 just picked up at the tissue and converted to carbonic acid.","week":"9"},{"labs":[["PO2 104 mmHg","down"],["PCO2 40 mmHg","up"],["Water vapour pressure 47 mmHg","up"],["Total pressure 760 mmHg","n"]],"opts":["Dry atmospheric air at sea level","Alveolar gas","Gas sitting in the anatomic dead space","Blood in a pulmonary vein"],"c":1,"why":"Alveolar PO2 is far below the 160 mmHg of dry inspired air for three reasons: incoming air is humidified so water vapour claims 47 mmHg of the total, tidal air only mixes with the functional residual capacity rather than replacing it, and oxygen is continuously removed by capillary blood while CO2 is continuously added.","week":"9"},{"labs":[["pH 7.52","up"],["PaCO2 27 mmHg","down"],["PaO2 106 mmHg","up"],["HCO3 24 mEq/L","n"]],"opts":["Metabolic alkalosis","Acute respiratory alkalosis from hyperventilation","Acute respiratory acidosis","Metabolic acidosis with respiratory compensation"],"c":1,"why":"pH and PaCO2 moving in opposite directions marks a respiratory origin, since CO2 is an acid gas. A still-normal bicarbonate is the timing clue: renal compensation takes days, so an untouched HCO3 means the disturbance is minutes to hours old.","week":"9"},{"labs":[["pH 7.26","down"],["PaCO2 66 mmHg","up"],["PaO2 56 mmHg","down"],["HCO3 26 mEq/L","n"]],"opts":["Acute respiratory acidosis from hypoventilation","Metabolic acidosis with respiratory compensation","Chronic CO2 retention that is fully compensated","Anemic hypoxia"],"c":0,"why":"Hypoventilation moves both gases the wrong way at once, raising CO2 and lowering O2 together, whereas a pure diffusion problem lowers O2 with little CO2 change because CO2 is about twenty times more soluble. The near-normal bicarbonate excludes chronic retention, in which renal HCO3 retention would have driven bicarbonate well above 30 and pulled pH back toward normal.","week":"9"},{"labs":[["Local temperature","up"],["Local PCO2","up"],["Local pH","down"],["2,3-BPG","up"],["P50","up"]],"opts":["Blood in a pulmonary capillary","Blood in the capillary bed of exercising skeletal muscle","Refrigerated banked blood","Blood in a hypothermic patient"],"c":1,"why":"Every value here is a by-product of high metabolic rate, and each independently loosens hemoglobin's grip on oxygen. A rising P50 means a higher PO2 is now needed for half saturation, which is the numeric definition of a right shift and of easier unloading exactly where demand is greatest.","week":"9"},{"labs":[["Temperature","down"],["pH","up"],["2,3-BPG","down"],["P50","down"]],"opts":["Blood at an exercising muscle","Blood in a patient with a high fever","Refrigerated stored or hypothermic blood","Blood after a week of altitude acclimatization"],"c":2,"why":"Cold and alkalosis both tighten oxygen binding, and stored red cells progressively lose 2,3-BPG because glycolysis slows. A falling P50 is a left shift: hemoglobin loads oxygen readily in the lung but releases it poorly at the tissue. Altitude acclimatization does the opposite by raising 2,3-BPG.","week":"9"},{"labs":[["PaO2 98 mmHg","n"],["Pulse oximeter reading 99%","n"],["Hemoglobin concentration 14 g/dL","n"],["Arterial oxygen content","down"]],"opts":["Anemic hypoxia from acute blood loss","Carbon monoxide poisoning","Hypoxemic hypoxia from hypoventilation","Histotoxic hypoxia from cyanide"],"c":1,"why":"PaO2 measures only oxygen dissolved in plasma, which carbon monoxide does not affect, and a two-wavelength pulse oximeter cannot tell carboxyhemoglobin from oxyhemoglobin. Content collapses because CO occupies heme sites with roughly 200 times the affinity of oxygen and left-shifts the curve on the remaining sites, so what is bound is also released poorly.","week":"9"},{"labs":[["PaO2 96 mmHg","n"],["SaO2 98%","n"],["Hemoglobin 7 g/dL","down"],["Arterial oxygen content","down"],["Cardiac output","up"]],"opts":["Anemic hypoxia","Hypoxemic hypoxia","Histotoxic hypoxia","Carbon monoxide poisoning"],"c":0,"why":"Saturation is a percentage of the binding sites present, not an amount of oxygen. With normal lungs the percentage stays perfect, but with half the hemoglobin the blood carries half the oxygen, which is why content rather than saturation is the meaningful number. The raised cardiac output is the compensation, since delivery equals content times flow.","week":"9"},{"labs":[["FEV1","down"],["FVC","down"],["FEV1/FVC ratio","down"],["Residual volume","up"],["Total lung capacity","up"]],"opts":["Restrictive pattern such as pulmonary fibrosis","Obstructive pattern such as asthma or emphysema","Normal spirometry in a trained athlete","Respiratory muscle weakness"],"c":1,"why":"Narrowed or floppy airways collapse during a forced expiration, so emptying is slow: FEV1 falls proportionally more than FVC and the ratio drops. Air trapped behind those airways cannot be exhaled, which raises residual volume and hyperinflates the chest, so total lung capacity rises rather than falls.","week":"9"},{"labs":[["FVC","down"],["FEV1","down"],["FEV1/FVC ratio","n"],["Total lung capacity","down"],["Lung compliance","down"]],"opts":["Obstructive pattern","Restrictive pattern such as pulmonary fibrosis","Acute asthma attack","Normal aging lung"],"c":1,"why":"The preserved ratio is the discriminator: airflow itself is not obstructed, the lung is simply small and stiff. Reduced compliance means a larger change in transpulmonary pressure is needed for each unit of volume, so every volume and capacity shrinks together and the work of breathing rises.","week":"9"},{"labs":[["Tidal volume 250 mL","down"],["Respiratory rate 30 per minute","up"],["Minute ventilation 7.5 L/min","n"],["Anatomic dead space 150 mL","n"],["Alveolar ventilation","down"]],"opts":["Normal quiet breathing","Rapid shallow breathing with reduced alveolar ventilation","Hyperventilation producing respiratory alkalosis","Slow deep breathing"],"c":1,"why":"Dead space is a fixed volume that is ventilated first on every single breath, so shallow breaths waste a larger fraction of each one. Here only 100 mL of each 250 mL breath reaches an alveolus, giving 3.0 L/min of alveolar ventilation, against 350 mL times 12 breaths, or 4.2 L/min, at rest. Minute ventilation looks normal while effective ventilation has fallen by nearly a third.","week":"9"},{"labs":[["Tidal volume 500 mL","n"],["Inspiratory reserve volume 3000 mL","n"],["Expiratory reserve volume 1100 mL","n"],["Residual volume 1200 mL","n"]],"opts":["Vital capacity 4600 mL and total lung capacity 5800 mL","Vital capacity 5800 mL and total lung capacity 4600 mL","Functional residual capacity 3500 mL","Inspiratory capacity 1600 mL"],"c":0,"why":"Vital capacity is everything that can actually be moved, so TV plus IRV plus ERV equals 4600 mL; total lung capacity adds the residual volume that can never be exhaled, giving 5800 mL. The distractors swap the two capacities or swap functional residual capacity (ERV plus RV, 2300 mL) with inspiratory capacity (TV plus IRV, 3500 mL). The distractors mislabel a capacity: inspiratory capacity (TV plus IRV, 3500 mL) is offered under the functional residual capacity label, while 1600 mL (TV plus ERV) is offered as an inspiratory capacity that is neither.","week":"9"}],"pairs":[{"clue":"The pressure in the fluid-filled space between the two pleural layers, which stays roughly 4 mmHg below atmospheric even at the end of a quiet expiration.","a":"Intrapleural pressure","b":"Intrapulmonary (alveolar) pressure","why":"Alveolar pressure swings above and below atmospheric with each breath and returns exactly to atmospheric between breaths, because the alveoli are open to outside air. The pleural space is sealed, so the inward elastic recoil of the lung pulling against the outward spring of the chest wall holds it permanently negative.","week":"9","c":0},{"clue":"The serous layer fused to the outer surface of the lung, dipping down into the fissures between lobes.","a":"Visceral pleura","b":"Parietal pleura","why":"Visceral means covering the organ itself; parietal lines the wall of the cavity, meaning the inner thoracic wall, mediastinum and superior diaphragm. Only the parietal layer carries somatic sensory fibres, which is why pleuritic pain is sharp and precisely localized while the lung surface is insensate.","week":"9","c":0},{"clue":"The alveolar cell that manufactures and secretes surfactant.","a":"Type II alveolar (septal) cell","b":"Type I alveolar cell","why":"Type I cells are simple squamous, cover about 95% of the alveolar surface, and exist to be thin enough for rapid diffusion. Type II cells are cuboidal and packed with secretory organelles, trading thinness for the machinery to build phospholipid.","week":"9","c":0},{"clue":"The air that remains in the lungs even after the most forceful possible expiration.","a":"Residual volume","b":"Expiratory reserve volume","why":"Expiratory reserve volume is air you can still force out after a quiet expiration, so a spirometer can measure it directly. Residual volume can never be exhaled because small airways close first, so it must be measured indirectly, and it is what keeps alveoli open and gas exchange continuous between breaths.","week":"9","c":0},{"clue":"The largest volume of air a person can move in a single breath, from maximal inspiration to maximal expiration.","a":"Vital capacity","b":"Total lung capacity","why":"Total lung capacity includes residual volume, which by definition cannot be moved. Vital capacity is total lung capacity minus residual volume, which is precisely why vital capacity can be measured at the mouth and total lung capacity cannot.","week":"9","c":0},{"clue":"The volume of air sitting in the lungs at the end of a normal quiet expiration.","a":"Functional residual capacity","b":"Residual volume","why":"Functional residual capacity is expiratory reserve volume plus residual volume, so it is always the larger of the two. It matters because it is the standing reservoir that fresh tidal air mixes into, which damps breath-to-breath swings in alveolar PO2 and PCO2 and keeps arterial gases steady.","week":"9","c":0},{"clue":"The receptors that generate most of the moment-to-moment drive to breathe by sensing hydrogen ions produced from CO2 in the cerebrospinal fluid.","a":"Central chemoreceptors of the ventrolateral medulla","b":"Peripheral chemoreceptors in the carotid and aortic bodies","why":"CO2 is lipid soluble and crosses the blood brain barrier freely, while H+ and bicarbonate do not. That makes the medullary receptors effectively a CO2 sensor reading pH in a compartment with almost no protein buffering, so small rises in PaCO2 produce large pH changes and a powerful ventilatory response.","week":"9","c":0},{"clue":"The receptors responsible for the increase in ventilation when arterial PO2 falls below about 60 mmHg.","a":"Peripheral chemoreceptors in the carotid and aortic bodies","b":"Central chemoreceptors in the medulla","why":"Only the peripheral receptors sense oxygen, and they respond to dissolved arterial PO2 rather than to total oxygen content, which is why anemia and carbon monoxide poisoning do not by themselves stimulate breathing. Central receptors are depressed by hypoxia, not excited by it.","week":"9","c":0},{"clue":"The form in which roughly 70% of carbon dioxide travels from the tissues to the lungs.","a":"Bicarbonate ion dissolved in plasma","b":"Carbaminohemoglobin","why":"Carbaminohemoglobin carries about 23% and dissolved CO2 about 7%. The bicarbonate route dominates because carbonic anhydrase inside the red cell converts CO2 fast enough to keep plasma CO2 low, which preserves the diffusion gradient pulling more CO2 out of the tissue.","week":"9","c":0},{"clue":"The effect by which rising CO2 and falling pH at an active tissue make hemoglobin release more oxygen.","a":"Bohr effect","b":"Haldane effect","why":"Bohr describes CO2 and H+ acting on oxygen binding; Haldane is the mirror image, in which unloading oxygen lets hemoglobin carry more CO2. Both operate at the same capillary at the same instant, so the trick is direction: Bohr is about O2 leaving, Haldane is about CO2 arriving.","week":"9","c":0},{"clue":"The movement of chloride into the red blood cell as bicarbonate diffuses out into the plasma.","a":"Chloride shift","b":"Haldane effect","why":"This is electrical bookkeeping, not gas transport. Bicarbonate is a negative ion leaving the cell, so another negative ion must enter to prevent a charge imbalance that would otherwise stall further bicarbonate export and shut down the main CO2 pathway.","week":"9","c":0},{"clue":"The elastic flap of cartilage that folds back over the laryngeal inlet during swallowing.","a":"Epiglottis","b":"Glottis","why":"The glottis is the opening itself, the space between the vocal folds, not a structure at all. Confusing the lid with the hole it covers is the single commonest wording error on upper airway questions.","week":"9","c":0},{"clue":"The last airway of the conducting zone, the final generation whose wall contains no alveoli.","a":"Terminal bronchiole","b":"Respiratory bronchiole","why":"The respiratory zone begins the moment alveoli appear in an airway wall, which happens at the respiratory bronchiole. Everything upstream only warms, humidifies and filters air, and the total volume of that upstream tubing is the anatomic dead space.","week":"9","c":0},{"clue":"The roughly 150 mL of inspired air that fills conducting airways and never reaches an exchange surface.","a":"Anatomic dead space","b":"Residual volume","why":"Dead space air moves in and out with every breath but never touches a capillary; residual volume sits inside alveoli where exchange is actively occurring. One is wasted ventilation, the other is a working reserve, and only dead space subtracts from alveolar ventilation.","week":"9","c":0},{"clue":"How a pulmonary arteriole responds when the alveolus it supplies becomes hypoxic.","a":"It constricts, diverting blood toward better ventilated alveoli","b":"It dilates, to deliver more blood to the low-oxygen region","why":"Systemic arterioles dilate in hypoxia because their job is to feed a starving tissue. Pulmonary arterioles have the opposite job, matching perfusion to ventilation, so pushing blood past an unventilated alveolus would only dump poorly oxygenated blood into the systemic circulation.","week":"9","c":0},{"clue":"The only airway cartilage that forms a complete ring all the way around the lumen.","a":"Cricoid cartilage","b":"Thyroid cartilage","why":"The thyroid cartilage is a shield that is open posteriorly, and the tracheal cartilages are C-shaped with a soft posterior gap so the oesophagus can bulge forward during swallowing. The cricoid's uninterrupted ring is why it is the landmark used to compress and seal the airway.","week":"9","c":0},{"clue":"The main bronchus into which an aspirated peanut is more likely to fall.","a":"Right main bronchus, because it is wider, shorter and more vertical","b":"Left main bronchus, because it is longer and more horizontal","why":"The heart occupies the left side of the mediastinum, forcing the left bronchus to angle sharply around it, while the right descends nearly in line with the trachea. A straighter, wider path plus gravity decides where an inhaled object lands.","week":"9","c":0},{"clue":"The gas law that explains why air flows into the lungs when the diaphragm contracts.","a":"Boyle law: at constant temperature, pressure varies inversely with volume","b":"Dalton law: total pressure equals the sum of the partial pressures","why":"Boyle governs bulk airflow, since enlarging the thorax lowers alveolar pressure below atmospheric and air moves down that gradient. Dalton governs what happens once the air is inside, because each gas then diffuses independently down its own partial pressure gradient across the respiratory membrane.","week":"9","c":0}],"redflags":[{"s":"A healthy 20-year-old sprinting hard has a respiratory rate of 34 and a tidal volume near 2 L, with both back to baseline five minutes after stopping.","act":0,"why":"Exercise hyperpnea matches ventilation to metabolic demand and is driven mainly by feed-forward signals from the motor cortex and by joint and muscle proprioceptors, not by any measurable change in arterial gases. The prompt return to baseline confirms the drive was demand rather than disease.","week":"9"},{"s":"Mixed venous blood sampled from the pulmonary artery is only 75% saturated with oxygen.","act":0,"why":"This is the normal venous reserve. At rest, tissues extract about 5 mL of oxygen from each 100 mL of the roughly 20 mL it carries, leaving three-quarters of the hemoglobin still loaded as a buffer that can be drawn on the instant demand rises.","week":"9"},{"s":"During a voluntary breath hold the urge to breathe becomes overwhelming while the pulse oximeter still reads 96%.","act":0,"why":"The breaking point of a breath hold is set by rising PaCO2 acting on central chemoreceptors, not by falling oxygen, so the alarm fires long before saturation is threatened. The dangerous version is the reverse pattern after deliberate hyperventilation, where the CO2 alarm is silenced while oxygen keeps falling.","week":"9"},{"s":"A hiker who arrived at 4000 m two days ago has a PaCO2 of 31 mmHg and a pH of 7.46.","act":0,"why":"Reduced barometric pressure lowers inspired PO2, the carotid bodies drive a hypoxic ventilatory response, and the extra ventilation blows off CO2, producing a mild respiratory alkalosis. Renal bicarbonate excretion over the following days will return pH toward normal, so this is acclimatization in progress.","week":"9"},{"s":"Intrapleural pressure measured at the end of a quiet expiration is 4 mmHg below atmospheric.","act":0,"why":"This is the normal equilibrium point at which the lung's inward elastic recoil exactly balances the chest wall's outward spring. Its continuous negativity is what holds the visceral and parietal pleurae together and keeps the lung expanded against its own recoil.","week":"9"},{"s":"An adult found unresponsive has a respiratory rate of 5, a PaCO2 of 68 mmHg and a pH of 7.19.","act":1,"why":"Alveolar ventilation has fallen far below the rate of CO2 production, so carbonic acid accumulates faster than buffers can absorb it. Because a high CO2 is itself narcotic and depresses the very centres that should respond, the situation becomes a positive feedback spiral rather than a self-correcting one.","week":"9"},{"s":"A resting adult breathing room air has an SpO2 of 84%.","act":1,"why":"84% sits on the steep portion of the oxyhemoglobin dissociation curve, corresponding to a PaO2 near 50 mmHg. On that part of the curve a further small drop in PO2 produces a disproportionately large fall in saturation and therefore in oxygen content, so there is no margin left.","week":"9"},{"s":"After a stab wound to the chest, air is heard being sucked into the wound with each breath and breath sounds are absent on that side.","act":1,"why":"The pleural seal has been broken, so intrapleural pressure equalizes with atmospheric and transpulmonary pressure falls to zero. With no distending pressure, the lung's elastic recoil and alveolar surface tension are unopposed and that lung collapses, ending its ventilation immediately.","week":"9"},{"s":"Breath sounds are absent on the right, the trachea is deviated toward the left, neck veins are distended and blood pressure is falling.","act":1,"why":"A one-way flap is admitting air into the pleural space on inspiration but not letting it out, so intrapleural pressure climbs above atmospheric. The mediastinum is pushed across, which kinks the great veins and cuts venous return, making this a circulatory emergency as much as a respiratory one.","week":"9"},{"s":"A man rescued from a running car in a closed garage is confused, and the pulse oximeter reads 100% on room air.","act":1,"why":"A conventional two-wavelength oximeter reads carboxyhemoglobin as if it were oxyhemoglobin, so a reassuring number can accompany severely reduced oxygen content. Carbon monoxide binds heme with roughly 200 times the affinity of oxygen and also left-shifts the curve, so the little oxygen still bound is released poorly.","week":"9"},{"s":"An infant born at 27 weeks has grunting expirations, intercostal retractions and lungs that need unusually high pressure to inflate.","act":1,"why":"Type II alveolar cells do not produce adequate surfactant until roughly 28 to 32 weeks, so alveolar surface tension is unopposed. By Laplace's law the smallest alveoli generate the greatest collapsing pressure and empty first, compliance falls sharply, and every breath must re-expand collapsed lung.","week":"9"},{"s":"A patient who had been wheezing loudly through a severe asthma attack now has a quiet chest and is too breathless to speak in full sentences.","act":1,"why":"Wheeze is generated by turbulent airflow through narrowed airways, so it requires air to be moving. Its disappearance in a patient who is working harder means flow itself has become minimal, making a silent chest a sign of worse obstruction rather than of improvement.","week":"9"},{"s":"A previously well child sits leaning forward, drooling, with audible stridor at rest and a muffled voice.","act":1,"why":"Stridor is a harsh monophonic sound produced by turbulent flow through a narrowed extrathoracic airway, and it is audible at rest only when the lumen is already critically reduced. Drooling and the tripod posture show the child is using every mechanical advantage to keep that airway open.","week":"9"}],"chains":[{"title":"Quiet inspiration: how muscle contraction becomes airflow","start":"The medullary respiratory centre fires down the phrenic nerves and the diaphragm contracts.","steps":["The diaphragm flattens and descends while the external intercostals swing the ribs up and out, enlarging the thoracic cavity in the vertical, anteroposterior and lateral dimensions.","The parietal pleura moves outward with the chest wall, and because the pleural fluid is cohesive and the pleural space is sealed, the visceral pleura and the lung are dragged with it.","Intrapleural pressure falls further below atmospheric, from about minus 4 to about minus 6 mmHg, so transpulmonary pressure rises and the alveoli are stretched open.","Alveolar volume increases, so by Boyle law alveolar pressure drops roughly 1 mmHg below atmospheric.","Air flows down that pressure gradient through the conducting airways into the alveoli until alveolar pressure again equals atmospheric and flow stops."],"why":"The lung has no muscle of its own and cannot pull itself open. Every breath is a chain of volume changing pressure and pressure moving air, with the negative intrapleural pressure serving as the mechanical coupling between the chest wall and the lung.","week":"9"},{"title":"External respiration: loading oxygen at the alveolus","start":"Fresh tidal air reaches the alveolus and holds alveolar PO2 at about 104 mmHg.","steps":["Blood delivered by the pulmonary artery arrives with a PO2 of only 40 mmHg, creating a partial pressure gradient of roughly 64 mmHg across the respiratory membrane.","Oxygen diffuses down that gradient through the type I alveolar cell, the fused basement membranes and the capillary endothelium, a barrier well under one micrometre thick.","Dissolved oxygen raises plasma PO2, which drives oxygen into the red cell and onto the heme iron of hemoglobin.","Binding removes oxygen from solution, so plasma PO2 stays low and the gradient remains steep until the blood equilibrates at about 100 mmHg and 98% saturation, which takes only a third of the capillary transit time.","At the same instant CO2 diffuses the opposite way across a gradient of only about 5 mmHg, which suffices because CO2 is roughly twenty times more soluble in the membrane than oxygen."],"why":"Nothing pumps gas across the alveolar wall. Movement is pure passive diffusion down partial pressure gradients, and hemoglobin's role is to keep sucking oxygen out of solution so the gradient never has a chance to flatten.","week":"9"},{"title":"The Bohr effect: unloading oxygen where it is needed","start":"An exercising muscle sharply raises its metabolic rate.","steps":["Aerobic metabolism generates CO2 and heat, so local tissue PCO2 and temperature both rise, and anaerobic glycolysis adds lactic acid.","CO2 diffusing into the red cell is hydrated by carbonic anhydrase to carbonic acid, which immediately dissociates into hydrogen ion and bicarbonate.","Hydrogen ions bind to specific sites on the globin chains and stabilize the low-affinity form of hemoglobin, an effect reinforced by warmth and, in chronic hypoxia, by rising 2,3-BPG.","The oxyhemoglobin dissociation curve shifts to the right and P50 increases, so at any given PO2 hemoglobin holds less oxygen.","More oxygen is therefore released at exactly the capillaries with the greatest demand, and venous saturation draining that muscle can fall from 75% toward 25%."],"why":"The position of the dissociation curve is a demand signal, not a fixed property. The very waste products of hard work are the chemical messengers that force hemoglobin to give up more of its cargo in the tissue that produced them.","week":"9"},{"title":"Carbon dioxide transport and the chloride shift","start":"CO2 produced by a metabolizing cell diffuses into the plasma and then into the red blood cell.","steps":["Carbonic anhydrase inside the red cell converts about 70% of it to carbonic acid, which dissociates into hydrogen ion and bicarbonate.","Bicarbonate is exported into the plasma by an antiporter that brings chloride in, the chloride shift, which keeps the red cell electrically neutral so export can continue.","The hydrogen ion left behind is buffered by deoxyhemoglobin, which is a better proton acceptor and a better CO2 carrier than oxygenated hemoglobin, the Haldane effect.","Around 23% of the CO2 binds directly to the amino groups of globin as carbaminohemoglobin, and the remaining 7% simply stays dissolved in plasma.","In the pulmonary capillary the entire sequence runs backwards: oxygen binding drives hydrogen ion off hemoglobin, bicarbonate re-enters the cell in exchange for chloride, carbonic anhydrase regenerates CO2, and it diffuses into the alveolus."],"why":"The same enzyme and the same reaction run in opposite directions at the two ends of the circulation, and the direction is set entirely by local gradients and by how much oxygen hemoglobin happens to be carrying. This is why oxygen and CO2 transport are one coupled system rather than two.","week":"9"},{"title":"Chemical control of breathing: the response to a rising PaCO2","start":"Alveolar ventilation falls slightly and arterial PCO2 climbs above 40 mmHg.","steps":["CO2, unlike hydrogen ion and bicarbonate, is lipid soluble and crosses the blood brain barrier freely into the cerebrospinal fluid.","Carbonic anhydrase in the CSF converts it to carbonic acid, which dissociates and lowers CSF pH sharply because the CSF contains almost no protein buffer.","Central chemoreceptors on the ventrolateral surface of the medulla detect the rise in CSF hydrogen ion and increase their firing rate.","The medullary respiratory centres respond by increasing both the rate and the depth of output to the diaphragm and intercostals, raising alveolar ventilation.","Greater ventilation blows off CO2, PaCO2 returns to 40 mmHg, CSF pH normalizes and the stimulus is removed."],"why":"Breathing is normally regulated as an acid-base loop rather than an oxygen loop. CO2 is monitored indirectly as hydrogen ion in a poorly buffered compartment, which is why a 5 mmHg rise in PaCO2 doubles ventilation while PaO2 must fall below 60 mmHg before it does much at all.","week":"9"},{"title":"Surfactant, surface tension and compliance","start":"Type II alveolar cells secrete a phospholipid and protein surfactant film into the fluid lining the alveoli.","steps":["Surfactant molecules insert themselves between water molecules at the air-liquid interface and disrupt their hydrogen bonding, which lowers the surface tension of the fluid layer.","By Laplace's law, collapsing pressure equals twice the tension divided by the radius, so lowering tension reduces the inward pressure on every alveolus.","Because surfactant becomes more concentrated as an alveolus shrinks, its tension-lowering effect is strongest in the smallest alveoli, which is exactly where collapsing pressure would otherwise be highest.","Small alveoli therefore stop emptying into larger neighbours, alveoli of different sizes remain open together, and lung compliance rises so a given transpulmonary pressure produces a larger volume change.","The work of breathing falls to a few percent of resting energy expenditure; without surfactant, as in a premature infant, alveoli collapse on each expiration and every breath must re-inflate them from scratch."],"why":"The dominant elastic load on the lung is not connective tissue but the surface tension of the water film lining 300 million alveoli. Surfactant is the mechanism that makes an otherwise physically unstable arrangement of interconnected bubbles stable and cheap to ventilate.","week":"9"},{"title":"Pneumothorax: what happens when intrapleural pressure is lost","start":"A puncture opens the pleural cavity to atmospheric air.","steps":["Because intrapleural pressure was subatmospheric, air rushes into the pleural space down its own pressure gradient.","Intrapleural pressure rises until it equals atmospheric, so transpulmonary pressure, the difference between alveolar and intrapleural pressure, falls to zero.","With no distending pressure left, the lung's elastic recoil and its alveolar surface tension act unopposed.","That lung recoils inward and collapses while the chest wall on the same side springs outward toward its own resting position.","Ventilation of the collapsed lung ceases, blood continues to flow past its unventilated alveoli and returns to the left heart still deoxygenated, and arterial PO2 falls."],"why":"This is the clearest demonstration that the negative intrapleural pressure, and not any attachment, is what holds the lung expanded against the chest wall. Remove the pressure difference and the lung reverts to the small, recoiled state it would occupy outside the body.","week":"9"}]},"10":{"labs":[{"labs":[["Gastric lumen pH","down"],["Pepsin activity","up"],["Blood gastrin","up"],["Intrinsic factor secretion","up"]],"opts":["Active gastric phase of a meal","Fasting stomach between meals","Duodenal chyme after neutralization","Salivary phase in the mouth"],"c":0,"why":"Parietal cells pump H+ and release intrinsic factor in the same burst, and it is that acid which converts chief-cell pepsinogen into active pepsin. Gastrin is the hormone driving the whole event, so acid, enzyme activation, and hormone all rise together only in the working stomach.","week":"10"},{"labs":[["Blood secretin","up"],["Pancreatic bicarbonate output","up"],["Duodenal lumen pH","up"],["Rate of gastric emptying","down"]],"opts":["Acidic chyme arriving in the duodenum","Cephalic phase triggered by the smell of food","Mass movement in the colon","The pharyngeal phase of swallowing"],"c":0,"why":"Acid itself is the stimulus for duodenal S cells to release secretin, and secretin acts on pancreatic duct cells rather than acinar cells, so what pours out is bicarbonate-rich fluid. The rising pH protects the duodenal lining and puts pancreatic enzymes near their optimum, while slowed emptying keeps more acid from arriving before the buffer catches up.","week":"10"},{"labs":[["Blood cholecystokinin","up"],["Gallbladder volume","down"],["Bile salts in the duodenum","up"],["Hepatopancreatic sphincter tone","down"]],"opts":["Fat and protein entering the duodenum","A pure water load","Fasting, with the gallbladder filling","Starch being digested in the mouth"],"c":0,"why":"Fatty acids and peptides are the specific trigger for duodenal I cells to release CCK, and CCK does two coordinated things: it contracts the gallbladder wall and relaxes the sphincter of Oddi. The falling gallbladder volume and the rising duodenal bile salts are the same event viewed from each end of the cystic and bile ducts.","week":"10"},{"labs":[["Fat content of stool","up"],["Vitamin K absorption","down"],["Stool color","abn"],["Pancreatic lipase output","n"]],"opts":["Bile is not reaching the small intestine","The exocrine pancreas has failed","A brush-border disaccharidase is missing","Gastric acid secretion has stopped"],"c":0,"why":"Normal lipase is the discriminator. The enzyme is present but fat still passes through undigested, which can only happen if the fat was never emulsified into small droplets, since lipase is water-soluble and can attack only the surface of a globule. Pale stool follows because bile pigment never reaches the gut to be converted to stercobilin.","week":"10"},{"labs":[["Brush-border lactase","down"],["Breath hydrogen after milk","up"],["Water held in the colonic lumen","up"],["Pancreatic amylase","n"]],"opts":["A missing brush-border disaccharidase","A missing pancreatic enzyme","Bile salt deficiency","Failure of gastric protein digestion"],"c":0,"why":"Carbohydrate digestion finishes at the microvillus membrane, not in the lumen, so a normal pancreas cannot compensate. Undigested lactose stays in the lumen, drags water in osmotically, and is fermented by colonic bacteria into hydrogen gas that diffuses into blood and is exhaled.","week":"10"},{"labs":[["Vitamin B12 absorption","down"],["Bile salts returned to the liver","down"],["Bile salts lost in stool","up"],["Intrinsic factor secretion","n"]],"opts":["Loss of the terminal ileum","Loss of the stomach","Loss of the gallbladder","Loss of the colon"],"c":0,"why":"Intrinsic factor is normal, so the stomach is intact and the defect must be at the receiving end. The terminal ileum is the single site with receptors for the intrinsic factor–B12 complex and the transporters for the enterohepatic recycling of bile salts, so losing it takes out both functions at once.","week":"10"},{"labs":[["Plasma albumin","down"],["Clotting factor production","down"],["Blood ammonia","up"],["Blood glucose between meals","down"]],"opts":["Failing hepatocyte function","Failing exocrine pancreas","Failing gallbladder","Failing gastric mucosa"],"c":0,"why":"Each of these is a separate liver job: manufacturing plasma proteins, manufacturing clotting factors, converting the ammonia of amino acid deamination into urea, and releasing stored glycogen between meals. No single digestive secretion explains all four, so the common factor is the hepatocyte itself.","week":"10"},{"labs":[["Glucose in the hepatic portal vein","up"],["Blood insulin","up"],["Liver glycogen","up"],["Glucose in the lymph","n"]],"opts":["Monosaccharides absorbed into portal blood after a carbohydrate meal","Fats absorbed into lacteals after a fatty meal","Fasting glycogenolysis","Protein digestion in the stomach"],"c":0,"why":"Sugars and amino acids leave the villus through the blood capillary and are carried by the hepatic portal vein straight to the liver, so the liver samples and buffers them before the rest of the body ever sees them. Normal lymph glucose confirms the route, because only lipids take the lymphatic detour.","week":"10"},{"labs":[["Chylomicrons in the lacteals","up"],["Appearance of intestinal lymph","abn"],["Triglyceride in the portal vein","n"],["Bile salt micelles in the lumen","up"]],"opts":["Lipid absorption a few hours after a fatty meal","Carbohydrate absorption","Amino acid absorption","The fasting state"],"c":0,"why":"Fatty acids and monoglycerides are re-esterified inside the enterocyte and packaged with protein into chylomicrons, which are too large to cross the capillary endothelium and instead enter the more permeable lacteal. Milky lymph together with an unremarkable portal triglyceride is the signature of that lymphatic bypass of the liver.","week":"10"},{"labs":[["Salivary amylase activity","up"],["Starch in the bolus","down"],["Maltose in the bolus","up"],["Protein digestion","n"]],"opts":["Chemical digestion in the mouth","Chemical digestion in the stomach","Chemical digestion in the duodenum","Absorption in the ileum"],"c":0,"why":"The mouth carries only one digestive enzyme of consequence, so starch begins to fall and maltose begins to appear while protein is untouched. Protein digestion cannot start until pepsin is activated by acid in the stomach, which is also where the swallowed amylase is denatured and shut down.","week":"10"},{"labs":[["Intrinsic factor","down"],["Vitamin B12 absorption","down"],["Red blood cell size","up"],["Terminal ileum structure","n"]],"opts":["Loss of parietal cells in the stomach","Loss of the terminal ileum","Loss of chief cells only","Loss of the exocrine pancreas"],"c":0,"why":"A structurally normal ileum places the fault upstream. Parietal cells make both HCl and intrinsic factor, and B12 is far too large and charged to be absorbed unescorted, so without its carrier protein it passes through an otherwise healthy absorptive surface untouched.","week":"10"},{"labs":[["Fat in stool","up"],["Bile salts in the duodenum","n"],["Pancreatic lipase output","down"],["Starch and protein digestion","down"]],"opts":["The exocrine pancreas is failing","The bile duct is obstructed","Only the brush border is affected","Gastric acid is absent"],"c":0,"why":"Bile is present, yet all three macronutrient classes are maldigested simultaneously. Only one gland supplies lipase, proteases, and amylase to the small intestine at once, so losing every category of luminal digestion at the same time localizes the problem to the pancreatic acinar cells.","week":"10"}],"pairs":[{"clue":"The wave of smooth muscle contraction that propels contents forward along the tract","a":"Peristalsis","b":"Segmentation","why":"Peristalsis is directional: circular muscle contracts behind the bolus while longitudinal muscle shortens ahead of it, producing net movement. Segmentation is stationary chopping by alternating rings of circular muscle that mixes chyme with enzymes and exposes it to the wall without advancing it.","week":"10","c":0},{"clue":"The layer of the gut wall that contains the myenteric plexus sandwiched between two sheets of muscle","a":"Muscularis externa","b":"Muscularis mucosae","why":"Muscularis externa is the thick inner-circular and outer-longitudinal coat responsible for peristalsis and segmentation, and the myenteric plexus lies between those two sheets to control them. The muscularis mucosae is a thin strip within the mucosa that only twitches villi and folds to refresh contact with chyme.","week":"10","c":0},{"clue":"The enzyme that begins chemical digestion of protein","a":"Pepsin","b":"Trypsin","why":"Pepsin is secreted as pepsinogen by gastric chief cells and activated by HCl, so it works at a pH near 2 and makes the first cuts. Trypsin is a pancreatic protease that arrives later and works in the alkaline duodenum, continuing rather than starting protein breakdown.","week":"10","c":0},{"clue":"The permanent macroscopic ridge of intestinal wall, built from mucosa plus submucosa, that spirals chyme through the lumen","a":"Circular folds (plicae circulares)","b":"Villi","why":"Circular folds are shelves large enough to see with the naked eye and they include submucosa, which is why they are permanent and do not flatten. Villi are microscopic fingers of mucosa only, so the two differ in both scale and which wall layers build them.","week":"10","c":0},{"clue":"The projections found on the apical membrane of a single absorptive cell","a":"Microvilli of the brush border","b":"Villi","why":"Microvilli are cytoplasmic extensions of one enterocyte, visible only with an electron microscope, and their membrane carries the final digestive enzymes such as lactase and maltase. Villi are multicellular mucosal projections, each covered by thousands of cells that in turn bear microvilli.","week":"10","c":0},{"clue":"The vessel inside a villus that carries absorbed fat away from the intestine","a":"Lacteal","b":"Blood capillary of the villus","why":"Chylomicrons are too large to pass through the tight capillary endothelium, but lymphatic capillaries have loose overlapping flaps that let them enter. That is why absorbed fat bypasses the hepatic portal system and enters the bloodstream at the thoracic duct instead.","week":"10","c":0},{"clue":"The organ that actually produces bile","a":"Liver","b":"Gallbladder","why":"Hepatocytes synthesize bile continuously as part of cholesterol handling and heme disposal. The gallbladder only stores that bile between meals and concentrates it by reabsorbing water, then squeezes it out when CCK arrives.","week":"10","c":0},{"clue":"The component of bile that emulsifies fat","a":"Bile salts","b":"Bilirubin","why":"Bile salts are amphipathic cholesterol derivatives with a fat-soluble face and a water-soluble face, so they coat and separate fat droplets. Bilirubin is a waste pigment from heme breakdown with no digestive action at all; it simply colors bile and, after bacterial conversion, gives stool its brown color.","week":"10","c":0},{"clue":"Emulsification of a fat globule into many small droplets is an example of","a":"Mechanical digestion","b":"Chemical digestion","why":"Emulsification changes only the physical size of the droplets and breaks no covalent bonds. Chemical digestion requires enzymatic hydrolysis, which for fat is lipase splitting triglyceride into fatty acids and a monoglyceride after emulsification has increased the available surface.","week":"10","c":0},{"clue":"The region where essentially all nutrient absorption is completed","a":"Small intestine, mostly the jejunum","b":"Large intestine","why":"The small intestine combines circular folds, villi, and microvilli to reach an enormous absorptive surface and it holds the brush-border enzymes and transporters. The large intestine lacks villi and absorbs mainly water and electrolytes, plus the vitamin K and B vitamins made by its bacteria.","week":"10","c":0},{"clue":"The hormone released specifically in response to acid arriving in the duodenum","a":"Secretin","b":"Cholecystokinin","why":"Secretin responds to low pH and drives duct cells to release bicarbonate, which is the correct fix for an acid problem. CCK responds to fats and peptides and drives enzyme release and gallbladder contraction, which is the correct fix for a digestion problem.","week":"10","c":0},{"clue":"The gastric cell that secretes hydrochloric acid and intrinsic factor","a":"Parietal cell","b":"Chief cell","why":"Parietal cells are the only source of intrinsic factor in the body and they pump H+ using an ATPase. Chief cells secrete the zymogen pepsinogen and gastric lipase, and they depend on the parietal cell's acid to activate their own product.","week":"10","c":0},{"clue":"The enzymes that perform the final step of carbohydrate digestion","a":"Brush-border enzymes such as lactase, maltase, and sucrase","b":"Pancreatic amylase","why":"Amylase can only cut starch down to disaccharides and short oligosaccharides, and no transporter accepts a disaccharide. The last bond is broken by membrane-bound enzymes on the microvilli, so digestion and absorption happen at the same square micron of membrane.","week":"10","c":0},{"clue":"The vessel that carries newly absorbed sugars and amino acids to the liver","a":"Hepatic portal vein","b":"Hepatic artery","why":"The hepatic portal vein is a second capillary-to-capillary circuit that delivers nutrient-rich but oxygen-poor blood from the intestines, letting the liver process and detoxify absorbed material first. The hepatic artery supplies oxygenated blood for the liver's own metabolic needs.","week":"10","c":0},{"clue":"The segment of small intestine where vitamin B12 and bile salts are reclaimed","a":"Ileum","b":"Duodenum","why":"The duodenum is where most chemical digestion occurs because it receives bile and pancreatic juice, but the specific receptors for the intrinsic factor–B12 complex and the bile salt transporters are expressed only distally. Recycling bile salts at the far end allows them to work through the entire length first.","week":"10","c":0},{"clue":"The innermost tunic of the gut wall, in direct contact with the lumen","a":"Mucosa","b":"Submucosa","why":"The mucosa is epithelium plus lamina propria plus muscularis mucosae, and it is the layer that secretes and absorbs. The submucosa lies just deep to it as dense connective tissue carrying the larger blood vessels, lymphatics, and the submucosal plexus that governs secretion and local blood flow.","week":"10","c":0},{"clue":"The folds of the stomach lining that flatten out as the stomach fills","a":"Rugae","b":"Circular folds","why":"Rugae are temporary accordion pleats that allow the stomach to expand from about 50 mL to well over a liter, so they disappear when full. Circular folds are permanent structural shelves of the small intestine that never flatten because they contain submucosa.","week":"10","c":0}],"redflags":[{"s":"Vomiting bright red blood shortly after repeated retching","act":1,"why":"Blood in vomit means the mucosal barrier that normally protects the wall from its own acid has been breached and a vessel is open in the esophagus or stomach. Bright red indicates the bleeding is brisk enough that acid has not yet had time to change the hemoglobin.","week":"10"},{"s":"Audible gurgling and rumbling from the abdomen about an hour after eating","act":0,"why":"Bowel sounds are simply gas and fluid being moved by segmentation and peristalsis, and they normally increase after a meal when the tract is most active. Silence, not noise, is the concerning finding because it suggests motility has stopped.","week":"10"},{"s":"Stool that is black, sticky, and tarry","act":1,"why":"That appearance means hemoglobin has been chemically altered by gastric acid and intestinal enzymes during a long transit, which localizes the bleeding to the upper tract. It reflects the same digestive chemistry acting on blood that normally acts on food.","week":"10"},{"s":"Feeling full, warm, and slightly drowsy after a large meal","act":0,"why":"Digestion is a parasympathetic, rest-and-digest activity, and blood is redistributed to the splanchnic circulation to support secretion and absorption. Stomach stretch receptors also signal satiety, so the sensation is the expected consequence of normal postprandial physiology.","week":"10"},{"s":"Yellowing of the sclera and skin together with pale clay-colored stools","act":1,"why":"Bile pigment is backing up into the blood instead of reaching the gut, so the same molecule that should color the stool is coloring the tissues. Loss of stool color at the same time as jaundice points to obstruction of bile flow rather than simple pigment overload.","week":"10"},{"s":"An urge to move the bowels within minutes of starting a large breakfast","act":0,"why":"Stretching of the stomach triggers the gastrocolic reflex, which increases colonic motility and drives mass movements toward the rectum. It is an anticipatory reflex that makes room for incoming food, not a sign of disease.","week":"10"},{"s":"Difficulty swallowing that has progressed from solids to liquids over several months, with weight loss","act":1,"why":"Swallowing is normally a fixed, reliable reflex sequence, so a steadily narrowing range of what can pass indicates a structural obstruction in the esophagus rather than a functional problem. Weight loss shows intake has already fallen below need.","week":"10"},{"s":"Brown stool color","act":0,"why":"Bilirubin excreted in bile is converted by colonic bacteria to urobilinogen and then to stercobilin, which is brown. Normal stool color is therefore direct evidence that the liver, bile duct, and colonic flora are all doing their usual jobs.","week":"10"},{"s":"Recurrent sharp right upper quadrant pain beginning about thirty minutes after fatty meals","act":1,"why":"Fat in the duodenum releases CCK, which contracts the gallbladder; pain reproducibly timed to that contraction means the gallbladder is squeezing against an obstruction. The timing itself is the diagnostic clue because it maps onto a normal hormonal reflex.","week":"10"},{"s":"Greasy, bulky, foul-smelling stools that float and are hard to flush","act":1,"why":"Fat should be almost completely absorbed in the small intestine, so fat appearing in stool means either bile is not emulsifying it or lipase is not hydrolyzing it. The floating and odor come from unabsorbed lipid and from bacterial fermentation of that lipid in the colon.","week":"10"},{"s":"Loss of appetite and a full, heavy stomach during hard exercise","act":0,"why":"Sympathetic activity during exercise constricts splanchnic vessels and shunts blood to skeletal muscle, which slows secretion, motility, and gastric emptying. Digestion is deliberately deprioritized, so the sensation reflects normal autonomic trade-offs.","week":"10"},{"s":"Bloating and gas after drinking milk in an adult whose lactase activity declined after childhood","act":0,"why":"Falling lactase after weaning is the ancestral human pattern and the majority state worldwide, so it is a normal developmental variant rather than a disease. The symptoms arise from ordinary osmosis and bacterial fermentation acting on a sugar that is simply no longer being digested.","week":"10"},{"s":"A rigid, board-like abdomen that is exquisitely tender when pressure is suddenly released","act":1,"why":"Involuntary guarding and rebound tenderness indicate that irritating material has reached the parietal peritoneum, which unlike the visceral peritoneum has somatic innervation and localizes pain sharply. The reflex muscle rigidity is the body splinting the wall.","week":"10"},{"s":"Persistent vomiting with a distended abdomen and no passage of stool or gas","act":1,"why":"Peristalsis normally moves both solids and gas distally, so the complete absence of both means the lumen is blocked. Contents accumulate behind the obstruction, distend the wall, and are eventually forced back the way they came.","week":"10"}],"chains":[{"title":"Swallowing: getting a bolus from mouth to stomach without entering the airway","start":"The tongue presses a chewed, saliva-moistened bolus against the hard palate and pushes it into the oropharynx","steps":["Touch receptors in the oropharynx fire and the swallowing center in the medulla takes over, so the process becomes involuntary from this point","The soft palate and uvula elevate to seal off the nasopharynx while the larynx rises and the epiglottis folds back over the glottis, and breathing briefly stops","The upper esophageal sphincter relaxes and the bolus enters the esophagus","A peristaltic wave in the esophageal muscularis externa contracts circular muscle behind the bolus and shortens longitudinal muscle ahead of it, driving it downward","The lower esophageal sphincter relaxes, the bolus enters the stomach, and the sphincter closes again to keep acid out of the esophagus"],"why":"The order matters because the airway must be closed before the pharyngeal muscles fire; every step after the bolus leaves the mouth is reflexive precisely because the timing is too tight to trust to voluntary control.","week":"10"},{"title":"Protein digestion from stomach to bloodstream","start":"Food distends the stomach and peptides contact the gastric mucosa","steps":["G cells release gastrin, which stimulates parietal cells to pump H+ into the lumen and chief cells to release pepsinogen","The falling pH cleaves pepsinogen into active pepsin and simultaneously denatures dietary proteins, unfolding them so their peptide bonds are exposed","Pepsin hydrolyzes the proteins into large polypeptides, and the resulting chyme is released through the pylorus into the duodenum","Pancreatic trypsin, chymotrypsin, and carboxypeptidase, working in the bicarbonate-neutralized duodenum, cut the polypeptides into short peptides","Brush-border peptidases finish the job at the microvillus membrane and amino acids are cotransported with sodium into the enterocyte, then pass into the capillary and the hepatic portal vein"],"why":"Protein needs a two-stage attack because a folded protein hides most of its bonds; acid must denature it before any protease is efficient, and each enzyme is secreted as an inactive zymogen so the cell that makes it is not digested by it.","week":"10"},{"title":"Fat digestion and its lymphatic route of absorption","start":"Chyme containing triglyceride enters the duodenum","steps":["Duodenal I cells release CCK into the blood, which contracts the gallbladder and relaxes the hepatopancreatic sphincter","Bile salts enter the lumen and emulsify the large fat globules into countless small droplets, multiplying the surface available to enzymes","Pancreatic lipase, aided by colipase, hydrolyzes the surface triglycerides into free fatty acids and monoglycerides","Bile salts form micelles that ferry these products through the watery layer to the microvillus membrane, where they diffuse into the enterocyte","Inside the cell the products are re-esterified into triglyceride, packaged as chylomicrons, and exocytosed into the lacteal, entering the blood at the thoracic duct rather than the portal vein"],"why":"Every step exists to solve one problem, that fat is not water soluble: emulsification creates surface, micelles solve transport through water, and the chylomicron package is too large for a blood capillary, which is why dietary fat is the one nutrient class that bypasses the liver on first pass.","week":"10"},{"title":"Neutralizing acid chyme so the small intestine can work","start":"Acidic chyme with a pH near 2 passes the pyloric sphincter into the duodenum","steps":["S cells in the duodenal mucosa detect the low pH and release secretin into the blood","Secretin travels to the pancreatic duct cells and stimulates them to secrete a watery bicarbonate-rich fluid into the pancreatic duct","Bicarbonate enters the duodenum and buffers the H+, raising luminal pH toward 7 to 8","The higher pH protects the duodenal epithelium and puts pancreatic amylase, lipase, and the proteases near their optimum, while inactivating any remaining pepsin","Secretin also inhibits gastrin release and slows gastric emptying, so no new acid load arrives before the buffer has caught up"],"why":"This is a classic negative feedback loop in which the stimulus, acid, calls forth the very thing that removes it; it also explains why enzymes with different pH optima are kept in separate compartments rather than mixed in one.","week":"10"},{"title":"Carbohydrate digestion from starch to liver glycogen","start":"Starch is chewed and mixed with saliva containing salivary amylase","steps":["Salivary amylase begins cutting starch into shorter chains and maltose until gastric acid denatures it in the stomach","In the duodenum, pancreatic amylase resumes the job and reduces starch to disaccharides and short oligosaccharides","Brush-border maltase, sucrase, and lactase on the microvilli split these into single sugars right at the absorptive membrane","Glucose and galactose are cotransported into the enterocyte with sodium down its gradient, while fructose enters by facilitated diffusion, and all exit into the villus capillary","Blood carries the sugars through the hepatic portal vein to the liver, where rising insulin drives uptake and glycogenesis, buffering the systemic blood glucose rise"],"why":"No transporter accepts anything larger than a monosaccharide, so digestion must proceed to single sugars, and doing the last step on the membrane itself means the product appears exactly where its transporter waits, leaving nothing for luminal bacteria.","week":"10"},{"title":"The defecation reflex","start":"A mass movement sweeps feces from the descending and sigmoid colon into the rectum","steps":["Stretch receptors in the rectal wall fire as the rectum distends","Signals travel to the sacral spinal cord and parasympathetic motor output returns, contracting the sigmoid colon and rectum","The same reflex relaxes the internal anal sphincter, which is smooth muscle and not under voluntary control","If the moment is appropriate, the person voluntarily relaxes the external anal sphincter, a skeletal muscle, and may raise abdominal pressure with a Valsalva maneuver to assist expulsion","If the moment is inappropriate, the external sphincter is held closed, the reflex fades within a few minutes, and the rectal wall relaxes to accommodate the volume until the next mass movement"],"why":"The two sphincters exist so that an autonomic reflex can prepare for defecation while a conscious skeletal muscle retains the final veto; continued deferral lets the colon reabsorb more water from the stored feces, which is why postponement makes stool harder.","week":"10"}]},"11":{"labs":[{"labs":[["TSH","up"],["Free T4","down"],["Free T3","down"],["Thyroid gland size","abn"]],"opts":["Secondary hypothyroidism — the anterior pituitary is failing","Primary hyperthyroidism","Primary hypothyroidism — the thyroid gland itself is failing","Normal euthyroid state"],"c":2,"why":"A high TSH beside low thyroid hormone proves the feedback loop is intact and shouting: the pituitary senses the low T4 and pushes TSH up, but the gland cannot answer. If the pituitary were the broken tier, TSH could not have risen at all, so the high TSH itself localizes the lesion to the gland.","week":"11"},{"labs":[["TSH","down"],["Free T4","up"],["Free T3","up"],["Basal metabolic rate","up"]],"opts":["Primary hypothyroidism","Primary hyperthyroidism — the gland is making hormone independent of TSH","Secondary hypothyroidism","Iodine-deficiency goiter"],"c":1,"why":"Thyroid hormone coming from the gland on its own still feeds back normally on the pituitary, so TSH is suppressed. The direction mismatch (tropic hormone down, target hormone up) is the fingerprint of a target gland running without its tropic signal.","week":"11"},{"labs":[["TSH","down"],["Free T4","down"],["ACTH","down"],["LH and FSH","down"]],"opts":["Primary hypothyroidism","Graves disease","Normal aging","Secondary hypothyroidism — anterior pituitary failure"],"c":3,"why":"Low T4 should be a maximal stimulus for TSH; a low TSH at that moment is inappropriate and moves the fault up one tier. Several trophic hormones failing together points at the anterior pituitary rather than at four separate target glands.","week":"11"},{"labs":[["PTH","up"],["Serum calcium","up"],["Serum phosphate","down"],["Urine calcium","up"],["Bone density","down"]],"opts":["Primary hyperparathyroidism","Hypoparathyroidism","Vitamin D deficiency","Calcitonin excess"],"c":0,"why":"A high calcium should switch chief cells off through their calcium-sensing receptors; PTH staying high there is the inappropriate finding. PTH pulls calcium out of bone and reclaims it in the distal tubule while blocking phosphate reabsorption, so calcium and phosphate move in opposite directions.","week":"11"},{"labs":[["PTH","down"],["Serum calcium","down"],["Serum phosphate","up"],["Chvostek sign","abn"]],"opts":["Primary hyperparathyroidism","Normal post-operative recovery","Hypoparathyroidism from surgical injury to the parathyroids","Hyperthyroidism"],"c":2,"why":"Low calcium is the strongest stimulus chief cells ever receive, so a low PTH beside it means the cells are gone or injured. Phosphate climbs because PTH's phosphate-wasting action on the tubule is lost, and low ionized calcium destabilizes nerve membranes, producing the twitch on facial nerve tapping.","week":"11"},{"labs":[["Blood glucose","up"],["Serum insulin","down"],["C-peptide","down"],["Serum ketones","up"],["Urine glucose","abn"]],"opts":["Type 2 diabetes with insulin resistance","Type 1 diabetes — beta cells destroyed","Normal fed state","Insulinoma"],"c":1,"why":"C-peptide is cleaved off proinsulin and released in equal amounts with insulin, so it reports what the beta cell itself produced; low C-peptide means no endogenous production. Without insulin restraining adipose lipolysis, the liver turns fatty acids into ketones, and glucose above the renal threshold spills into urine.","week":"11"},{"labs":[["Blood glucose","up"],["Serum insulin","up"],["C-peptide","up"],["Serum ketones","n"]],"opts":["Type 1 diabetes","Fasting hypoglycemia","Type 2 diabetes — target cell insulin resistance","Glucagon deficiency"],"c":2,"why":"The beta cells are working hard, so the defect must be downstream at the receptor and GLUT4 insertion step. Enough insulin still reaches adipose tissue to hold lipolysis in check, which is why ketones stay normal even while glucose is high.","week":"11"},{"labs":[["Blood glucose","n"],["Serum insulin","down"],["Serum glucagon","up"],["Liver glycogen","down"]],"opts":["Normal overnight fasting counter-regulation","Type 1 diabetes","Insulin overdose","Cushing syndrome"],"c":0,"why":"The normal glucose is the discriminating clue: the loop succeeded. Falling glucose switches beta cells off and alpha cells on, and glucagon-driven glycogenolysis draws down liver glycogen to hold glucose at the set point.","week":"11"},{"labs":[["Urine volume","up"],["Urine osmolality","down"],["Serum sodium","up"],["Serum osmolality","up"],["Plasma ADH","down"]],"opts":["SIADH","Uncontrolled diabetes mellitus","Normal response after drinking two liters of water","Central diabetes insipidus — posterior pituitary ADH deficiency"],"c":3,"why":"A rising serum osmolality is the maximal stimulus for ADH release, so a low ADH there is the pathologic mismatch. With no ADH, aquaporin-2 channels never enter the collecting duct, free water is lost, and the urine stays dilute while the blood concentrates.","week":"11"},{"labs":[["Serum sodium","down"],["Serum osmolality","down"],["Urine osmolality","up"],["Plasma ADH","up"],["Urine volume","down"]],"opts":["Central diabetes insipidus","SIADH — ADH secreted when it should be switched off","Dehydration","Primary aldosteronism"],"c":1,"why":"Dilute blood should shut osmoreceptors and ADH release down completely. Instead aquaporins remain in the collecting duct, so water is retained and concentrated urine is made while the plasma is dilute — concentrated urine plus dilute blood is a combination normal physiology never produces.","week":"11"},{"labs":[["Serum cortisol","down"],["Plasma ACTH","up"],["Aldosterone","down"],["Serum potassium","up"],["Serum sodium","down"]],"opts":["Cushing syndrome","Secondary adrenal insufficiency from pituitary failure","Pheochromocytoma","Primary adrenal cortex failure (Addison disease)"],"c":3,"why":"Cortex failure removes cortisol's negative feedback, so ACTH climbs, and the same precursor peptide drives skin pigmentation. Because the zona glomerulosa is also lost, aldosterone falls and sodium is wasted while potassium is retained — a pituitary cause would leave aldosterone largely intact since it answers mainly to angiotensin II and potassium.","week":"11"},{"labs":[["Plasma epinephrine","up"],["Heart rate","up"],["Blood glucose","up"],["Serum cortisol","up"],["Serum insulin","down"]],"opts":["Type 1 diabetes","Normal sympathoadrenal plus HPA stress response","Insulin overdose","Primary hypothyroidism"],"c":1,"why":"This is a coordinated fuel-mobilization pattern rather than a gland failure. Epinephrine drives glycogenolysis and directly inhibits beta cell insulin release, while cortisol keeps gluconeogenesis running, so glucose rises with insulin deliberately held low.","week":"11"}],"pairs":[{"clue":"A gland with no duct that releases its product straight into interstitial fluid and blood capillaries.","a":"Endocrine gland","b":"Exocrine gland","why":"Exocrine glands keep the epithelial duct that carries the product to a body surface or lumen — sweat, saliva, digestive enzymes. Endocrine glands lose that duct during development, so their product must travel in blood and can act only where a matching receptor exists.","week":"11","c":0},{"clue":"The part of the pancreas that delivers amylase, lipase and trypsinogen into the duodenum.","a":"Acinar cells, the exocrine pancreas","b":"Pancreatic islets (islets of Langerhans)","why":"The pancreas is both gland types in one organ. Acini drain into the pancreatic duct system, while islets are ductless clusters making up only one to two percent of the mass and secreting into surrounding capillaries.","week":"11","c":0},{"clue":"Lipid-soluble hormone that crosses the plasma membrane and binds a receptor inside the cell to switch genes on.","a":"Steroid hormone such as cortisol, aldosterone, testosterone or estrogen","b":"Peptide hormone such as insulin or ADH","why":"Steroids are cholesterol-derived and nonpolar, so the phospholipid bilayer is no barrier at all. Their effect is new protein synthesis, which is slow to begin and long lasting; a water-soluble peptide is stopped at the membrane and must signal from outside.","week":"11","c":0},{"clue":"Hormone that binds a surface receptor and works through a G protein, adenylate cyclase and cAMP.","a":"Peptide hormone such as glucagon, ADH, TSH or ACTH","b":"Steroid hormone such as cortisol","why":"Because the message stops at the membrane, an intracellular second messenger must carry it inward, and the cascade amplifies one hormone molecule into thousands of reactions. It acts on enzymes already present, so onset is seconds to minutes and duration is short.","week":"11","c":0},{"clue":"Thyroid hormone is built from tyrosine, yet its receptor is in the nucleus and its effects last for days.","a":"It behaves like a steroid hormone","b":"It behaves like a peptide hormone","why":"T3 and T4 are amine-derived but strongly lipid soluble, so they need plasma carrier proteins to travel and they regulate transcription from nuclear receptors. Solubility, not chemical family of origin, predicts the receptor location and the time course.","week":"11","c":0},{"clue":"Hormone that inserts aquaporins into the collecting duct so that water alone is reabsorbed.","a":"ADH (vasopressin) from the posterior pituitary","b":"Aldosterone from the adrenal cortex","why":"ADH moves water without solute, so it corrects osmolality and changes serum sodium concentration. Aldosterone moves sodium out of the tubule and potassium in, with water following osmotically, so it corrects volume. Different problem, different hormone.","week":"11","c":0},{"clue":"The vascular link that carries hypothalamic releasing hormones a few centimeters to the anterior pituitary.","a":"Hypophyseal portal system","b":"Hypothalamic-hypophyseal tract","why":"A portal system is two capillary beds in series, so minute amounts of releasing hormone reach the trophic cells undiluted without circulating through the whole body. The tract is axonal rather than vascular and serves only the posterior lobe.","week":"11","c":0},{"clue":"Where ADH and oxytocin are actually manufactured.","a":"Hypothalamic supraoptic and paraventricular nuclei","b":"The posterior pituitary itself","why":"The posterior lobe is nervous tissue holding axon terminals, not secretory glandular cells, which is why it is a storage and release site rather than a true gland. Damage to the stalk can therefore cut off release even with healthy hypothalamic neurons.","week":"11","c":0},{"clue":"The hormone that lowers blood calcium by inhibiting osteoclasts.","a":"Calcitonin from thyroid parafollicular (C) cells","b":"Parathyroid hormone from parathyroid chief cells","why":"Two cell populations in the same anatomic region with opposite jobs. Calcitonin tones calcium down and matters most during childhood growth and pregnancy, while PTH is the minute-to-minute regulator whose loss, not calcitonin's, produces tetany.","week":"11","c":0},{"clue":"Adrenal cortex zone that produces aldosterone.","a":"Zona glomerulosa, the outermost layer","b":"Zona fasciculata, the middle layer","why":"Salt, sugar, sex from outside inward: glomerulosa makes mineralocorticoid, fasciculata makes cortisol, reticularis makes androgens. Only the glomerulosa carries the final enzyme for aldosterone, which is why losing ACTH spares aldosterone but wipes out cortisol.","week":"11","c":0},{"clue":"The secretory cells of the adrenal medulla are best described as modified what.","a":"Postganglionic sympathetic neurons (chromaffin cells)","b":"Steroid-secreting cortical cells","why":"They arise from neural crest and are stimulated directly by preganglionic sympathetic fibers, so they discharge in seconds and release catecholamines rather than steroids. The cortex is mesodermal and answers to a hormone, so it responds over minutes to hours.","week":"11","c":0},{"clue":"Islet cell type that secretes insulin.","a":"Beta cell","b":"Alpha cell","why":"Beta cells form the bulk of each islet and are switched on by rising glucose entering through GLUT2. Alpha cells sit toward the periphery and are switched on by falling glucose, releasing glucagon — the two respond to opposite ends of the same stimulus.","week":"11","c":0},{"clue":"Anterior pituitary hormone that causes milk to be produced.","a":"Prolactin","b":"Oxytocin","why":"Prolactin drives synthesis in the glandular alveolar cells of the breast, while oxytocin from the posterior lobe contracts the myoepithelial cells that squeeze the milk out. Production versus ejection, and two different lobes of the pituitary.","week":"11","c":0},{"clue":"The tropic hormone that directly stimulates the adrenal cortex to make cortisol.","a":"ACTH from the anterior pituitary","b":"CRH from the hypothalamus","why":"The axis has three tiers, and each hormone talks only to the next one down: the hypothalamic releasing hormone acts on the pituitary, and the pituitary tropic hormone acts on the target gland. CRH never reaches the adrenal in meaningful concentration.","week":"11","c":0},{"clue":"In the testis, LH acts on which cell population.","a":"Interstitial (Leydig) cells, which make testosterone","b":"Sustentacular (Sertoli) cells","why":"FSH together with local testosterone acts on Sertoli cells to support spermatogenesis and to release inhibin, which selectively suppresses FSH. Two pituitary gonadotropins, two different target cells, two different feedback signals.","week":"11","c":0},{"clue":"Most of growth hormone's effect on the epiphyseal plate is actually produced by what.","a":"IGF-1 (somatomedins) released by the liver","b":"Growth hormone acting directly on chondrocytes by itself","why":"GH works largely indirectly by instructing the liver to secrete IGF-1, which then drives cartilage proliferation. That is why IGF-1 is the more useful blood measure: it is stable through the day while GH is released in sharp pulses, mostly during deep sleep.","week":"11","c":0},{"clue":"Thyroid hormone must be present for epinephrine to produce its full effect on fat breakdown.","a":"Permissiveness","b":"Synergism","why":"Permissiveness means one hormone is required for a second hormone to act at all or to act fully, even though the first produces little of that effect on its own. Synergism means two hormones acting together produce a result greater than the sum of their separate effects.","week":"11","c":0},{"clue":"Stretch of the cervix triggers oxytocin, which strengthens contractions, which stretches the cervix further.","a":"Positive feedback","b":"Negative feedback","why":"The response amplifies rather than opposes the original stimulus, so the loop can only be ended by an outside event such as delivery. Almost all other endocrine control is negative feedback because its job is defending a set point.","week":"11","c":0}],"redflags":[{"s":"Two days after a total thyroidectomy, a patient reports tingling around the mouth and fingertips, and tapping over the facial nerve makes the lip twitch.","act":1,"why":"The parathyroid glands sit on the posterior thyroid and are easily bruised or removed during surgery. Falling ionized calcium destabilizes excitable membranes, letting sodium channels open at more negative voltages, so threshold shifts closer to the resting potential, so nerves fire spontaneously — tetany and eventually laryngospasm.","week":"11"},{"s":"A person with type 1 diabetes has a glucose of 480, deep rapid breathing, and a fruity odor on the breath.","act":1,"why":"With no insulin to restrain adipose lipolysis, the liver converts the flood of fatty acids into ketoacids. Blood pH falls, the respiratory center compensates by blowing off carbon dioxide, and volatile acetone is exhaled.","week":"11"},{"s":"A glucose of 42 mg/dL with confusion, sweating and a fine tremor.","act":1,"why":"Neurons store no glycogen and cannot use fatty acids, so brain function fails within minutes of low glucose. The sweating and tremor are the epinephrine counter-regulatory alarm firing on top of the neurologic changes.","week":"11"},{"s":"Blood pressure 76/48, potassium 6.2, sodium 126, with bronze pigmentation in the skin creases.","act":1,"why":"Adrenal cortex failure removes aldosterone, so sodium is wasted, potassium is retained and volume collapses, and it removes cortisol's support of vascular tone. Loss of cortisol feedback drives ACTH extremely high, and the same precursor peptide stimulates melanocytes, so the pigment is a visible readout of the broken feedback loop.","week":"11"},{"s":"A patient who has taken prednisone daily for eight months stops it abruptly and two days later is weak, nauseated and hypotensive.","act":1,"why":"Exogenous glucocorticoid suppresses CRH and ACTH, and the unstimulated zona fasciculata atrophies. Sudden withdrawal leaves no cortisol from either the drug or the gland until the axis recovers over weeks, which is why steroids must be tapered.","week":"11"},{"s":"Urine output of nine liters a day, urine that looks like water, serum sodium climbing to 152, and unrelenting thirst.","act":1,"why":"A rising serum osmolality is the strongest stimulus the osmoreceptors can give, so dilute urine at that moment means ADH or its renal response is absent. Free water is leaving faster than drinking can replace it.","week":"11"},{"s":"Serum sodium 118 with headache, nausea and confusion in a patient producing small volumes of very concentrated urine.","act":1,"why":"Water retained without solute dilutes the extracellular fluid, so water moves osmotically into brain cells and swells them inside a rigid skull. The concentrated urine beside dilute blood shows ADH is being released when it should be fully off.","week":"11"},{"s":"Resting heart rate 132, fine tremor, heat intolerance and twenty pounds of weight loss with an undetectable TSH.","act":1,"why":"Thyroid hormone up-regulates beta-adrenergic receptors and Na/K ATPase activity, so metabolic rate and catecholamine sensitivity rise together. The suppressed TSH confirms the drive is coming from the gland rather than from the pituitary.","week":"11"},{"s":"Loss of the outer half of the visual field in both eyes, together with unexplained milk production and absent periods.","act":1,"why":"The pituitary sits in the sella directly under the optic chiasm, where the medial retinal fibers cross, so an expanding pituitary mass compresses them. The same mass lifts the stalk and interrupts the dopamine that normally inhibits prolactin release.","week":"11"},{"s":"A serum cortisol drawn at 8 am is roughly three times the level drawn at 11 pm in the same healthy person.","act":0,"why":"Cortisol follows a strong diurnal rhythm set by the hypothalamic clock, peaking near waking and troughing near midnight. This is exactly why the draw time must be recorded before any cortisol value can be called abnormal.","week":"11"},{"s":"Blood glucose rises from 90 to 145 one hour after a large pasta meal and is back to 92 at two hours.","act":0,"why":"A normal postprandial excursion: glucose triggers insulin release, GLUT4 transporters move into muscle and adipose membranes, and glucose is cleared. The return to baseline is itself the proof that the feedback loop is intact.","week":"11"},{"s":"After an overnight fast, insulin is low, glucagon and cortisol are mildly elevated, and glucose is 88.","act":0,"why":"Counter-regulation working as designed — alpha cells switch on as beta cells switch off, and glycogenolysis plus gluconeogenesis hold glucose at the set point. The normal glucose is the evidence of success, not of disease.","week":"11"},{"s":"During a final exam a student has a heart rate of 118, dilated pupils, dry mouth and cold sweaty palms that settle within twenty minutes.","act":0,"why":"Preganglionic sympathetic fibers stimulate adrenal chromaffin cells to dump epinephrine, producing the classic alarm reaction. It resolves quickly because circulating catecholamines have a plasma half-life of only a couple of minutes.","week":"11"},{"s":"During labor, contractions grow progressively stronger and closer together as oxytocin levels climb.","act":0,"why":"This is the textbook positive feedback loop: cervical stretch drives oxytocin from the posterior pituitary, which strengthens the contraction and produces more stretch. It is self-limiting because delivery removes the stimulus.","week":"11"}],"chains":[{"title":"The hypothalamic-pituitary-thyroid axis correcting a falling T4","start":"Circulating free T4 drifts below the body's set point.","steps":["Hypothalamic neurons sense the low thyroid hormone and secrete TRH into the hypophyseal portal veins.","TRH arrives undiluted at the anterior pituitary and stimulates thyrotrophs to release TSH into the general circulation.","TSH binds receptors on thyroid follicular cells, driving iodide trapping, thyroglobulin uptake and hydrolysis of colloid.","T4 and T3 are released into the follicular capillaries and blood levels climb back toward the set point.","Rising T3 acts back on the hypothalamus and pituitary, shutting off TRH and TSH and closing the loop."],"why":"It explains why a pair of values, not one, localizes a thyroid problem: the target hormone reports the output, while the tropic hormone reports which tier of the axis is broken.","week":"11"},{"title":"How a steroid hormone changes a target cell","start":"Cortisol, synthesized from cholesterol in the zona fasciculata, reaches a target cell bound to a plasma transport protein.","steps":["The free fraction dissociates from its carrier and, being nonpolar, diffuses straight through the phospholipid bilayer.","Inside the cell it binds an intracellular receptor, and the hormone-receptor complex moves into the nucleus.","The complex binds a hormone response element on the DNA and acts as a transcription factor.","Specific mRNA is transcribed and carried to ribosomes, where new enzyme proteins are translated.","Those new proteins, such as gluconeogenic enzymes, alter the cell's behavior for hours to days."],"why":"It accounts for the timing signature of steroids: because the effect requires building proteins, it starts slowly and outlasts the hormone in the blood — the mirror image of a peptide's fast, brief action.","week":"11"},{"title":"How a peptide hormone works through a second messenger","start":"Blood glucose falls and glucagon reaches a liver cell, but as a water-soluble peptide it cannot cross the membrane.","steps":["Glucagon binds a G-protein-coupled receptor on the hepatocyte surface.","The activated G protein switches on adenylate cyclase within the membrane.","Adenylate cyclase converts many molecules of ATP into cAMP, the second messenger, amplifying the original signal.","cAMP activates protein kinase A, which phosphorylates enzymes already present in the cytoplasm.","Glycogen phosphorylase is activated, glycogen is broken down, and glucose leaves the hepatocyte for the blood within minutes."],"why":"The amplification cascade shows how a few hormone molecules can redirect an entire cell, and acting on pre-existing enzymes is why peptide effects begin in seconds and fade quickly.","week":"11"},{"title":"Parathyroid hormone restoring a falling blood calcium","start":"Ionized calcium in the blood falls and calcium-sensing receptors on parathyroid chief cells detect the drop.","steps":["Chief cells release stored PTH into the blood within minutes.","PTH stimulates osteoblasts, which in turn signal osteoclasts to resorb bone matrix, freeing calcium and phosphate.","In the kidney, PTH increases calcium reabsorption in the distal tubule while blocking phosphate reabsorption, so phosphate is lost in the urine.","PTH activates the renal enzyme that converts vitamin D to calcitriol, which increases calcium absorption from the small intestine.","Blood calcium returns to the set point, the calcium-sensing receptors quiet, and PTH secretion falls off."],"why":"Three target organs plus the deliberate phosphate loss are what make the PTH pattern recognizable on labs: calcium up and phosphate down at the same time can only come from PTH.","week":"11"},{"title":"Insulin release and glucose clearance after a meal","start":"A carbohydrate meal is absorbed and blood glucose rises.","steps":["Glucose enters the beta cell through the GLUT2 transporter and is metabolized, raising intracellular ATP.","The rising ATP closes ATP-sensitive potassium channels, the beta cell depolarizes, and voltage-gated calcium channels open.","Calcium influx triggers exocytosis of granules containing insulin and an equal amount of C-peptide.","Insulin binds tyrosine-kinase receptors on muscle and adipose cells, and stored GLUT4 vesicles fuse with the plasma membrane.","Glucose is taken into those cells and stored as glycogen and fat, blood glucose falls, and beta cell firing stops."],"why":"It links the blood test to the cell biology: C-peptide is co-released with insulin so it reports the beta cell's own output, and the GLUT4 step explains how a target tissue can be resistant while the beta cell is perfectly healthy.","week":"11"},{"title":"The two-speed stress response","start":"The hypothalamus registers a threat.","steps":["Preganglionic sympathetic fibers fire directly onto chromaffin cells of the adrenal medulla.","Epinephrine and norepinephrine enter the blood within seconds, raising heart rate, blood pressure and glycogenolysis while inhibiting insulin release.","In parallel the hypothalamus secretes CRH into the hypophyseal portal system, and the anterior pituitary releases ACTH.","ACTH stimulates the zona fasciculata to synthesize cortisol over the following minutes to hours.","Cortisol sustains gluconeogenesis and fat and protein catabolism, then feeds back on the hypothalamus and pituitary to terminate the response."],"why":"The medulla is wired and the cortex is chemical, so one arm is measured in seconds and the other in hours — that timing difference is the entire reason the body maintains both.","week":"11"},{"title":"ADH defending plasma osmolality during dehydration","start":"Water loss pushes plasma osmolality above its normal range of about 280 to 295 mOsm per kilogram.","steps":["Hypothalamic osmoreceptor neurons lose water, shrink, and increase their firing rate.","The signal travels down the axons of the hypothalamic-hypophyseal tract to terminals in the posterior pituitary.","Stored ADH is released by exocytosis from those axon terminals directly into the blood.","ADH binds receptors on collecting duct principal cells, which insert aquaporin-2 channels into the luminal membrane.","Water is reabsorbed into the hypertonic medulla, a small volume of concentrated urine is produced, plasma osmolality falls, and osmoreceptor firing subsides."],"why":"It shows the posterior pituitary functioning as a neural release site rather than a gland, and explains why the pairing of ADH level with urine osmolality, not either value alone, identifies a water-balance disorder.","week":"11"}]}};
